import 'dart:math';

// Helper function to check if a number is prime
bool isPrime(int n) {
  if (n <= 1) return false;
  if (n == 2 || n == 3) return true;
  if (n % 2 == 0) return false;

  for (int i = 3; i <= sqrt(n); i += 2) {
    if (n % i == 0) return false;
  }
  return true;
}

void main() {
  int count = 0;
  int num = 2;

  while (count < 10) {
    if (isPrime(num)) {
      print(num);
      count++;
    }
    num++;
  }
}
