import 'dart:convert';

class Candidate {
  final String name;
  final int score;

  const Candidate(this.name, this.score);
}

List<Candidate> topCandidates(List<Map<String, dynamic>> data) {
  if (data.isEmpty) return [];

  // Parse the data into a list of Candidates
  List<Candidate> candidates = data.map((item) => Candidate(item['name'] as String, item['score'] as int)).toList();

  // Sort by score descending and then alphabetically for ties
  candidates.sort((a, b) {
    if (b.score != a.score) {
      return b.score - a.score; // Descending order
    } else {
      return a.name.compareTo(b.name); // Alphabetical order
    }
  });

  // Take the first three highest scorers or all if less than three
  int takeCount = math.min(3, candidates.length);
  return candidates.take(takeCount).toList();
}
