// Helper function to calculate the distance between two points in 3D space.
double _distanceBetweenPoints(Point3 a, Point3 b) {
  return (a - b).length;
}

class Assembly {
  final List<Point3> vertices = [];
  final List<List<int>> faces = [];

  // Adds a vertex to the assembly.
  void addVertex(double x, double y, double z) {
    vertices.add(Point3(x, y, z));
  }

  // Adds a face defined by three vertices indices.
  void addFace(int v1, int v2, int v3) {
    faces.add([v1, v2, v3]);
  }

  // Calculates and returns the total surface area of all faces in the assembly.
  double getSurfaceArea() {
    double totalArea = 0.0;

    for (final face in faces) {
      if (face.length != 3) continue; // Skip invalid faces.

      final p1 = vertices[face[0]];
      final p2 = vertices[face[1]];
      final p3 = vertices[face[2]];

      // Calculate vectors along two edges from point p1.
      final vectorA = p2 - p1;
      final vectorB = p3 - p1;

      // Cross product of vectorA and vectorB gives a normal vector perpendicular to the plane.
      final crossProduct = Vector3.cross(vectorA, vectorB);

      // The magnitude of the cross product divided by 2 is the area of the triangle.
      final area = crossProduct.length / 2.0;

      totalArea += area;
    }

    return totalArea;
  }
}
