        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: <Widget>[
            AnimatedBuilder(
              animation: _animation,
              builder: (context, _) {
                return Transform.translate(
                  offset: Offset(30 * (_animation.value - 1), 40 * (_animation.value - 1)),
                  child: IconButton(
                    icon: Icon(Icons.add),
