import 'package:graph/graph.dart';

void main() {
  // Create a graph from the assembly instructions.
  final graph = Graph<String, String>();

  // Parse the assembly code into nodes and edges.
  for (final line in getAssemblyLines()) {
    final parts = line.split(' ');

    if (parts.length < 2) continue;

    final sourceNode = parts[0];
    final targetNode = parts[1];

    // Add nodes to the graph.
    graph.addNode(sourceNode);
    graph.addNode(targetNode);

    // Connect the nodes with an edge labeled as the instruction.
    graph.addEdge(sourceNode, targetNode, line);
  }

  // Perform topological sorting on the graph using Kahn's algorithm.
  final sortedNodes = kahnTopoSort(graph);

  // Print the sorted nodes.
  print('Sorted nodes:');
  for (var node in sortedNodes) {
    print(node);
  }
}

// Function to simulate getting lines of assembly code.
List<String> getAssemblyLines() {
  return [
    "start A",
    "A B",
    "B C",
    "C D",
    "D end"
  ];
}
