```dart
String kahnTopoSort(Graph<String, String> graph) {
  final visited = Set<String>();
  final queue = Queue<String>();

  // Step 1: Compute in-degrees for all nodes.
  final inDegree = Map<String, int>();
  final nodes = graph.nodes;

  for (final node in nodes) {
    inDegree[node] = 0;
  }

  for (final edge in graph.edges.values) {
    final target = edge.to;
    inDegree[target] = (inDegree[target] ?? 0) + 1;
  }

  // Step 2: Initialize queue with nodes having zero in-degree.
  for (final node in nodes) {
    if (inDegree[node] == 0) {
      queue.add(node);
    }
  }

  final result = List<String>();

  while (!queue.isEmpty) {
    final current = queue.removeFirst();
    result.add(current);

    // Step 3: Process each neighbor.
    for (final edge in graph.getEdgesFrom(current)) {
      final neighbor = edge.to;
      inDegree[neighbor]--;

      if (inDegree[neighbor] == 0) {
        queue.add(neighbor);
      }
    }
  }

  // Check for cycles.
  if (result.length != nodes.length) {
    throw Exception("Graph has a cycle.");
  }

  return result.join(', ');
}
