import 'dart:math';

class Candidate {
  final int id;
  final String name;

  const Candidate({required this.id, required this.name});

  @override
  String toString() => "Candidate($id, $name)";
}

abstract class VoteStrategy {
  void vote(Candidate candidate);
}

class SimpleVoteStrategy implements VoteStrategy {
  List<Candidate> candidates = [];

  void addCandidate(Candidate candidate) {
    candidates.add(candidate);
  }

  @override
  void vote(Candidate candidate) {
    print("Voted for ${candidate.name}");
  }
}

class WeightedVoteStrategy extends SimpleVoteStrategy {
  Map<int, double> weights = {};

  void setWeight(int candidateId, double weight) {
    if (weight < 0 || weight > 1.0) throw ArgumentError('Weight must be between 0 and 1');
    weights[candidateId] = weight;
  }

  @override
  void vote(Candidate candidate) {
    var weight = weights.containsKey(candidate.id) ? weights[candidate.id]! : 0.5; // Default to 0.5 if not specified
    print("Voted for ${candidate.name} with weight $weight");
  }
}

void main() {
  // Example usage:
  var strategy = WeightedVoteStrategy();
  strategy.addCandidate(const Candidate(id: 1, name: "Alice"));
  strategy.addCandidate(const Candidate(id: 2, name: "Bob"));

  strategy.setWeight(1, 0.7); // Alice has higher weight

  strategy.vote(const Candidate(id: 1, name: "Alice")); // Voted for Alice with weight 0.7
  strategy.vote(const Candidate(id: 2, name: "Bob"));   // Voted for Bob with weight 0.5
}
