  final directory = Directory(sdPath!);

  List<FileSystemEntity> files = [];
  for (var entity in directory.listSync(recursive: true)) {
    files.add(entity);
  }

  // Filter only .wav files, or any other file type as needed
  List<FileSystemEntity> wavFiles = files.where((file) => file.path.endsWith('.wav')).toList();

  if (wavFiles.isEmpty) {
    print('No .wav files found on the SD card.');
    return;
  }

  print('\nFound ${wavFiles.length} .wav files:');
  for (int i = 0; i < wavFiles.length; i++) {
    print('${i + 1}. ${wavFiles[i].relativePath}');
