int candidate(int n, int k) {
  if (n == 0) return 0;
  int count = 1;
  while (k > 0 && n >= 2) {
    final q = n ~/ 2; // integer division to find quotient of dividing by 2
    final r = n % 2; // remainder when divided by 2
    if (r == 1) {
      k--;
    }
    n = q;
    if (k == 0) break;
    count += q + 1;
  }
  return count;
}
