int candidate(int n) {
  if (n <= 0) return 0;

  int maxVal = pow(2, n - 1).toInt();
  List<int> dp = List.filled(n + 1, 0);
  dp[0] = 1; // Base case

  for (int i = 1; i < n; i++) {
    dp[i] = (dp[i - 1] * (maxVal - i)) ~/ i;
  }

  return dp[n];
}
