import 'dart:math';

class Candidate {
  static int? solve(int n, List<int> a) {
    // Check if the input is valid
    if (n <= 0 || n != a.length) return -1;

    // Initialize variables to keep track of maximum sum and current sum
    var maxSum = 0;
    var currentSum = 0;

    for (int i = 0; i < n; i++) {
      // If adding the current element makes the currentSum negative,
      // reset it to zero as starting a new subarray from next element might be better
      if (currentSum + a[i] > a[i]) {
        currentSum += a[i];
      } else {
        currentSum = a[i];
      }

      // Update the maximum sum found so far
      if (currentSum > maxSum) {
        maxSum = currentSum;
      }
    }

    return maxSum;
  }
}
