class Candidate {
  static final _maxDistance = 10.0;

  // Determine if the candidate is suitable based on their position and the target's location.
  bool isSuitableForTarget(Vector3 candidatePosition, Vector3 targetLocation) {
    double distanceToTarget = (candidatePosition - targetLocation).length;

    return distanceToTarget <= _maxDistance && !isInDanger(candidatePosition);
  }

  // Check if the candidate is in danger based on nearby threats.
  bool isInDanger(Vector3 candidatePosition) {
    for (final threat in getThreats()) {
      double distanceToThreat = (candidatePosition - threat.position).length;

      if (distanceToThreat < threat.radius) {
        return true; // The candidate is within a threat's radius.
      }
    }

    return false; // No immediate danger detected.
  }

  // Retrieve a list of potential threats to consider.
  List<Threat> getThreats() {
    return [
      Threat(position: Vector3(5.0, 2.0, 0.0), radius: 2.0),
      Threat(position: Vector3(-4.0, 7.0, 0.0), radius: 1.5)
    ];
  }
}

// Represents a potential threat with its position and influence range.
class Threat {
  final Vector3 position;
  final double radius;

  Threat({required this.position, required this.radius});
}
