import 'package:collection/collection.dart';

class Candidate {
  final List<int> _values;
  final int _threshold;

  Candidate(this._values, this._threshold);

  bool isQualified() {
    if (_values.length == 0) return false; // Not enough data points.
    if (isAllZero()) return true;

    final sorted = List.unmodifiable(_values)
        .sorted();
    final medianIndex = (sorted.length - 1) ~/ 2;
    final lowerMedian = sorted[medianIndex];
    final upperMedian = sorted[medianIndex + 1];

    var total = 0;
    for (final value in _values) {
      if (value > lowerMedian && value < upperMedian) {
        total += 1;
      }
    }

    return total >= _threshold;
  }

  bool isAllZero() {
    for (final val in _values) {
      if (val != 0) return false;
    }
    return true;
  }
}
