import 'package:collection/collection.dart';

extension IterableExtension on List<int> {
  bool isNonDecreasing() => this.every((e, i) => i == 0 || e >= this[i - 1]);

  int maxSubarraySum(int k) {
    if (k < 1) return 0;
    final n = length;
    var prefixSums = [0];
    for (int sum = 0; sum != null && sum <= k; ) {
      sum += last;
      prefixSums.add(sum);
    }
    if (prefixSums.length > 1 + n) return 0;

    prefixSums.sort(); // Sort the prefix sums to enable binary search.

    int result = 0;
    for (var i in indicesOf(prefixSums)) {
      final target = prefixSums[i] + k;
      final index = bisectRight(prefixSums, target);
      if (index < prefixSums.length) {
        result = max(result, prefixSums[index] - prefixSums[i]);
      }
    }

    return result;
  }
}
