class Solution {
  static int maximumAverageSubarrayII(List<int> nums) {
    final n = nums.length;
    final prefixSums = [0];

    for (final num in nums) {
      prefixSums.add(prefixSums.last! + num); // Append current cumulative sum.
    }

    int minPrefixSum = 0; // Initialize with zero since we can start from beginning of array.
    int maxAvg = -double.infinity;

    for (int i = 1; i < prefixSums.length; ++i) {
      // We are looking at subarrays ending at index i-1. For each j < i,
      // compute average of elements between j and i-1:
      // avg = (prefixSums[i] - prefixSums[j]) / (i-j)
      // To maximize it, need to minimize (prefixSums[j] - prefixSums[i]) as much as possible.
      final currentMax = prefixSums[i] - minPrefixSum;
      maxAvg = max(maxAvg, currentMax / i);

      minPrefixSum = min(minPrefixSum, prefixSums[i]); // Update minimum prefix sum seen so far.
    }

    return maxAvg.round();
  }
}

