class Candidate {
  final String name;
  int age;

  Candidate({required this.name, required this.age});

  void printInfo() {
    stdout.write('Candidate Name: $name, Age: $age\n');
  }

  static List<Candidate> loadCandidatesFromFile(String filePath) async {
    try {
      File file = File(filePath);
      if (!await file.exists()) {
        throw Exception("File not found");
      }
      List<String> lines = await file.readAsLines();
      return lines.map((line) => parseLine(line)).toList();
    } catch (e) {
      stderr.writeln(e.toString());
      exit(1); // Exit with error code
    }
    return [];
  }

  static Candidate? parseLine(String line) {
    try {
      var parts = line.split(',');
      if (parts.length < 2 || !int.tryParse(parts[0])!.isPresent ||
          !int.tryParse(parts[1])!.isPresent) {
        return null;
      }
      return Candidate(name: parts[0], age: int.parse(parts[1]));
    } catch (e) {
      stderr.writeln("Error parsing line '$line': $e");
      return null;
    }
  }
}
