import 'dart:io';

void main() {
  final stdin = stdin;
  final stdout = stdout;

  stdin.listen((event) async {
    final input = event as String?;
    if (input == null || input.trim().isEmpty) return;

    final lines = input.split('\n');
    for (final line in lines) {
      try {
        await _processLine(line);
      } catch (e, stackTrace) {
        stderr.writeln('Error processing line: $line');
        stderr.writeln(e.toString());
        stderr.writeln(stackTrace.toString());
      }
    }
  });
}

Future<void> _processLine(String line) async {
  final parts = line.split(': ');
  if (parts.length < 2) {
    throw FormatException("Invalid format");
  }

  final command = parts[0].trim();
  final args = parts[1].split(', ').map((arg) => arg.trim()).toList();

  switch (command.toLowerCase()) {
    case "add":
      final a = int.parse(args[0]);
      final b = int.parse(args[1]);
      print(a + b);
      break;
    case "subtract":
      final a = int.parse(args[0]);
      final b = int.parse(args[1]);
      print(a - b);
      break;
    case "multiply":
      final a = int.parse(args[0]);
      final b = int.parse(args[1]);
      print(a * b);
      break;
    case "divide":
      final a = int.parse(args[0]);
      final b = int.parse(args[1]);
      if (b != 0) {
        print(a ~/ b);
      } else {
        throw Exception("Division by zero is not allowed.");
      }
      break;
    default:
      throw FormatException("Unknown command: ${command}");
  }
}
