    // Get a list of candidate entries from the results map
    final candidatesList = _results.entries.map((entry) {
      final candidateName = entry.key;
      final candidateScore = entry.value['score'];

      // Ensure we have valid data before creating a Candidate instance
      if (candidateScore is! num || candidateScore <= 0) {
        throw FormatException('Invalid score value for $candidateName');
      }

      return Candidate(name: candidateName, score: candidateScore);
    }).whereType<Candidate>().toList();

    // Sort candidates by score in descending order
    candidatesList.sort((a, b) => b.score.compareTo(a.score));

    // Return first 3 candidates or less if not enough
    return candidatesList.take(3).toList();
  }

  @override
  String toString() {
    return "ElectionResult{_results: $_results}";
  }
}

