class Location {
  final double latitude;
  final double longitude;

  const Location({required this.latitude, required this.longitude});

  factory Location.fromLatLng(double lat, double lng) => Location(
    latitude: lat,
    longitude: lng,
  );

  static bool isApproximatelyEqual(Location a, Location b, {double tolerance = 1e-5}) {
    return (a.latitude - b.latitude).abs() <= tolerance && 
           (a.longitude - b.longitude).abs() <= tolerance;
  }

  static List<Location> getPointsOnCircleFromCenter({
    required Location center,
    required int totalSteps,
    required double stepAngleInDegrees,
    bool clockwise = true,
  }) {
    if (totalSteps < 2 || stepAngleInDegrees == 0.0) {
      throw ArgumentError('Invalid parameters for generating points on circle');
    }

    final stepsPerQuadrant = totalSteps / 4;
    final angleStep = stepAngleInDegrees * (clockwise ? 1 : -1);

    List<Location> result = [];
    for(int i=0; i<stepsPerQuadrant; i++) {
      final angleRad = radians(center.longitude + i * angleStep);
      final x = _EARTH_RADIUS * cos(angleRad);
      final y = _EARTH_RADIUS * sin(angleRad);

      result.add(Location.fromLatLng(
        center.latitude + (i * 2) * (pi/2),
        center.longitude + i * angleStep
      ));
    }

    return result;
  }

  @override
  String toString() {
    return "Location(latitude=$latitude, longitude=$longitude)";
  }
