// This is a basic 3D vector math library that includes functions to add, subtract,
// multiply vectors with scalars and other vectors. It also has some helper methods for normalization.

class Vector {
  final double x;
  final double y;
  final double z;

  const Vector(this.x, this.y, this.z);

  // Adds two vectors together.
  static Vector operator +(Vector v1, Vector v2) => 
    Vector(v1.x + v2.x, v1.y + v2.y, v1.z + v2.z);

  // Subtracts one vector from another.
  static Vector operator -(Vector v1, Vector v2) =>
      Vector(v1.x - v2.x, v1.y - v2.y, v1.z - v2.z);

  // Multiplies a vector by a scalar value.
  static Vector operator *(double scale, Vector v) =>
      Vector(scale * v.x, scale * v.y, scale * v.z);

  // Returns the length of the vector (magnitude).
  double get magnitude => sqrt(x*x + y*y + z*z);

  // Normalizes the vector so its magnitude becomes 1 while maintaining direction.
  Vector normalize() {
    if(magnitude == 0) throw new Exception("Cannot normalize zero-length vector");
    return this / magnitude;
  }

  // Computes the dot product between two vectors.
  static double dot(Vector v1, Vector v2) => 
    v1.x*v2.x + v1.y*v2.y + v1.z*v2.z;

  // Computes the cross product between two vectors.
  static Vector cross(Vector v1, Vector v2) => 
    Vector(
        v1.y*v2.z - v1.z*v2.y,
        v1.z*v2.x - v1.x*v2.z,
        v1.x*v2.y - v1.y*v2.x
    );

  @override
  String toString() => "($x, $y, $z)";
}

void main() {  
  var v1 = Vector(1, 2, 3);
  var v2 = Vector(4, 5, 6);  

  print('v1 = ${v1}');
  print('v2 = ${v2}');
  print('v1 + v2 = ${v1 + v2}');
  print('v1 - v2 = ${v1 - v2}');
  print('v1 * 2 = ${v1 * 2}');  
  print('Magnitude of v1 = ${v1.magnitude}');
  print('Normalized v1 = ${v1.normalize()}');
  print('Dot Product of v1 & v2 = ${Vector.dot(v1,v2)}');
}
