import 'package:vector_math/vector_math.dart';

// Define the main function to run the simulation
void main() {
  // Initialize a list of particles with random positions and velocities
  final List<Particle> particles = List.generate(10, (index) => Particle());

  // Set up the simulation loop
  runApp(() {
    var timeStep = 0.0;

    while (true) {
      for (var particle in particles) {
        particle.updatePosition(timeStep);
      }

      // Check for collisions between any pair of particles
      for (int i = 0; i < particles.length; ++i) {
        for (int j = i + 1; j < particles.length; ++j) {
          if (!particles[i].checkCollision(particles[j])) continue;

          // If collision is detected, swap their velocities
          final tempVelocity = particles[i].velocity.copy();
          particles[i].velocity = particles[j].velocity;
          particles[j].velocity = tempVelocity;
        }
      }

      // Update the screen display
      renderParticles(particles);

      // Increment the time step
      timeStep += 0.05;
    }
  });
}

// Define the Particle class representing each ball
class Particle {
  late Vector2 position;
  late Vector2 velocity;
  static const double radius = 20.0;

  // Constructor initializes the position and velocity randomly
  Particle() : super() {
    this.position = Vector2.random(); 
    this.velocity = Vector2.random();
  }

  void updatePosition(double timeDelta) {
    position += velocity * timeDelta;
  }

  bool checkCollision(Particle other) {
    return distanceTo(other) <= radius * 2.0;
  }

  double distanceTo(Particle other) {
    return position.distanceTo(other.position);
  }
}

// Function to render the current state of the simulation on-screen
void renderParticles(List<Particle> particles) {
  stdout.write('\x1B[2J'); // Clear console

  int width = 80;
  int height = 40;

  for (int y = 0; y < height; ++y) {
    String line = '';

    for (int x = 0; x < width; ++x) {
      bool hasParticle = false;

      for (final p in particles) {
        if (p.position.x.floor() == x && p.position.y.floor() == y) {
          hasParticle = true;
          break;
        }
      }

      line += hasParticle ? '@' : '.';
    }

    print(line);
  }
}
```

The provided code defines a simple particle simulation that models balls moving around on a grid, colliding elastically when they touch. Here's how it works:

1. It creates a list of `Particle` objects, each with its own position and velocity.
2. In the main loop:
   - Each particle updates its position based on its velocity.
   - The code checks every possible pair of particles for collisions by comparing their distances.
   - When two particles collide, their velocities are swapped, simulating an elastic collision.
   - Finally, the simulation renders the current state of the system on the terminal.

This implementation uses basic vector math for movement and collision detection, but lacks features like boundaries or more realistic physics calculations.

