List<Candidate> parseCandidates(String input) {
  if (input.isEmpty || !input.contains('candidates')) return [];

  final candidates = <Candidate>[];
  final lines = input.split('\n');

  for (var line in lines) {
    if (!line.startsWith('candidate') && !line.startsWith('candidates')) continue;

    // Extract the candidate data from the line
    var parts = line.split(':').skip(1).first.trim().split(', ');

    var name = '';
    var votes = 0;

    for (final part in parts) {
      if (part.contains('Name:')) {
        name = part.replaceFirst('Name:', '').trim();
      } else if (part.contains('Votes:')) {
        votes = int.parse(part.replaceFirst('Votes:', '').trim());
      }
    }

    if (name.isNotEmpty && votes > 0) {
      candidates.add(Candidate(name: name, votes: votes));
    }
  }

  return candidates;
}
