import 'dart:async';
import 'dart:convert';
import 'dart:io';
import 'package:yaml/yaml.dart';

class ConfigParser {
  static Future<Map<String, dynamic>> readConfig(String path) async {
    try {
      final file = File(path);
      if (!await file.exists()) throw Exception("File not found");

      final contents = await file.readAsString();
      final configMap = loadYaml(contents);
      return Map.castFrom(configMap as Map<dynamic, dynamic>);
    } catch (e) {
      print('Error parsing configuration file: $e');
      rethrow;
    }
  }

  static void validateKeys(Map<String, dynamic> config, List<String> requiredFields) {
    for (final field in requiredFields) {
      if (!config.containsKey(field)) {
        throw ArgumentError("Missing required field '$field'");
      }
    }
  }
}

void main() async {
  // Example usage:
  const String configPath = "path/to/config.yaml";

  try {
    final config = await ConfigParser.readConfig(configPath);

    // Validate necessary fields here...
    ConfigParser.validateKeys(
      config,
      ['database', 'api_key', 'environment']
    );

    print("Configuration loaded successfully.");
    print(jsonEncode(config));
  } catch (e) {
    print("Failed to load configuration: $e");
  }
}
