double computeAverageAge(List<Candidate> candidates) {
  if (candidates.isEmpty) {
    throw Exception('Cannot compute average age for an empty list');
  }

  // Calculate total age and divide by number of candidates
  double totalAge = candidates.fold(0.0, (sum, candidate) => sum + candidate.age);
  return totalAge / candidates.length;
