import 'package:graph/graph.dart';

class Candidate {
  final int id;
  final String name;

  const Candidate({required this.id, required this.name});

  @override
  String toString() => '$name (ID: $id)';
}

// Helper function to create a graph from the assembly data.
Graph<Candidate> buildGraph(List<List<String>> edges) {
  Graph<Candidate> graph = Graph();

  for (var edge in edges) {
    if (edge.length < 2) continue; // Skip invalid entries

    final sourceName = edge[0];
    final targetName = edge[1];

    // Create nodes if they don't exist
    var sourceNode = graph.getOrAdd(Candidate(id: -1, name: sourceName));
    var targetNode = graph.getOrAdd(Candidate(id: -1, name: targetName));

    // Add directed edge with default weight of 1.0
    graph.addEdge(sourceNode, targetNode);
  }

  return graph;
}
```

