import 'dart:math' show Random;

int candidate(int n, int m, int k) {
  if (n == 0 || m == 0 || k <= 0) return 0;

  var dp = List<List<int>>.generate(n + 1, (_) => List.filled(m + 1, 0));

  // Initialize base cases
  for (var i = 0; i <= n; i++) {
    dp[i][0] = 1;
  }

  for (var j = 0; j <= m; j++) {
    dp[0][j] = 1;
  }

  for (var i = 1; i <= n; i++) {
    for (var j = 1; j <= m; j++) {
      dp[i][j] = dp[i - 1][j];

      if (i >= k && j > k) {
        dp[i][j] += dp[i - k][j - k];
      }
    }
  }

  return dp[n][m];
}

