import 'dart:math';

int candidate(List<int> nums) {
  int n = nums.length;
  if (n == 0) return -1;

  for (int i = 0; i < n; i++) {
    int count = 0;
    for (int j = 0; j < n; j++) {
      if (nums[j] == nums[i]) {
        count++;
      }
    }

    if (count > n / 2) {
      return nums[i];
    }
  }

  return -1;
}
