List<Candidate> parseCandidates(String input) {
  List<Map<String, dynamic>> entries = [];

  // Split the input into lines and process each line
  for (String line in input.split('\n')) {
    if (line.trim().isNotEmpty && !line.startsWith('Candidate Name') && !line.startsWith('Score')) {
      Map<String, dynamic> entry = {};
      var parts = line.split(':');
      if (parts.length == 2) {
        entry['name'] = parts[0].trim();
        entry['score'] = int.tryParse(parts[1].trim()) ?? 0; // Default to 0 if parsing fails
      } else {
        // Handle cases where there might be extra spaces or formatting issues
        var trimmedLine = line.trim();
        var lastSpaceIndex = trimmedLine.lastIndexOf(' ');
        if (lastSpaceIndex != -1) {
          entry['name'] = trimmedLine.substring(0, lastSpaceIndex);
          entry['score'] = int.tryParse(trimmedLine.substring(lastSpaceIndex + 1)) ?? 0;
        }
      }
      entries.add(entry);
    }
  }

  // Convert list of maps to list of Candidate objects
  return entries.map((e) => Candidate.fromJson(e)).toList();
}
