    // Convert each candidate's name to uppercase and remove whitespace
    for (int i = 0; i < length; ++i) {
      var currentName = name.trim().toUpperCase();
      var originalName = name;

      // Find the index of the first occurrence where the current candidate has a different name than their previous version after trimming/uppercase conversion
      while (i > 0 && _getNameWithoutWhitespaceAndUpperCase(originalName) != 
