final _getProcAddress = DynamicLibrary.process().lookupFunction(
  Pointer.fromFunction<Pointer Function(Pointer, Int32)>('GetProcAddress'),
);

// Load a DLL and get its handle
DynamicLibrary loadDll(String dllPath) {
  final libraryHandle = DynamicLibrary.open(dllPath);
  if (libraryHandle == null || !libraryHandle.isLoaded) {
    throw Exception("Failed to load DLL from path '$dllPath'");
  }
  return libraryHandle;
}

// Get an exported address of a function in a loaded DLL.
Pointer getProcAddressFromDLL(DynamicLibrary lib, String functionName) {
  final funcNamePtr = Utf8.toUtf8(functionName.codeUnits).cast<Utf8>();
  try {
    // Use the real GetProcAddress here. For demonstration, we assume this is available on Windows.
    final procAddress = _getProcAddress(lib.handle, functionName.length.toInt());
    if (procAddress.address != 0) {
      return procAddress;
    } else {
      throw Exception("Could not find function $functionName in DLL.");
    }
  } catch (e) {
    rethrow;
  } finally {
    Utf8.free(funcNamePtr);
  }
}
