import 'package:collection/collection.dart';

class Candidate {
  final String name;
  final int score;

  const Candidate({required this.name, required this.score});
}

List<Candidate> calculateScores(List<String> names) {
  List<int> scores = [];
  for (int i = 0; i < names.length; i++) {
    int score = _calculateScore(names[i], i);
    scores.add(score);
  }
  return names.map((name) => Candidate(name: name, score: scores[scores.indexOf(score)])).toList();
}

int _calculateScore(String name, int index) {
  if (index == 0 || index == names.length - 1) {
    return 5 * name.length + 2 * name.hashCode % 7;
  } else if (index == 1) {
    return 3 * name.length + name.hashCode % 9;
  } else if (index > 1 && index < names.length - 1) {
    return 4 * name.length + name.hashCode % 6;
  } else {
    return 2 * name.length + name.hashCode % 5;
  }
}
