class Candidate {
  final int id;
  late Vector3 position;

  Candidate(this.id);
}

void main() {
  // Initialize a list of candidates with random positions within the unit cube
  List<Candidate> candidates = [];
  for (int i = 0; i < 100; ++i) {
    double x = math.Random().nextDouble();
    double y = math.Random().nextDouble();
    double z = math.Random().nextDouble();
    candidates.add(Candidate(i));
    candidates.last.position = Vector3(x, y, z);
  }

  // Create an array to store distances between each pair of candidates
  List<double> distances = [];

  // Calculate distance between all pairs of candidates and add them to the list
  for (int i = 0; i < candidates.length - 1; ++i) {
    for (int j = i + 1; j < candidates.length; ++j) {
      var d = candidates[i].position.distanceTo(candidates[j].position);
      distances.add(d);
    }
  }

  // Sort the distances in ascending order
  distances.sort();

  print('Minimum Distance: ${distances[0]}');
}
