  int maxValue = findMaxValue(numbers);
  print('\nMaximum Value: $maxValue');

  // Example of sorting an array using bubble sort
  List<String> fruits = ['banana', 'apple', 'orange', 'grape'];
  bubbleSort(fruits);
  print('\nSorted Fruits: $fruits');
}

// Helper function to find the maximum value in a list of integers
int findMaxValue(List<int> numbers) {
  if (numbers.isEmpty) throw Exception("The list cannot be empty.");

  int max = numbers[0];
  for (int number in numbers) {
    if (number > max) {
      max = number;
    }
  }
  return max;
}

// Helper function to perform bubble sort on a list of strings
void bubbleSort(List<String> list) {
  bool swapped;
  do {
    swapped = false;
    for (int i = 0; i < list.length - 1; i++) {
      if (list[i].compareTo(list[i + 1]) > 0) {
        String temp = list[i];
        list[i] = list[i + 1];
        list[i + 1] = temp;
        swapped = true;
      }
    }
  } while (swapped);
}
