List<Candidate> parseCandidates(String input) {
  List<Map<String, dynamic>> data = [];

  // Split the input into lines and process each line
  for (String line in input.split('\n')) {
    if (line.trim().isNotEmpty && !line.startsWith('//')) {
      Map<String, dynamic> candidateData = {};
      try {
        for (final part in line.split(',').map((part) => part.trim())) {
          if (part.contains(':')) {
            var keyValue = part.split(':');
            String key = keyValue[0].trim();
            String value = keyValue[1].trim();

            if (key == 'name') {
              candidateData[key] = value;
            } else if (key == 'score') {
              candidateData[key] = int.parse(value);
            }
          }
        }

        if (candidateData.containsKey('name') && candidateData.containsKey('score')) {
          data.add(candidateData);
        }
      } catch (e) {
        print("Error parsing line '$line': $e");
      }
    }
  }

  return data.map((json) => Candidate.fromJson(json)).toList();
}
