String encrypt(String input) {
  final key = "secretkey";
  String result = '';
  int keyIndex = 0;

  for (var c in input.split('')) {
    var codeUnit = c.codeUnits.first;
    var keyCodeUnit = key[keyIndex % key.length].codeUnits.first;

    // XOR operation with the current character and the corresponding key character
    int encryptedCodeUnit = codeUnit ^ keyCodeUnit;
    result += ascii.decode([encryptedCodeUnit]);

    keyIndex++;
  }

  return result;
