Future<void> main(List<String> args) async {
  // Read input from stdin
  final List<String> lines = await File(stdin.readLinesSync()).map((line) => line.trim()).toList();

  if (lines.isEmpty) {
    print('No data provided.');
    exit(0);
  }

  try {
    final Map<String, dynamic> rootJson = json.decode(lines[0]);

    // Validate structure and extract candidates list
    if (!rootJson.containsKey('candidates') || 
        !(rootJson['candidates'] is List)) {
      throw Exception("Invalid JSON format - missing or invalid 'candidates' field");
    }

    final List<dynamic> candidateDataList = rootJson['candidates'];

    if (candidateDataList.isEmpty) {
      print("No candidates found in the data.");
      exit(0);
    }

    // Process each candidate's data
    for (final entry in candidateDataList) {
      if (!(entry is Map<String, dynamic>) || !entry.containsKey('name')) {
        throw Exception("Invalid entry in candidates list");
      }

      final String name = entry['name'] as String;
      final double? rawScore = entry['score'];

      if (rawScore == null || rawScore < 0 || rawScore > 100) {
        throw Exception("Invalid score value for candidate '$name'");
      }

      final int score = rawScore.round();
      final Candidate candidate = Candidate(name: name, score: score);

      // Display formatted output
      print('${candidate.name.padRight(25)} | Score: ${candidate.score}');
    }

    stdout.write('\n');
  } catch (e, stackTrace) {
    stderr.writeln('Error processing data:');
    stderr.writeln(e.toString());
    stderr.writeln(stackTrace.toString());
    exit(1);
  }
}
