    );

    print('\nGrouped by first letter:');
    for (var entry in groupedByNameInitial.entries) {
      print('${entry.key.toUpperCase()} - ${entry.value.length} candidates');
    }
  } catch (e) {
    print('Error: $e');
  }
}

// Helper function to group list elements by key extractor
List<Grouped<T, K>> groupedListBy<T, K>(Iterable<T> items, T Function(T item) keySelector) {
  if (items.isEmpty) return [];

  var result = <K, List<T>>{};
  for (T item in items) {
    K key = keySelector(item);
    if (!result.containsKey(key)) {
      result[key] = [];
    }
    result[key]!.add(item);
  }

  return result.entries.map((e) => Grouped(e.key, e.value)).toList();
}

class Grouped<K, V> {
  final K key;
  final List<V> values;

  Grouped(this.key, this.values);
}
