class AssemblyCode {
  final int op;
  final String label;

  AssemblyCode({required this.op, required this.label});
}

// Convert the given assembly to Dart source code
List<AssemblyCode> convertToDartSource(List<String> lines) {
  List<AssemblyCode> result = [];

  for (String line in lines) {
    if (line.trim().isEmpty || line.startsWith(';')) continue; // Skip empty or comment lines

    var parts = line.split(' ');
    var op = parts[0].trim();
    var label = parts.length > 1 ? parts[1].trim() : '';

    if (label.isNotEmpty && label.endsWith(':')) {
      label = label.substring(0, label.length - 1);
    }

    result.add(AssemblyCode(op: int.parse(op), label: label));
  }
  return result;
}
