// Helper function to convert a hexadecimal string to an integer.
int hexToInteger(String s) {
  int result = 0;
  for (var i = 0; i < s.length; i++) {
    final c = s[i];
    if ('0' <= c && c <= '9') {
      result = result * 16 + int.parse(c);
    } else if ('a' <= c && c <= 'f') {
      result = result * 16 + (c.codeUnitAt(0) - 'a'.codeUnitAt(0) + 10);
    } else if ('A' <= c && c <= 'F') {
      result = result * 16 + (c.codeUnitAt(0) - 'A'.codeUnitAt(0) + 10);
    }
  }
  return result;
}

