#include <stdint.h>
#include <stdlib.h>

extern "C" void _executeAssemblyCode(void* cpu) {

    uint8_t opcodes[] = {
        0x48, 0x31, 0xC0,   // XOR RAX, RAX (clear register)
        0xB8, 0xDE, 0xAD, 0xBE, 0xEF,  // MOV EAX, DEADBEEF
        0xFF, 0xD0          // CALL RAX (call function at address in RAX)
    };

    asm volatile(
        "movq %0, %%rax\n"
        "xorq %%rax, %%rax\n"
        "mov $0xDEADBEEF, %%eax\n"
        "call *%%rax"
        :
        : "r"(opcodes)
        : "%rax", "%eax"
    );
}
