void _processInput(String line) {
  if (line.trim().isEmpty) return;

  try {
    // Split the input by spaces and convert each part to integer
    final List<int> nums = line.split(' ').map(int.parse).toList();

    // Determine if all even or all odd
    bool isEven = nums.every((num) => num % 2 == 0);
    bool isOdd = nums.every((num) => num % 2 != 0);

    if (isEven && isOdd) {
      print("Mixed");
    } else if (isEven) {
      print("Even");
    } else {
      print("Odd");
    }
  } on FormatException catch (_) {
    print("Invalid input format. Please provide valid integers separated by spaces.");
  } on Exception catch (_) {
    print("An error occurred processing your input.");
  }
