String candidate(Iterable<String> lines) {
  final countMap = <String, int>{};
  for (final line in lines) {
    if (line.trim().isNotEmpty) {
      countMap[line.trim()] = (countMap[line.trim()] ?? 0) + 1;
    }
  }

  // Sort by frequency descending, then lexicographically ascending
  final sortedEntries = countMap.entries.toList()
      .sorted((a, b) => a.value.compareTo(b.value) * -1 == 0 ? a.key.compareTo(b.key) : a.value.compareTo(b.value));

  final result = StringBuffer();

  for (var i = 0; i < sortedEntries.length && i < 5; ++i) {
    final entry = sortedEntries[i];
    result.write('${entry.key} ${entry.value}\n');
  }

  return result.toString();
}
