import 'dart:io';

void main() {
  final String input = stdin.readLinesSync().join('\n');

  try {
    final List<String> lines = input.split('\n').map((line) => line.trim()).toList();

    if (lines.isEmpty) {
      print('No input provided.');
      return;
    }

    int totalCharacters = 0;
    int totalWords = 0;
    int totalSentences = 0;

    for (int i = 0; i < lines.length; ++i) {
      final String currentLine = lines[i];

      // Count characters, including spaces and punctuation
      totalCharacters += currentLine.length;

      // Split into words using whitespace as delimiter
      final Iterable<String> words = currentLine.split(RegExp(r'\\s+'));
      totalWords += words.where((word) => word.isNotEmpty).length;

      // Count sentences by splitting on '.!?'
      final RegExp sentenceSplitter = RegExp(r'[.!?]');
      final Iterable<String> sentences = currentLine.split(sentenceSplitter);
      totalSentences += sentences.where((sentence) => sentence.isNotEmpty).length;
    }

    print('Total Characters: $totalCharacters');
    print('Total Words: $totalWords');
    print('Total Sentences: $totalSentences');
  } catch (e) {
    print('Error processing input: $e');
  }
}
