import 'dart:io';

class Candidate {
  final String name;
  int score;

  const Candidate({required this.name, required this.score});

  @override
  String toString() => '$name ($score)';
}

List<Candidate> parseCandidates(String input) {
  List<String> lines = input.split('\n');
  List<Candidate> candidates = [];

  for (int i = 0; i < lines.length; i++) {
    if (lines[i].isEmpty || lines[i].startsWith('#')) continue;

    String[] parts = lines[i].split(': ');
    if (parts.length != 2) continue;

    String name = parts[0];
    int score = int.tryParse(parts[1]) ?? 0;

    if (score >= 0 && score <= 100) {
      candidates.add(Candidate(name: name, score: score));
    }
  }

  return candidates;
}

void main(List<String> args) async {
  // Read the input from stdin
  String input = await File('candidates.txt').readAsString();

  List<Candidate> candidates = parseCandidates(input);

  // Sort by score descending and then alphabetically
  candidates.sort((a, b) {
    int scoreComparison = b.score.compareTo(a.score);
    if (scoreComparison != 0) return scoreComparison;
    return a.name.compareTo(b.name);
  });

  print("Sorted Candidates:");
  for (Candidate candidate in candidates) {
    print(candidate.toString());
  }
}
