    await _channel.ready;
    print('Connected to $url');
  }

  void listen(Function(dynamic message) onMessage, Function(Exception e) onError) {
    _channel.stream.listen(
      (message) => onMessage(message),
      onError: (e) => onError(e),
    );
  }

  void send(data) {
    if (_channel.readyState == ReadyState.open) {
      _channel.sink.add(data);
    } else {
      throw Exception("WebSocket is not open");
    }
  }

  void close() {
    _channel.close();
  }
}
