import 'dart:io';

void main() {
  final int n = stdin.readLineSync().toInt();
  List<int> numbers = List.generate(n, (i) => i + 1);

  print('Original list:');
  for (int num in numbers) {
    stdout.write('$num ');
  }
  stdout.writeln();

  // Perform a selection sort to demonstrate sorting
  for (int i = 0; i < n - 1; i++) {
    int minIndex = i;
    for (int j = i + 1; j < n; j++) {
      if (numbers[j] < numbers[minIndex]) {
        minIndex = j;
      }
    }
    if (minIndex != i) {
      var temp = numbers[i];
      numbers[i] = numbers[minIndex];
      numbers[minIndex] = temp;
    }

    print('After iteration $i:'); 
    for (int num in numbers) {
      stdout.write('$num ');
    }
    stdout.writeln();
  }

  print('\nSorted list:');
  for (int num in numbers) {
    stdout.write('$num ');
  }
}
