import 'dart:ffi';
import 'dart:io';

// Helper function to convert a list of bytes to a string using ASCII encoding
String fromUtf8(List<int> data) {
  return String.fromCharCodes(data);
}

void main() async {
  final library = DynamicLibrary.open('libmylibrary.so');

  // Load the functions we need
  final readFromSharedMemory =
      library.lookupFunction<Pointer<Utf8Value>, Utf8Value Function()>('read_from_shared_memory');
  final writeToSharedMemory =
      library.lookupFunction<Void Function(Pointer<Utf8Value>, Int32), void Function(Utf8Value, int)>(
          'write_to_shared_memory');

  try {
    final buffer = calloc.allocate(1024); // Allocate memory for shared memory buffer
    final resultBuffer = calloc.allocate(1024);

    // Read from shared memory
    final result = readFromSharedMemory();
    if (result != null && result.address != 0) {
      final data = malloc.allocate(result.length);
      memcpy(data.cast(), result.cast(), result.length);

      // Convert and print received message
      final message = fromUtf8(data.asTypedList());
      stdout.write(message + '\n');
    } else {
      stdout.write("No data received.\n");
    }

    // Write to shared memory - send "Hello from Dart"
    final messageToWrite = "Hello from Dart";
    final encodedMessage = utf8.encode(messageToWrite);

    final size = encodedMessage.length;
    final writtenBytes = write_to_shared_memory(encodedMessage.buffer.asByteData().cast(), size);

    stdout.write("$writtenBytes bytes sent\n");
  } finally {
    calloc.free(buffer);
    calloc.free(resultBuffer);
  }
}
