void main(List<String> args) {
  if (args.isNotEmpty && args[0] == '--list') {
    List<Candidate> candidates = _readCandidatesFromInput();
    for (var candidate in candidates) {
      print(candidate);
    }
  } else {
    print("Usage: dart run --help");
  }
}

List<Candidate> _readCandidatesFromInput() {
  List<Candidate> candidates = [];
  stdin.forEach((line) {
    if (line.trim().isEmpty) return;
    var parts = line.split(',').map((part) => part.trim()).toList();
    if (parts.length != 2) return;
    var name = parts[0];
    var ageStr = parts[1];
    if (!int.tryParse(ageStr).isPresent) return;
    var age = int.parse(ageStr);
    candidates.add(Candidate(name: name, age: age));
  });
  return candidates;
}
