import 'package:collection/collection.dart';

class Candidate {
  final String name;
  int? score;

  const Candidate({required this.name});

  void updateScore(int newScore) {
    if (score != null && newScore < score!) return; // No change needed, preserve existing
    score = newScore;
  }

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is Candidate &&
          runtimeType == other.runtimeType &&
          name == other.name;

  @override
  int get hashCode => name.hashCode;

  static List<Candidate> sortCandidatesByDescendingScore(List<Candidate> candidates) {
    if (candidates.isEmpty) return [];

    // Sort by descending score and then by ascending name for stable sorting
    candidates.sort((a, b) {
      var scoreComparison = b.score!.compareTo(a.score!);
      if (scoreComparison != 0) return scoreComparison;
      return a.name.compareTo(b.name); // Tie-breaker by name
    });

    return candidates;
  }
}
