import 'package:collection/collection.dart';

class Candidate {
  final String name;
  final int score;

  const Candidate({required this.name, required this.score});

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is Candidate &&
          runtimeType == other.runtimeType &&
          name == other.name &&
          score == other.score;

  @override
  int get hashCode => Object.hash(name, score);

  @override
  String toString() => '$name ($score)';
}

List<Candidate> parseCandidates(String input) {
  final lines = input.split('\n');
  return List.from(lines.map((line) {
    if (line.trim().isEmpty || line.startsWith('#')) return null;
    final parts = line.split(':').map((part) => part.trim()).toList();
    if (parts.length < 2) throw FormatException('Invalid format');
    final name = parts[0];
    final scoreStr = parts[1].replaceAll(RegExp(r'[^0-9]'), '');
    if (!int.tryParse(scoreStr).isPresent) throw FormatException('Invalid score');
    final score = int.parse(scoreStr);
    return Candidate(name: name, score: score);
  }).whereType<Candidate>());
}
