Future<void> saveCandidate(Candidate candidate) async {
  SharedPreferences prefs = await SharedPreferences.getInstance();
  List<Candidate> candidates = (prefs.getStringList('candidates')?.map((e) => Candidate.fromJson(jsonDecode(e))) ?? [])
      .toList();

  // Find if the candidate already exists and update their score
  bool updated = false;
  for (var i = 0; i < candidates.length; i++) {
    if (candidates[i].name == candidate.name) {
      candidates[i] = candidate;
      updated = true;
      break;
    }
  }

  // If not found, add new candidate with initial score of 15
  if (!updated) {
    candidates.add(candidate);
  }

  // Save back to shared preferences
  await prefs.setStringList('candidates', candidates.map((c) => jsonEncode(c.toJson())).toList());
}

