import 'package:collection/collection.dart';

class Candidate {
  final List<int> _graph;
  final int _n;

  Candidate(this._graph, this._n);

  bool hasCycle() {
    var visited = [false] * _n;
    for (int i = 0; i < _n; i++) {
      if (!visited[i]) {
        if (_dfs(i, -1, visited)) return true;
      }
    }
    return false;
  }

  bool _dfs(int node, int parent, List<bool> visited) {
    visited[node] = true;
    for (final neighbor in _graph[node]) {
      if (neighbor == parent) continue;
      if (visited[neighbor]) {
        // Cycle detected
        return true;
      } else if (!_dfs(neighbor, node, visited)) {
        return false;
      }
    }
    return true;
  }
}
```

This code defines a `Candidate` class that checks if there's a cycle in an undirected graph represented by an adjacency list. The `hasCycle()` method uses DFS to detect cycles.

