import 'package:vector_math/vector_math.dart';

class Candidate {
  final int id;
  final String name;
  final List<Vector2> points;

  Candidate({
    required this.id,
    required this.name,
    required this.points,
  });

  double calculateScore() {
    var score = 0.0;
    for (int i = 0; i < points.length - 1; i++) {
      Vector2 p1 = points[i];
      Vector2 p2 = points[i + 1];
      // Calculate the distance between consecutive points
      double dx = p2.x - p1.x;
      double dy = p2.y - p1.y;
      double dist = sqrt(dx * dx + dy * dy);
      score += dist;
    }
    return score / (points.length - 1) * 100;
  }

  static List<Candidate> generateCandidates(int count, int pointsPerCandidate) {
    List<Candidate> candidates = [];
    for (int i = 0; i < count; i++) {
      List<Vector2> path = [];
      for (int j = 0; j < pointsPerCandidate; j++) {
        // Generate random x and y coordinates within a certain range
        double x = Random().nextDouble() * 1000;
        double y = Random().nextDouble() * 1000;
        path.add(Vector2(x, y));
      }
      candidates.add(Candidate(
        id: i,
        name: "Candidate $i",
        points: path,
      ));
    }
    return candidates;
  }

  @override
  String toString() {
    return '$name with ID: $id';
  }
}
