    final savedCandidatesJson = prefs.getString('candidates');
    if (savedCandidatesJson != null) {
      final List<dynamic> parsedCandidates =
          List.from(jsonDecode(savedCandidatesJson));
      _candidates = parsedCandidates.map((json) => Candidate.fromJson(json)).toList();
