    _candidates[index] = updatedCandidate;
    saveCandidates();
    notifyListeners();
  }

  void deleteCandidate(int index) {
    _candidates.removeAt(index);
    saveCandidates();
    notifyListeners();
  }

  void saveCandidates() async {
    final prefs = await SharedPreferences.getInstance();
    final jsonList = _candidates.map((candidate) => candidate.toJson()).toList();
    prefs.setString('candidates', jsonEncode(jsonList));
