import 'dart:io';

void main() {
  stdout.write('Enter the path to your assembly file: ');
  final String? filePath = stdin.readLineSync();

  if (filePath == null || !File(filePath).existsSync()) {
    print("Invalid file path. Please provide a valid file.");
    return;
  }

  try {
    final List<String> lines = File(filePath).readAsLinesSync();
    final int maxLineLength = lines.fold(0, (maxLen, line) => max(maxLen, line.length));

    for (int i = 0; i < lines.length; i++) {
      final String currentLine = lines[i];
      final int padding = maxLineLength - currentLine.length;

      // Check for comments starting with ';'
      if (currentLine.contains(';')) {
        final parts = currentLine.split(';');
        final instructionPart = parts[0].trim();

        if (instructionPart.isNotEmpty) {
          final paddedInstruction = '$instructionPart' + (' '.repeat(padding));
          print('$paddedInstruction;');
        } else {
          print(';' + (' '.repeat(maxLineLength)));
        }
      } else {
        print(currentLine.padRight(maxLineLength));
      }
    }
  } catch (e) {
    print("Error reading or processing the file: $e");
  }
}
