import 'dart:math';

// A simple implementation of the Sieve of Eratosthenes algorithm.
List<int> sieveOfEratosthenes(int limit) {
  if (limit < 2) return [];

  final List<bool> isPrime = List.filled(limit + 1, true);
  isPrime[0] = false;
  isPrime[1] = false;

  for (int i = 2; i * i <= limit; i++) {
    if (isPrime[i]) {
      for (var j = i * i; j <= limit; j += i) {
        isPrime[j] = false;
      }
    }
  }

  final List<int> primes = [];
  for (int i = 2; i <= limit; i++) {
    if (isPrime[i]) primes.add(i);
  }

  return primes;
}

void main() {
  // Example usage:
  final primesUpTo50 = sieveOfEratosthenes(50);

  print('Primes up to 50:');
  for (final prime in primesUpTo50) {
    stdout.write('$prime ');
  }
}
