class GroupedCandidates {
  final Map<String, List<Candidate>> _groups = {};

  void add(String groupKey, Candidate candidate) {
    if (!_groups.containsKey(groupKey)) {
      _groups[groupKey] = [];
    }
    _groups[groupKey]!.add(candidate);
  }

  Iterable<MapEntry<String, List<Candidate>>> get groups => _groups.entries;

  // Returns a list of candidates sorted by the number of groups they belong to in descending order.
  List<Candidate> sortTopMembers() {
    var groupedCountMap = <Candidate, int>{};
    for (var entry in _groups.entries) {
      for (var candidate in entry.value) {
        groupedCountMap[candidate] = groupedCountMap.putIfAbsent(candidate, () => 0) + 1;
      }
    }

    return groupedCountMap.keys.toList()
        .sort((a, b) => groupedCountMap[b]! - groupedCountMap[a]!)
        .take(3)
        .toList();
  }
}
