import 'package:graph/graph.dart';

class Candidate {
  final String name;
  final int score;

  const Candidate({required this.name, required this.score});

  @override
  String toString() => 'Candidate(name: $name, score: $score)';
}

Future<void> main() async {
  // Create a graph to represent the assembly process
  var graph = Graph<String>();

  // Add nodes for each candidate and their scores
  var candidates = [
    Candidate(name: 'Alice', score: 85),
    Candidate(name: 'Bob', score: 92),
    Candidate(name: 'Charlie', score: 76),
    Candidate(name: 'David', score: 88)
  ];

  // Connect all candidates with edges representing dependencies (e.g., higher scores depend on lower ones)
  for (var i = 0; i < candidates.length - 1; i++) {
    for (var j = i + 1; j < candidates.length; j++) {
      if (candidates[i].score > candidates[j].score) {
        graph.addEdge(candidates[i], candidates[j]);
      } else {
        graph.addEdge(candidates[j], candidates[i]);
      }
    }
  }

  // Run topological sort to determine the order of execution
  var sortedCandidates = graph.topoSort();

  print('Execution Order:');
  for (final candidate in sortedCandidates!) {
    print(candidate);
  }
}
