Future<void> loadCandidates() async {
  SharedPreferences prefs = await SharedPreferences.getInstance();
  List<Candidate>? candidates = prefs.getString('candidates')?.split(',').map((s) => Candidate.fromJson(json.decode(s))).toList();

  if (candidates == null || candidates.isEmpty) {
    // Default data
    candidates = [
      Candidate(name: "Alice", age: 30),
      Candidate(name: "Bob", age: 25)
    ];
    saveCandidates(candidates);
  }

  print("Loaded Candidates: $candidates");
}

void saveCandidates(List<Candidate> candidates) {
  SharedPreferences prefs = SharedPreferences.getInstance().then((prefs) {
    String encoded = candidates.map((c) => json.encode(c.toJson())).join(',');
    prefs.setString('candidates', encoded);
  });
}
