import 'package:collection/collection.dart';

class Candidate {
  final int id;
  final String name;

  const Candidate({required this.id, required this.name});

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is Candidate &&
          runtimeType == other.runtimeType &&
          id == other.id &&
          name == other.name;

  @override
  int get hashCode => id.hashCode ^ name.hashCode;
}

extension Candidates on List<Candidate> {
  // Sorts candidates by [name] in ascending order.
  List<Candidate> sortByName() => sorted((a, b) => a.name.compareTo(b.name));

  // Returns the candidate with the smallest ID (or first one if IDs are equal).
  Candidate? getMinIdCandidate() {
    return reduce((prev, curr) => prev.id < curr.id ? prev : curr);
  }

  // Returns the index of the candidate with given [id].
  int? findIndexById(int id) {
    for (int i = 0; i < length; ++i)
      if (this[i].id == id) return i;
    return null;
  }
}
