// Function to sort the list of candidates based on their scores using bubble sort algorithm
Future<void> sortCandidatesByScore(List<Candidate> candidates) async {
  bool swapped;
  do {
    swapped = false;
    for (int i = 0; i < candidates.length - 1; i++) {
      if (candidates[i].score > candidates[i + 1].score) {
        // Swap the elements at positions i and i+1
        Candidate temp = candidates[i];
        candidates[i] = candidates[i + 1];
        candidates[i + 1] = temp;
        swapped = true;
      }
    }
  } while (swapped);
}
