      identical(this, other) ||
          other is Candidate &&
              runtimeType == other.runtimeType &&
              name == other.name &&
              age == other.age;

  @override
  int get hashCode => Object.hash(name, age);
}

List<Candidate> filterCandidates(List<Candidate> candidates, {int? minAge}) {
  if (minAge != null && minAge < 0) return [];

  List<Candidate> filtered = candidates.where((candidate) {
    if (minAge == null || candidate.age >= minAge) {
      return true;
    } else {
      return false;
    }
  }).toList();

  return filtered;
}
