import 'package:collection/collection.dart';

class Candidate {
  final String name;
  int score;

  Candidate(this.name, this.score);

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is Candidate &&
          runtimeType == other.runtimeType &&
          name == other.name &&
          score == other.score;

  @override
  int get hashCode => Object.hash(name, score);
}

extension CandidatesExt on List<Candidate> {
  // Calculate the sum of scores for all candidates.
  int totalScore() => fold(0, (sum, candidate) => sum + candidate.score);

  // Find the highest scoring candidate(s).
  List<Candidate> topCandidates(int maxCount) {
    if (maxCount <= 0 || isEmpty) return [];

    var sorted = toList()
        .sort((a, b) => b.score.compareTo(a.score))
        .where((c) => c.score > 0)
        .toList();

    if (sorted.isEmpty) return [];
    var maxValue = sorted[0].score;
    var top = sorted.where((c) => c.score == maxValue).take(maxCount).toList();
    return top.take(min(top.length, maxCount)).toList();
  }

  // Get a list of all candidates with non-zero scores.
  List<Candidate> activeCandidates() => where((candidate) => candidate.score > 0).toList();

  // Sort by ascending order of names and descending order of scores.
  List<Candidate> sortByNameDescendingScoresAscending() {
    return this.toList().sort(
            (a, b) => a.name.compareTo(b.name) * -1
                + (b.score.compareTo(a.score)));
  }
}
