    Candidate(name: 'Charlie', score: 90),
    Candidate(name: 'David', score: 68),
    Candidate(name: 'Eve', score: 81),
  ];

  candidates.forEach((c) => graph.addNode(c.name));

  // Build the graph based on some logic (here we use scores as edges weight)
  // For example, create an edge from lower-scoring to higher-scoring candidates
  for (int i = 0; i < candidates.length - 1; i++) {
    for (int j = i + 1; j < candidates.length; j++) {
      if (candidates[i].score < candidates[j].score) {
        double strength = (candidates[j].score - candidates[i].score).toDouble();
        graph.addEdge(
          candidates[i].name,
          candidates[j].name,
          weight: strength,
        );
      }
    }
  }

  // Find the node with highest score using BFS traversal
  Node? bestCandidateNode = findBestCandidate(graph);

  print('The candidate with the highest score is ${bestCandidateNode?.value}');
}

// Helper function to find the node with the highest score via BFS traversal
Node? findBestCandidate(Graph<String> graph) {
  var queue = Queue<Node>();
  var visited = Set<String>();

  // Start BFS from any node
  for (var node in graph.nodes) {
    queue.add(node);
    visited.add(node.value);
  }

  Node? bestNode;
  while (!queue.isEmpty) {
    var current = queue.removeFirst();
    var currentScore = getScore(current.value); 

    if (bestNode == null || currentScore > getScore(bestNode.value)) {
      bestNode = current;
    }

    for (var neighbor in graph.getNeighbors(current.value)) {
      if (!visited.contains(neighbor.value)) {
        visited.add(neighbor.value);
        queue.add(neighbor);
      }
    }
  }

  return bestNode;
}

