    if (line.isNotEmpty) {
      final parts = line.split(': ');
      if (parts.length == 2 && !parts[0].isEmpty && !parts[1].isEmpty) {
        try {
          final id = int.parse(parts[0]);
          final name = parts[1];
          candidates.add(Candidate(id, name));
        } catch (_) {}
      }
    }
  }

  if (candidates.isEmpty) return null;

  return candidates;
}
