void main() async {
  final stdin = stdin;
  final stdout = stdout;

  // Read the input line by line and process it.
  await for (final line in stdin.transform(utf8.decoder).transform(const LineSplitter())) {
    if (line.isEmpty) continue;

    try {
      final result = candidate(line);
      stdout.write('$result\n');
    } catch (e, stackTrace) {
      stdout.writeln('Error processing line: $e');
      stderr.writeln(stackTrace.toString());
    }
  }
}

// Function to process each line of input.
String? candidate(String line) {
  return _processLine(line);
}

String? _processLine(String input) {
  int count = 0;

  // Split the string into characters.
  List<String> chars = input.split('');

  // Iterate through each character.
  for (int i = 0; i < chars.length - 1; i++) {
    String firstChar = chars[i];
    String secondChar = chars[i + 1];

    // Check if two consecutive identical letters exist.
    if (firstChar == secondChar) {
      count++;

      // Skip the next character as we've processed this pair.
      i += 1;
    }
  }

  // Return the total count of such pairs.
  return '$count';
}
