dynamic eval(String sourceCode, List<int> data) {
  final isolate = Isolate.spawn(
    () => _evalInIsolate(sourceCode, data),
    null,
  );

  return await Future.any([
    isolate.then((_) => throw Exception("Isolate completed normally")),
    Completer<dynamic>().future,
  ]);
}

Future<void> _evalInIsolate(String sourceCode, List<int> data) async {
  final result = await compute(() => evaluate(sourceCode, data));
  print(result);
}

T evaluate<T>(String sourceCode, List<int> data) {
  final interpreter = Interpreter();
  final context = interpreter.evaluate(sourceCode, null, []);

  final function = context['main'] as Function;
  final closure = function.createClosure(context);

  final args = data.map((b) => b.toInt()).toList(); 
  final result = closure.apply(args, null);

  return result;
}
