class Interpreter {
  dynamic evaluate(String sourceCode, String filename, List<String> options) {
    final script = Script.fromString(sourceCode);
    final context = Context.current;
    final compiledScript = compileScript(script, context);
    final evaluationResult = compiledScript.execute(context, filename, options);
    return evaluationResult.value;
  }
