  Future<void> addItem(T item);
  Future<void> updateItem(T item);
  Future<void> deleteItem(int id);
}

class InMemoryRepository<T> implements Repository<T> {
  final List<T> _items = [];

  @override
  Future<List<T>> getItems() async => [..._items];

  @override
  Future<void> addItem(T item) async {
    _items.add(item);
  }

  @override
  Future<void> updateItem(T item) async {
    // For simplicity, assume ID is used to find the item and replace it.
    final index = _items.indexWhere((e) => e.runtimeType == item.runtimeType && e.hashCode == item.hashCode);
    if (index != -1) {
      _items[index] = item;
    } else {
      throw Exception('Item not found');
    }
  }

  @override
  Future<void> deleteItem(int id) async {
    final index = _items.indexWhere((item) => item is Candidate && item.id == id);
    if (index != -1) {
      _(items).removeAt(index);
    } else {
      throw Exception('Item not found');
    }
  }
}
