void main() {
  // Create a directed graph representing the assembly process.
  final Graph<String> graph = Graph();

  // Add nodes for each component.
  graph.addNode('A');
  graph.addNode('B');
  graph.addNode('C');
  graph.addNode('D');
  graph.addNode('E');

  // Add edges to represent dependencies between components.
  graph.addEdge('A', 'B'); // A depends on B
  graph.addEdge('B', 'C'); // B depends on C
  graph.addEdge('C', 'D'); // C depends on D
  graph.addEdge('D', 'E'); // D depends on E

  // Perform topological sort to determine the correct order of execution.
  final List<String> sortedComponents = graph.topoSort().toList();

  // Print the assembly sequence in reverse (since topological sort gives predecessors first).
  print("Assembly Sequence:");
  for (final String component in sortedComponents.reversed) {
    print(component);
  }
}
