abstract class VoteStrategy<T> {
  void vote(Candidate candidate);
}

class MajorityVoteStrategy implements VoteStrategy<Candidate> {
  late Map<int, List<String>> votesByCandidateId = {};
  late Set<int> candidatesIds = {};

  @override
  void vote(Candidate candidate) {
    if (votesByCandidateId.containsKey(candidate.id)) {
      votesByCandidateId[candidate.id]!.add(candidate.name);
    } else {
      votesByCandidateId[candidate.id] = [candidate.name];
    }

    candidatesIds.add(candidate.id);
  }
}

class PluralityVoteStrategy extends MajorityVoteStrategy {
  static const double _pluralityThresholdPercentage = 50.0; // % of total votes needed to win

  @override
  void vote(Candidate candidate) {
    super.vote(candidate);

    var maxVotesCount = -1;
    int? winnerId;
    for (var id in candidatesIds) {
      var currentCount = votesByCandidateId[id]!.length;
      if (currentCount > maxVotesCount) {
        maxVotesCount = currentCount;
        winnerId = id;
      }
    }

    if (maxVotesCount * 2 >= candidatesIds.length) {
      print("Plurality threshold achieved by candidate with ID $winnerId");
    }
  }
}
