import 'package:vector_math/vector_math.dart';

class Candidate {
  final Vector3 _position;
  double get x => _position.x;
  double get y => _position.y;
  double get z => _position.z;

  const Candidate({required this._position});
}

extension CandidateExtensions on List<Candidate> {
  void moveTowardsTarget(
      {double targetX = -1.0, required int iterations}) {
    for (int i = 0; i < iterations; i++) {
      final directionVector =
          Vector3(targetX - x, 0.0, 0.0) - position;
      final distanceToTarget = directionVector.length();
      if (distanceToTarget == 0 || distanceToTarget <= 5e-4) break;
      final stepSize = min(distanceToTarget / 2.0, 1.0);
      final nextPosition = position + directionVector * stepSize;
      replaceAt(i, Candidate(nextPosition));
    }
  }

  static bool isConverged(List<double> positions,
      {double tolerance = 1.0e-6, required int maxIterations}) {
    if (positions.length != 1) return false;
    var count = 0;
    while (count++ < maxIterations) {
      final lastPosition = positions.last;
      final newPositions = [];
      for (final candidate in positions) {
        final newPosition = candidate.moveTowardsTarget(
            targetX: lastPosition, iterations: 1).first.position;
        newPositions.add(newPosition);
      }
      final changed = newPositions.any((newP) =>
          !lastPosition.isApproximatelyEqual(newP, epsilon: tolerance));
      if (!changed) break;
      positions = newPositions;
    }
    return positions.first.x.isApproximatelyZero(epsilon: tolerance) &&
        positions.first.y.isApproximatelyZero(epsilon: tolerance) &&
        positions.first.z.isApproximatelyZero(epsilon: tolerance);
  }
}
