            height: kBottomNavigationBarHeight * .75,
            padding: EdgeInsets.symmetric(horizontal: 8.0, vertical: 4.0),
            decoration: BoxDecoration(boxShadow: [BoxShadow(color: Colors.black.withOpacity(.1))]),
            child: Row(
              children: [
