void main() {
  // Read input from stdin, split into lines.
  final List<String> inputs = Platform.resolvedExecutable == null ? 
      (stdin as InputStream).readLinesSync().toList() : [];

  if (inputs.isEmpty) return;

  final int n = int.parse(inputs[0]);
  final List<int> nums = inputs.getRange(1, n + 1)
    .map(int.parse)
    .toList();

  for (int i = 0; i < n - 1; ++i) {
    for (int j = i + 1; j < n; ++j) {
      if (nums[i] > nums[j]) {
        final int temp = nums[i];
        nums[i] = nums[j];
        nums[j] = temp;
      }
    }
  }

  print(nums.join(' '));
}
