  Future<Map<String, dynamic>> fetchVoteResults() async {
    final url = Uri.parse('$baseUrl/results');

    final request = http.Request('GET', url)
      ..headers.contentType = ContentType.json;

    final streamedResponse = await httpClient.send(request);
    final response = await http.Response.fromStream(streamedResponse);

    if (response.statusCode == 200) {
      return jsonDecode(utf8.decode(response.bodyBytes));
    } else {
      throw Exception('Failed to load vote results.');
    }
  }

  Future<Candidate> findCandidateByName(String name) async {
    final candidatesUrl = Uri.parse('$baseUrl/candidates');

    final request = http.Request('GET', candidatesUrl)
      ..headers.contentType = ContentType.json;

    final streamedResponse = await httpClient.send(request);
    final response = await http.Response.fromStream(streamedResponse);

    if (response.statusCode == 200) {
      final List<dynamic> candidates = jsonDecode(utf8.decode(response.bodyBytes));

      for (final candidate in candidates) {
        if (candidate['name'] == name) {
          return Candidate.fromMap(candidate);
        }
      }
    }

    throw Exception('Candidate not found with name: $name');
  }
