import 'package:vector_math/vector_math.dart';

class Candidate {
  static void main() {
    final points = List<Vector3>.generate(10, (i) => Vector3.random2D());

    // Compute convex hull using Graham's scan algorithm
    final convexHull = computeConvexHull(points);

    print("Convex Hull Points:");
    for (final point in convexHull) {
      print("${point.x} ${point.y}");
    }
  }

  static List<Vector3> computeConvexHull(List<Vector3> points) {
    if (points.length < 3) return points;

    // Sort the points by x-coordinate
    points.sort((a, b) => a.x.compareTo(b.x));

    // Find the lowest and highest y points to start with
    int lowerLeftIndex = 0;
    int upperRightIndex = 0;
    for (int i = 1; i < points.length; i++) {
      if (points[i].y > points[upperRightIndex].y || 
          (points[i].y == points[upperRightIndex].y && points[i].x > points[upperRightIndex].x)) {
        upperRightIndex = i;
      }
      if (points[i].y < points[lowerLeftIndex].y ||
          (points[i].y == points[lowerLeftIndex].y && points[i].x < points[lowerLeftIndex].x)) {
        lowerLeftIndex = i;
      }
    }

    // Build the initial polygon starting from lower left
    final polygon = [points[lowerLeftIndex]];
    int j = lowerLeftIndex + 1 % points.length;
    while (j != lowerLeftIndex) {
      polygon.add(points[j]);
      j = (j + 1) % points.length;
    }

    // Add the upper right point back into the polygon
    polygon.removeAt(polygon.indexOf(points[upperRightIndex]));
    polygon.insert(1, points[upperRightIndex]);

    // Perform gift wrapping algorithm
    var result = [];
    int m = 0;
    do {
      result.add(polygon[m]);

      int n = 1;
      for (int k = 2; k < polygon.length; k++) {
        if (crossProduct(
            vectorFromTo(polygon[n], polygon[k]), 
            vectorFromTo(polygon[m], polygon[k])) < 0) {
          n = k;
        }
      }
      m = n;
    } while (m != result.first.indexWhere((p) => p == polygon[m]));

    return result.toList();
  }

  static Vector3 vectorFromTo(Vector3 a, Vector3 b) =>
      new Vector3(b.x - a.x, b.y - a.y, b.z - a.z);

  static double crossProduct(Vector3 u, Vector3 v) =>
      u.x * v.z - u.z * v.x;

  static bool arePointsEqual(Vector3 a, Vector3 b) =>
      a.x == b.x && a.y == b.y && a.z == b.z;
}
