  int get hashCode => id.hashCode;
}

void main() {
  // Create a graph with nodes representing candidates
  Graph<Candidate> candidateGraph = Graph();

  // Add some sample candidates
  final candidate1 = Candidate(1, "Alice");
  final candidate2 = Candidate(2, "Bob");
  final candidate3 = Candidate(3, "Charlie");

  candidateGraph.add(candidate1);
  candidateGraph.add(candidate2);
  candidateGraph.add(candidate3);

  // Connect candidates (edges represent relationships)
  candidateGraph.connect(candidate1, candidate2); // Alice knows Bob
  candidateGraph.connect(candidate2, candidate3); // Bob knows Charlie
  candidateGraph.connect(candidate1, candidate3); // Alice knows Charlie

  // Find the shortest path between two candidates using BFS
  List<Node<Candidate>>? path =
      findShortestPath(candidateGraph, candidate1, candidate3);

  if (path != null) {
    print("Shortest Path from $candidate1 to $candidate3:");
    for (var node in path) {
      print(node.value.name);
    }
  } else {
    print("No path found from $candidate1 to $candidate3.");
  }

  // Check if there's a cycle in the graph
  var hasCycle = containsCycle(candidateGraph);
  print("\nDoes the graph contain a cycle? $hasCycle");

  // Get all connected components
  Map<int, List<Candidate>> components = findConnectedComponents(candidateGraph);
  print("\nConnected Components:");
  for (var component in components.values) {
    print("- ${component.map((c) => c.name).join(', ')});
  }
}
