import 'dart:math' show Random;

int candidate(int n) {
  int count = 0;
  if (n < 1) return 0;

  List<int> arr = List.filled(n, 0);
  for (var i = 0; i < n; i++) {
    var randomIndex = new Random().nextInt(i + 1);
    arr[randomIndex] ^= 1 << i;
  }

  // Count the number of set bits in the array
  for (var num in arr) {
    count += countSetBits(num);
  }

  return count;
}

// Helper function to count set bits in an integer
int countSetBits(int x) {
  int result = 0;
  while (x > 0) {
    result++;
    x &= x - 1;
  }
  return result;
}
