import 'dart:math';

int candidate(int n) {
  if (n <= 0) return 0;

  int count = 0;
  for (var i = 1; i <= sqrt(n); i++) {
    if (i * i == n) {
      count += 2;
    } else if (i * i < n && isPrime(i)) {
      count++;
    }
  }
  return count;
}

bool isPrime(int num) {
  if (num <= 1) return false;
  if (num == 2) return true;
  if (num % 2 == 0) return false;
  for (var i = 3; i <= sqrt(num); i += 2) {
    if (num % i == 0) return false;
  }
  return true;
}
