    print('No input provided.');
    return;
  }

  int totalSum = 0;
  for (int i = 1; i < lines.length - 2; i++) {
    String currentLine = lines[i];

    // Extract digits from line and convert to integers.
    List<int> digits = [];
    for (var c in currentLine.split('')) {
      if ('0' <= c && c <= '9') {
        digits.add(int.parse(c));
      }
    }

    // Sum each row's first and last digit.
    int sumRow = digits[0] + digits.last;
    totalSum += sumRow;
  }

  print(totalSum);
