import 'package:vector_math/vector_math.dart';

// Helper function to calculate the area of a polygon using shoelace formula.
double _polygonArea(List<Vector2> vertices) {
  double area = 0.0;
  int n = vertices.length;

  for (int i = 0; i < n; i++) {
    Vector2 current = vertices[i];
    Vector2 next = vertices[(i + 1) % n];

    area += (current.x * next.y - next.x * current.y);
  }

  return area.abs() / 2.0;
}

// Candidate solution that calculates the area of a polygon given its coordinates.
double candidate(List<List<double>> coords) {
  if (coords.isEmpty || coords.length < 3) {
    return 0.0; // Not enough points to form a polygon.
  }

  List<Vector2> vertices = [];
  for (List<double> point in coords) {
    vertices.add(Vector2(point[0], point[1]));
  }

  return _polygonArea(vertices);
}
