List<Candidate> parseCandidates(String input) {
  if (input.isEmpty) return [];

  // Split the input into lines and filter out empty ones
  List<String> lines = input.split('\n').where((line) => line.trim().isNotEmpty).toList();

  // Process each line to extract candidate data
  List<Candidate> candidates = [];

  for (String line in lines) {
    // Split the line by commas
    List<String> parts = line.split(',');

    // Check that there are exactly two parts after trimming whitespace
    if (parts.length != 2) continue;

    // Trim any extra spaces around the ID and name
    String? idStr = parts[0].trim();
    String? name = parts[1].trim();

    // Parse the ID as integer
    try {
      int id = int.parse(idStr);
      candidates.add(Candidate(id, name!));
    } catch (_) {}
  }

  return candidates;
}
