  }

  Candidate? findByName(String nameToFind) {
    for (final candidate in this) {
      if (candidate.name == nameToFind) {
        return candidate;
      }
    }
    return null;
  }

  void addCandidate(Candidate newCandidate) {
    add(newCandidate);
  }

  void removeCandidate(String nameToRemove) {
    for (int i = 0; i < length; i++) {
      if (this[i].name == nameToRemove) {
        removeAt(i);
        break;
      }
    }
  }

