List<Candidate> getTopCandidates(List<String> names) {
  List<int> scores = [];

  for (int i = 0; i < names.length; i++) {
    Random random = Random();
    scores.add(random.nextInt(100));
  }

  Map<int, List<String>> mapScoresToNames = {};

  for (int i = 0; i < names.length; i++) {
    if (!mapScoresToNames.containsKey(scores[i])) {
      mapScoresToNames[scores[i]] = [names[i]];
    } else {
      mapScoresToNames[scores[i]].add(names[i]);
    }
  }

  List<MapEntry<int, List<String>>> sortedEntries =
      mapScoresToNames.entries.toList()..sort((a, b) => b.key.compareTo(a.key));

  List<Candidate> topCandidates = [];

  for (MapEntry<int, List<String>> entry in sortedEntries) {
    for (String name in entry.value) {
      topCandidates.add(Candidate(name, entry.key));
    }
  }

  return topCandidates;
}
