Future<List<Candidate>> fetchCandidates(String filePath) async {
  try {
    final file = await File(filePath).readAsString();
    List<dynamic> data = jsonDecode(file);

    if (data is! List || data.isEmpty) {
      throw Exception('Invalid JSON format or empty list');
    }

    List<Candidate> candidates = [];
    for (var item in data) {
      if (item is Map<String, dynamic>) {
        candidates.add(Candidate.fromJson(item));
      } else {
        throw Exception('Expected map but found ${item.runtimeType}');
      }
    }

    // Sort candidates by votes descending to get the top one
    candidates.sort((a, b) => b.votes.compareTo(a.votes));
    return candidates;
  } catch (e) {
    print("Error fetching candidates: $e");
    rethrow;
  }
}
