class Candidate {
  final List<double> _points;

  Candidate(this._points);

  double get length => _points.length;

  int get count => _points.length ~/ 2; // assuming even number of points

  void compute() { 
    for (int i = 0; i < count - 1; i++) {
      Vector3 a = fromList(_points[i * 2], _points[i * 2 + 1], 0.0); // z=0 as per example
      Vector3 b = fromList(_points[(i+1) * 2], _points[(i+1)*2 + 1], 0.0);

      double dx = b.x - a.x;
      double dy = b.y - a.y;
      double dz = b.z - a.z;

      double distance = sqrt(dx*dx + dy*dy + dz*dz);
      print('Distance between point $i and $i+1 is $distance');
    }
  }

  static void main() {
    // Example usage:
    var data = [1, 2, 4, 5]; // x,y pairs
    var candidate = Candidate(data);
    candidate.compute();
  }
}
