// Helper function to convert a list of integers into an array for use with FFI functions.
Pointer<Uint8> intListToPtr(List<int> numbers) {
  final length = numbers.length;
  final ptr = calloc<Uint8>(length);

  if (ptr == null) throw Exception('Failed to allocate memory');

  try {
    for (int i = 0; i < length; ++i) {
      ptr.elementAt(i).value = numbers[i];
    }
  } catch (e) {
    free(ptr);
    rethrow;
  }

  return ptr;
}

void main() {
