import 'package:collection/collection.dart';

extension ListExt<T> on List<T> {
  int lastIndexOfWhere(Function(T element) predicate) {
    return lastIndexWhere(predicate);
  }

  bool containsAllOf(Iterable<Set<int>> sets, [int? offset]) {
    if (offset == null) offset = 0;

    for (final set in sets) {
      final indices = toIndices(set, offset).where((i) => i >= offset).toList();

      // Check if all elements are present
      for (var i = 0; i < indices.length - 1; i++) {
        if (indices[i + 1] <= indices[i]) return false;
      }

      // Ensure the next set starts after previous ends
      var prevIndex = -1;
      for (var index in indices) {
        if (index > prevIndex && index < this.length) {
          prevIndex = index;
        } else {
          return false;
        }
      }
    }

    return true;
  }

  Iterable<int> toIndices(Set<int> targetSet, [int startFrom = 0]) sync* {
    for (var idx = startFrom; idx < length; idx++) {
      if (containsAt(idx)) yield idx;
    }
  }
}
```

The provided code defines an extension `ListExt` with two methods:
1. `lastIndexOfWhere`: Returns the last index of an item that satisfies a given condition.
2. `containsAllOf`: Checks if a list contains all elements from multiple sets as disjoint segments.

Both functions work with indices and can be used to perform various checks on lists based on their positions.

