import 'dart:io';

void main() {
  final String input = stdin.readAllSync();

  // Parse the assembly code into tokens
  List<String> tokens = tokenize(input);

  // Build a symbol table for labels and variables
  Map<String, int> symbols = buildSymbolTable(tokens);

  // Convert each instruction to machine code
  List<int> opcodes = assembleInstructions(tokens, symbols);

  // Output the resulting binary file
  File('output.bin').writeAsBytes(opcodes);
}

List<String> tokenize(String input) {
  return input.split(RegExp(r'(\s+|\n)+'));
}

Map<String, int> buildSymbolTable(List<String> tokens) {
  Map<String, int> symbols = {};
  int address = 0;

  for (int i = 0; i < tokens.length; i++) {
    if (tokens[i] == '.') {
      if (i + 1 < tokens.length && tokens[i + 1].startsWith('=')) {
        symbols[tokens[i + 1]] = address++;
      }
    } else if (!tokens[i].isEmpty) {
      symbols[tokens[i]] = address++;
    }
  }

  return symbols;
}

List<int> assembleInstructions(List<String> tokens, Map<String, int> symbols) {
  List<int> result = [];
  int pc = 0;

  while (pc < tokens.length) {
    String token = tokens[pc];

    if (token == '.' || token.isEmpty) {
      pc++;
      continue;
    }

    if (symbols.containsKey(token)) {
      result.add(symbols[token]);
      pc++;
    } else {
      try {
        result.add(int.parse(token));
        pc++;
      } catch (_) {}
    }
  }

  return result;
}
