    Candidate('Alice', 0),
    Candidate('Bob', 0),
    Candidate('Charlie', 0)
  ];

  print("Voting system initialized. Candidates are: Alice, Bob, Charlie.");

  for (int i = 1; i <= 5; i++) {
    if (i % 2 == 0) {
      // Even rounds have different voting pattern
      candidates[Random().nextInt(candidates.length)].castVote();
    } else {
      // Odd rounds follow a simple rotation
      candidates[(i - 1) % candidates.length].castVote();
    }

    print("\nRound $i:");
    for (var candidate in candidates) {
      print("${candidate.name}: ${candidate.votes} vote(s)");
    }
  }

  // Determine the winner
  var maxVotes = candidates.reduce((a, b) => a.votes > b.votes ? a : b);
  print("\nFinal results:");
  for (var candidate in candidates) {
    print("${candidate.name}: ${candidate.votes} vote(s)");
  }
  print("\nThe winner is: ${maxVotes.name}");
}
