import 'package:collection/collection.dart';

class Candidate {
  final String name;
  final int score;

  const Candidate({required this.name, required this.score});

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is Candidate &&
          runtimeType == other.runtimeType &&
          name == other.name &&
          score == other.score;

  @override
  int get hashCode => Object.hash(name, score);
}

List<Candidate> topCandidates(List<Candidate> candidates, int n) {
  if (n <= 0 || n >= candidates.length) return List.from(candidates);

  // Sort candidates by score in descending order
  var sorted = candidates.toList()
    ..sort((a, b) => b.score.compareTo(a.score));

  // Take the first n elements and then sort them alphabetically
  var topN = sorted.take(n).toList();
  topN.sort((a, b) => a.name.compareTo(b.name));

  return topN;
}
