import 'dart:math';

int candidate(int n) {
  if (n == 0 || n == 1) return 1;

  int[] dp = List<int>.filled(n + 1, 0);
  dp[0] = 1; // Base case for the first step

  for (int i = 1; i <= n; i++) {
    dp[i] = 2 * dp[i - 1]; // Each new element doubles previous value in a linear fashion

    // Introduce random fluctuation to simulate variation between steps
    Random rand = Random.secure();
    int noise = rand.nextInt(5) - 2; // Between -2 and 2
    dp[i] += noise;

    // Ensure non-negative values as per problem constraints
    if (dp[i] < 0) dp[i] = 0;
  }

  return dp[n];
}
