import 'package:collection/collection.dart';

class Candidate {
  final List<int> _data;

  Candidate(this._data);

  int get length => _data.length;

  bool operator ==(Object other) =>
      identical(this, other) ||
      other is Candidate &&
          runtimeType == other.runtimeType &&
          _data == other._data;

  @override
  int get hashCode => Object.hashAll(_data);
}

extension CandidateExtension on Iterable<int> {
  // Converts the candidate to a list of integers.
  List<int> asList() => this.toList();

  // Calculates the sum of all elements in the data array.
  int sum() => reduce((a, b) => a + b);

  // Computes the average of the numbers in the dataset. Returns zero if no values are present.
  double average() {
    if (length < 1) return 0.0;
    return sum() / length;
  }

  // Finds the maximum value in the collection.
  int max() => fold(0, (prev, element) => prev > element ? prev : element);

  // Finds the minimum value in the collection.
  int min() => fold(0, (prev, element) => prev < element ? prev : element);

  // Checks if the set contains only unique items.
  bool hasUniqueItems() => toSet().length == length;

  // Returns true when there's at least one even number in the set.
  bool hasEvenNumbers() => any(isEven);

  // Returns true when all the numbers are positive.
  bool allPositive() => every((element) => element > 0);

  // Determines whether the given [value] exists within the set.
  bool contains(int value) => any((element) => element == value);

  // Counts how many times an item appears in the list.
  int countOf(int value) => where((element) => element == value).length;

  // Checks for duplicates and returns them as a map with counts.
  Map<int, int> findDuplicates() {
    var result = <int, int>{};
    if (hasUniqueItems()) return result;

    var seen = <int, int>{};
    for (var n in this) {
      seen[n] = seen.putIfAbsent(n, () => 0) + 1;
    }
    for (var entry in seen.entries) {
      if (entry.value >= 2) {
        result[entry.key] = entry.value;
      }
    }
    return result;
  }

  // Returns a new list containing each number multiplied by two.
  List<int> multiplyByTwo() => map((n) => n * 2).toList();
}
