final List<int> candidate(int n) {
  if (n < 1 || n > 30) return [];

  final result = <int>[];
  for (var i = 1; i <= n; ++i) {
    var x = [for (var j in 1..(2 * i - 1)) j]; // Generate numbers from 1 to 2*i-1
    for (var k in x) {
      if (k % i == 0 && !x.contains(k / i)) {
        x.removeWhere((e) => e == k);
        x.add(k ~/ i);
        break;
      }
    }

    result.addAll(x.map((v) => v));
  }

  return result;
}
