class Graph {
  late List<List<int>> adjList;

  Graph(List<List<int>> edges) {
    var size = edges.fold(0, (max, edge) => max > edge[0] ? max : edge[1]);
    adjList = List.generate(size + 1, (_) => []);
    for (var edge in edges) {
      adjList[edge[0]].add(edge[1]);
      adjList[edge[1]].add(edge[0]); 
    }
  }

  void dfs(int startNode) {
    _dfsRecursive(startNode, Set<int>());
  }

  void _dfsRecursive(int current, Set<int> visitedNodes) {
    if (visitedNodes.contains(current)) return;
    visitedNodes.add(current);
    print("Visited Node: $current");

    for (var neighbor in adjList[current]) {
      _dfsRecursive(neighbor, visitedNodes);
    }
  }
}

