import 'package:collection/collection.dart';

class Candidate {
  final String name;
  int score;

  const Candidate({required this.name, required this.score});

  factory Candidate.fromString(String input) {
    if (input.isEmpty || !input.contains(':')) return null;

    var parts = input.split(':');
    if (parts.length != 2) return null;

    try {
      final namePart = parts[0].trim();
      final scorePart = int.parse(parts[1].trim());

      return Candidate(name: namePart, score: scorePart);
    } catch (_) {
      return null;
    }
  }

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is Candidate &&
          runtimeType == other.runtimeType &&
          name == other.name &&
          score == other.score;

  @override
  int get hashCode => Object.hash(name, score);

  @override
  String toString() => '$name: $score';
}

List<Candidate> parseCandidates(String candidatesData) {
  List<String> candidateLines = candidatesData.trim().split('\n');

  List<Candidate> parsedCandidates = [];

  for (String line in candidateLines) {
    Candidate? candidate = Candidate.fromString(line);
    if (candidate != null && candidate.score >= 0) {
      parsedCandidates.add(candidate);
    }
  }

  // Sort by highest score descending, then alphabetically
  parsedCandidates.sort((a, b) {
    if (b.score != a.score) {
      return b.score.compareTo(a.score);
    } else {
      return a.name.compareTo(b.name); // Alphabetical order
    }
  });

  return parsedCandidates;
}
