import 'package:collection/collection.dart';

class Candidate {
  final String name;
  final int year;

  const Candidate({required this.name, required this.year});

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is Candidate &&
          runtimeType == other.runtimeType &&
          name == other.name &&
          year == other.year;

  @override
  int get hashCode => Object.hash(name, year);

  static List<Candidate> parseCandidates(String input) {
    if (input.isEmpty) return [];

    // Split the string into lines and process each line
    final candidates = <Candidate>[];
    for (final line in input.split('\n')) {
      final parts = line.trim().split(':');
      if (parts.length != 2) continue; // Skip malformed lines

      try {
        final name = parts[0].trim();
        final year = int.parse(parts[1].trim());

        candidates.add(Candidate(name: name, year: year));
      } catch (_) {}
    }

    return candidates;
  }

  factory Candidate.fromString(String str) {
    final splitStr = str.split(':');
    if (splitStr.length != 2) throw FormatException('Invalid candidate format');

    final name = splitStr[0];
    final year = int.tryParse(splitStr[1]);

    if (year == null || year <= 0) throw FormatException('Year must be a positive integer');

    return Candidate(name: name, year: year);
  }
}

void main() {
  // Example usage:
  final rawInput = """
John Doe:2023
Jane Smith:2024
Alice Johnson:2025
Bob Brown:2023
Charlie Davis:2022
""";

  final parsedCandidates = Candidate.parseCandidates(rawInput);

  print("Parsed Candidates:");
  for (final candidate in parsedCandidates) {
    print("${candidate.name} (${candidate.year})");
  }
}
