abstract class ElectionResult<T> {}

class Winner<T> extends ElectionResult<T> {
  final T candidate;
  final int votes;

  Winner(this.candidate, this.votes);

  @override
  String toString() => 'Winner(candidate: $candidate, votes: $votes)';
}

class NoContest extends ElectionResult<void> {
  static final instance = NoContest();

  @override
  String toString() => 'NoContest';
}

extension ElectionResults on Iterable<Candidate> {
  ElectionResult<Candidate> determineWinner(int totalVotes) {
    if (isEmpty) return NoContest();

    var candidatesWithVotes = map((c) => MapEntry(c, 0));
    for (var i = 0; i < totalVotes; i++) {
      final winner = this.randomOrNull ?? first;
      candidatesWithVotes[winner]!.value++;
    }

    // Sort by votes descending, then by name ascending
    final sortedCandidates = candidatesWithVotes.values.toList()
        .sort((a, b) => a.value.compareTo(b.value) * -1)
        .then((e) => e.sort((a, b) => a.key.name.compareTo(b.key.name)));

    final maxVoteCount = sortedCandidates.first.value;
    final winners = List<MapEntry<Candidate, int>>.from(sortedCandidates)
        .where((entry) => entry.value == maxVoteCount);

    if (winners.length > 1) {
      return NoContest();
    } else {
      return Winner(winners.single.key, winners.single.value);
    }
  }

  Candidate? randomOrNull => _random.nextInt(length) >= length ? null : elementAt(_random.nextInt(length));

  late final Random _random = Random.secure(); 
}
