import 'package:graph/graph.dart';

void main() {
  final graph = Graph<int, int>();

  // Add nodes and edges with weights
  graph.addNode(1);
  graph.addNode(2);
  graph.addNode(3);
  graph.addNode(4);
  graph.addNode(5);

  graph.addEdge(1, 2, weight: 10);
  graph.addEdge(1, 3, weight: 6);
  graph.addEdge(1, 4, weight: 9);
  graph.addEdge(2, 3, weight: 8);
  graph.addEdge(2, 5, weight: 7);
  graph.addEdge(3, 4, weight: 3);
  graph.addEdge(3, 5, weight: 5);
  graph.addEdge(4, 5, weight: 4);

  final shortestPaths = dijkstra(graph, sourceNode: 1);

  for (final node in graph.nodes) {
    print('Shortest path from $node to 1:');
    if (shortestPaths.containsKey(node)) {
      final distance = shortestPaths[node]!;
      print('Distance: $distance');
    } else {
      print('No path found.');
    }
  }
}

Map<int, double> dijkstra(Graph<int, int>, {required int sourceNode}) {
  final distances = <int, double>{};
  final visited = <int>{};

  final pq = PriorityQueue<MapEntry<int, double>>((a, b) => a.value.compareTo(b.value));
  pq.add(MapEntry(sourceNode, 0.0));

  while (!pq.isEmpty) {
    final current = pq.removeFirst();
    final currentNode = current.key;
    final currentDistance = current.value;

    if (visited.contains(currentNode)) continue;

    visited.add(currentNode);
    distances[currentNode] = currentDistance;

    for (final neighbor in graph.getAdjacentNodes(currentNode).keys) {
      final edgeWeight = graph.getEdgeWeightBetween(currentNode, neighbor)!;
      final newDistance = currentDistance + edgeWeight;

      if (!distances.containsKey(neighbor) || newDistance < distances[neighbor]!) {
        pq.add(MapEntry(neighbor, newDistance));
      }
    }
  }

  return distances;
}
