class PriorityQueue<T extends Comparable<T>> {
  List<T> _elements = [];
  late Comparator<T> _comparator;

  PriorityQueue([Comparator<T>? comparator]) : _comparator = comparator ?? ((a, b) => a.compareTo(b)) {
    _elements.sort(_comparator);
  }

  void add(T element) {
    _elements.add(element);
    _elements.sort(_comparator);
  }

  T get first => _elements.first;

  bool isEmpty() => _elements.isEmpty;

  removeFirst() {
    if (_elements.isNotEmpty) {
      final result = _elements.first;
      _elements.removeAt(0);
      return result;
    }
    throw Exception("Cannot remove from empty priority queue");
  }
