import 'package:ffi/ffi.dart';

// Define the structure for the assembly instructions.
class AssemblyInstruction {
  final String mnemonic;
  final List<String> operands;

  AssemblyInstruction({required this.mnemonic, required this.operands});
}

// Helper function to parse a single instruction line into an Instruction object.
AssemblyInstruction? parseInstruction(String line) {
  // Split the line by spaces and commas to extract parts.
  var tokens = line.split(RegExp(r'\s+|,\s*'));

  if (tokens.isEmpty || !tokens[0].startsWith('mov')) return null; // Not an instruction.

  var mnemonic = tokens[0];
  var operands = <String>[];

  // Extract operand(s).
  for (var i = 1; i < tokens.length; i++) {
    if (tokens[i] == '') continue; // Skip empty strings from split.
    operands.add(tokens[i]);
  }

  return AssemblyInstruction(mnemonic: mnemonic, operands: operands);
}

// Main function to convert assembly lines to Dart code.
void main() {
  // Example input list of assembly lines. Replace with your actual data source.
  List<String> assemblyLines = [
    "mov rax, rbx",
    "add rax, rcx",
    "cmp rdx, rsi",
    "jmp label1",
    "label1:",
    "xor r8, r9",
    "lea rsp, [rax + 4]",
    "call funcA",
    "ret"
  ];

  // Convert each assembly line to Dart code.
  for (final line in assemblyLines) {
    var inst = parseInstruction(line);

    if (inst != null && inst.operands.isNotEmpty) {
      print("if (${inst.operands[1]} is not null) {");
      print("  ${inst.operands[0]} = ${inst.operands[1]};");
      print("}");
    } else if (inst != null) {
      print("${inst.operands[0]} = ${inst.operands[1]};"); 
    }
  }
}
