class Candidate {
  final String name;
  final int score;

  Candidate(this.name, this.score);

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is Candidate &&
          runtimeType == other.runtimeType &&
          name == other.name &&
          score == other.score;

  @override
  int get hashCode => Object.hash(name, score);
}

List<Candidate> findTopCandidates(List<String> candidates, List<int> scores) {
  if (candidates.length != scores.length || candidates.isEmpty || scores.isEmpty) {
    return [];
  }

  var candidateMap = Map<String, int>();
  for (var i = 0; i < candidates.length; i++) {
    candidateMap[candidates[i]] = scores[i];
  }

  // Sort the list of candidates based on their scores in descending order.
  var sortedCandidates = candidateMap.entries
      .map((entry) => Candidate(entry.key, entry.value))
      .sorted(
        (a, b) => b.score.compareTo(a.score),
      );

  // Return top 3 highest scoring candidates with their names and scores.
  return sortedCandidates.take(3).toList();
}
