import 'package:vector_math/vector_math.dart';

class Candidate {
  static final _epsilon = 1e-6;

  static bool isSamePoint(Point3 a, Point3 b) =>
      (a.x - b.x).abs() < _epsilon && (a.y - b.y).abs() < _epsilon &&
          (a.z - b.z).abs() < _epsilon;

  static Vector3 subtractPoints(Point3 p0, Point3 p1) => 
    Vector3(p0.x - p1.x, p0.y - p1.y, p0.z - p1.z);

  static double dotProduct(Vector3 v1, Vector3 v2) => 
    v1.dot(v2);

  static double lengthSquared(Vector3 vector) => 
    vector.lengthSquared;

  static void normalizeVector(Vector3 vector) { 
    if(vector.length > _epsilon)
      vector.normalize();
  }

  static List<Vector3> calculateNormals(List<List<Point3>> triangles) {
    final normals = [];

    for (final triangle in triangles) {
      // Ensure the triangle has three points.
      if(triangle.length != 3) continue;

      var p0 = triangle[0];
      var p1 = triangle[1];
      var p2 = triangle[2];

      // Create vectors from point to other points.
      var u = subtractPoints(p1, p0);
      var v = subtractPoints(p2, p0); 

      // Calculate cross product of vectors.
      var normal = cross(u, v); 

      // Normalize and add it to list.
      normalizeVector(normal);
      normals.add(normal);
    }

    return normals; 
  }

  static int compareVectors(
      Vector3 v1,
      Vector3 v2,
      [double epsilon = _epsilon]) {

    if(v1 == null || v2 == null) return 0;

    final diffX = v1.x - v2.x;
    final diffY = v1.y - v2.y;
    final diffZ = v1.z - v2.z;

    // Check for magnitude difference within tolerance.
    if ((diffX * diffX + diffY * diffY + diffZ * diffZ).sqrt() < epsilon) {
      return 0;
    } else if (v1.length >= v2.length) {
      return 1;
    } else {
      return -1;
    }
  }
}
