List<PlaneEquation> generatePlanesFromTriangles(Iterable<List<Point3>> triangles) {
  final planes = [];

  for (final triangle in triangles) {
    final p0 = triangle[0];
    final p1 = triangle[1];
    final p2 = triangle[2];

    final n = Candidate.calculateNormal(p0, p1, p2);

    // Compute plane equation coefficients using Ax + By + Cz + D = 0
    final A = n.x;
    final B = n.y;
    final C = n.z;

    // Find D by plugging in any point on the plane. Here we use p0
    final D = -(A * p0.x + B * p0.y + C * p0.z);

    planes.add(PlaneEquation(A, B, C, D));
  }

  return planes;
}

// Helper method to compute the normal between three points
static Vector3 calculateNormal(Point3 p0, Point3 p1, Point3 p2) {
  final ab = subtractPoints(p1, p0);
  final ac = subtractPoints(p2, p0);
  return cross(ab, ac);
}
