void candidate() {
  // Define the input as a graph structure with nodes and edges.
  final int n = 5;
  List<List<int>> adjacencyList = [
    [1, 2],      // Node 0 connected to 1 and 2
    [0, 3],      // Node 1 connected to 0 and 3
    [0, 4],      // Node 2 connected to 0 and 4
    [1, 4],      // Node 3 connected to 1 and 4
    [2, 3]       // Node 4 connected to 2 and 3
  ];

  // Check if all nodes are visited in one traversal (DFS or BFS).
  bool isStronglyConnected(int startNode) {
    Set<int> visited = {startNode};
    Stack<int> stack = [startNode];

    while (stack.isNotEmpty) {
      var current = stack.removeLast();
      for (int neighbor in adjacencyList[current]) {
        if (!visited.contains(neighbor)) {
          visited.add(neighbor);
          stack.add(neighbor);
        }
      }
    }

    return visited.length == n;
  }

  print('Is strongly connected? ${isStronglyConnected(0)}');
}
