class Graph {
  Map<String, List<String>> _graph;

  Graph() : _graph = {};

  void addEdge(String from, String to) {
    if (!_graph.containsKey(from)) {
      _graph[from] = [];
    }
    _graph[from].add(to);

    if (!_graph.containsKey(to)) {
      _graph[to] = [];
    }
    _graph[to].add(from); // Assuming undirected graph
  }

  Future<void> dfsAsync(String node, Set<String> visited, Completer<bool> completer) async {
    if (visited.contains(node)) return;
    visited.add(node);
    for (String neighbor in _graph[node] ?? []) {
      await dfsAsync(neighbor, visited, completer);
    }
  }

  Future<void> checkConnectivity(String startNode) async {
    Set<String> visited = {};
    Completer<bool> completer = Completer();
    await dfsAsync(startNode, visited, completer);
    if (visited.length != _graph.keys.length) {
      completer.complete(false);
    } else {
      completer.complete(true);
    }
    return completer.future;
  }
}

