import 'dart:math';

class Candidate {
  final String name;
  int score;

  Candidate(this.name, this.score);
}

List<Candidate> generateCandidates(int count) {
  List<Candidate> candidates = [];
  for (int i = 0; i < count; i++) {
    var randomName = _generateRandomName();
    var randomScore = Random().nextInt(100).toDouble() * 2.5 + 40.0;
    candidates.add(Candidate(randomName, randomScore.toInt()));
  }
  return candidates;
}

String _generateRandomName() {
  const vowels = ['a', 'e', 'i', 'o', 'u'];
  const consonants = [
    'b', 'c', 'd', 'f', 'g',
    'h', 'j', 'k', 'l', 'm',
    'n', 'p', 'q', 'r', 's',
    't', 'v', 'w', 'x', 'z'
  ];

  String createWord(int length) {
    var word = '';
    for (var i = 0; i < length; i++) {
      if (i % 3 == 0 && i != 0) {
        // Add a vowel after every third character to make it pronounceable.
        word += vowels[Random().nextInt(vowels.length)];
      } else {
        word += consonants[Random().nextInt(consonants.length)];
      }
    }
    return word;
  }

  // Generate two words and combine them as a full name.
  var firstPart = createWord(6);
  var secondPart = createWord(4);
  return '$firstPart $secondPart';
}
