List<Candidate> filterCandidates(List<Candidate> candidates, {int? minAge}) {
  if (minAge != null && minAge < 0) {
    throw ArgumentError('Minimum age cannot be negative');
  }

  return candidates.where((candidate) {
    final valid = candidate.age >= (minAge ?? 18); // default to 18 if not specified
    return valid;
  }).toList();
}
