// Helper function to calculate the area of a triangle using Heron's formula
double triangleArea(double side1, double side2, double side3) {
  var s = (side1 + side2 + side3) / 2;
  return sqrt(s * (s - side1) * (s - side2) * (s - side3));
}

class Triangle {
  final List<double> sides;

  Triangle(this.sides);

  // Calculate the area of the triangle
  double get area => triangleArea(sides[0], sides[1], sides[2]);

  bool isEquilateral() {
    return sides.every((side) => side == sides[0]);
  }

  bool isIsosceles() {
    return sides.toSet().length <= 2;
  }

  bool isValidTriangle() {
    final sortedSides = [...sides]..sort();
    return sortedSides[0] + sortedSides[1] > sortedSides[2];
  }
}
