import 'dart:io';
import 'dart:convert';

void main() async {
  final input = stdin.readLinesSync();

  for (final line in input) {
    if (line.startsWith('Assembly:')) {
      final assemblyCode = line.substring(10).trim();

      // Convert to Dart code using simple substitution
      String dartCode = assembleToDart(assemblyCode);

      print(dartCode);
    }
  }
}

String assembleToDart(String assembly) {
  var lines = assembly.split('\n');
  var result = '';

  for (var i = 0; i < lines.length; i++) {
    var line = lines[i];

    // Remove comments
    int commentIndex = line.indexOf(';');
    if (commentIndex != -1) {
      line = line.substring(0, commentIndex);
    }

    // Skip empty lines
    if (line.trim().isEmpty) continue;

    // Basic instruction mapping
    switch (line.trim()) {
      case '.section .text':
        result += 'void main() {\n';
        break;

      case '.global _start':
        result += '_start();\n';
        break;

      case 'mov rax, 60': 
        result += 'exit(0);\n';
        break;

      default:
        if (line.contains(':') && !line.endsWith(':')) { // Label definition
          var parts = line.split(':');
          var label = parts[0].trim();
          var instr = parts[1].trim();

          result += '$label:\n';
          result += assembleToDart(instr);
        } else {
          result += '// $line\n';
        }
        break;
    }
  }

  return result;
}
