import 'dart:convert';
import 'dart:io';

void candidate() {
  final input = stdin.readLinesSync();
  final lines = List<String>.from(input);

  if (lines.isEmpty) return;

  final graph = Map<int, Set<int>>();

  for (final line in lines) {
    final parts = line.split(' ').map(int.parse).toList();

    if (parts.length < 3 || parts[0] == -1) continue; // skip invalid or header

    int from = parts[0];
    int to = parts[2]; 

    if (!graph.containsKey(from)) {
      graph[from] = HashSet<int>();
    }
    graph[from]!.add(to);
  }

  void dfs(int node, bool isVisited, bool visitedSet) {
    if (visitedSet) { 
      print(node); 
      return;
    } else {
      var v = [node];
      while(v.isNotEmpty) {
        final current = v.removeAt(0);

        if (current != null && !isVisited[current]) {
          isVisited[current] = true;
          v.addAll(graph[current] ?? []);
        } else {
          v.add(current! + 1);
        }
      }
    }
  }

  void bfs(int startNode) {
    var queue = Queue<int>();
    var visited = Array<bool>(size: graph.keys.length * 2);

    queue.add(startNode);
    visited[startNode] = true;

    while(queue.isNotEmpty) {
      final current = queue.removeFirst();

      if (visited[current]!) {
        print(current);
      }

      if (graph.containsKey(current)) {
        for (int neighbor in graph[current]!) {
          if (!visited[neighbor]) {
            visited[neighbor] = true;
            queue.add(neighbor);
          }
        }
      }
    }
  }

  bfs(lines[0].split(' ')[0]);
}
