extension Candidates on List<Candidate> {
  Vector3 get averagePosition => fold(Vector3.zero(), (sum, candidate) {
    return sum + Vector3(candidate.id.toDouble() % 100.0,
        candidate.id.toDouble() % 50.0, candidate.id.toDouble() % 20.0);
  }).scaled(1 / length);

  void drawCandidates(double width, double height) {
    final canvas = Canvas(size: Size(width, height));
    final paint = Paint()
      ..color = Colors.black.withOpacity(0.6)
      ..style = PaintingStyle.stroke
      ..strokeWidth = 2.0;

    for (final candidate in this) {
      final point = averagePosition;
      final x = point.x * width / 100.0;
      final y = point.y * height / 50.0;

      canvas.drawRect(
        Rect.fromLTWH(x - 4, y - 4, 8, 8),
        paint,
      );
    }
  }

  static List<Candidate> fromJson(Map<String, dynamic> json) {
    if (!json.containsKey('candidates')) {
      throw FormatException("Missing candidates field");
    }

    final candidatesList = json['candidates'] as List<dynamic>;
    final candidates = <Candidate>[];

    for (var item in candidatesList) {
      if (item is Map<String, dynamic>) {
        final id = item['id'] as num?;
        final name = item['name'] as String? ?? '';

        if (id != null && name.isNotEmpty) {
          candidates.add(Candidate(id.toInt(), name.trim()));
        }
      }
    }

    return candidates;
  }
}
