import 'package:collection/collection.dart';

class Candidate {
  final int id;
  final String name;

  const Candidate(this.id, this.name);
}

abstract class Vote {
  void apply(VoteResult result);
}

class ApprovalVote extends Vote {
  final List<Candidate> approvals;

  ApprovalVote(List<Candidate> approvals) : approvals = approvals.toList();

  @override
  void apply(VoteResult result) {
    for (final candidate in approvals) {
      result.approvals[candidate.id] = true;
    }
  }

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ApprovalVote &&
          runtimeType == other.runtimeType &&
          setEquals(approvals, other.approvals);

  @override
  int get hashCode => Object.hashAll(approvals.map((e) => e.id));
}

class RankingVote extends Vote {
  final Map<int, double> rankings; // key: candidate ID, value: rank (lower better)

  RankingVote(Map<int, double> rankings) : rankings = rankings;

  static List<double> computeRankings(
      List<List<int>> ballots,
      List<Candidate> candidates,
      int numCandidates) {
    final rankingScores = <int, double>{};

    for (var i = 0; i < numCandidates; i++) {
      var totalScore = 0.0;
      for (var j = 0; j < ballot.length; j++) {
        if (ballot[j] != -1) {
          totalScore += (j + 1).toDouble();
        } else {
          break;
        }
      }
      rankingScores[i] = totalScore / ballot.length.toDouble();
    }

    return rankingScores.values.toList()..sort(); // Sort by score to determine ranks
  }

  @override
  void apply(VoteResult result) {
    for (final entry in rankings.entries) {
      result.rankings[entry.key] = entry.value;
    }
  }

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is RankingVote &&
          runtimeType == other.runtimeType &&
          mapEquals(rankings, other.rankings);

  @override
  int get hashCode => Object.hashAll(rankings.values);
}

class ScoreVote extends Vote {
  final Map<int, double> scores;

  ScoreVote(Map<int, double> scores) : scores = scores;

  @override
  void apply(VoteResult result) {
    for (final entry in scores.entries) {
      result.scores[entry.key] = entry.value;
    }
  }

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ScoreVote &&
          runtimeType == other.runtimeType &&
          mapEquals(scores, other.scores);

  @override
  int get hashCode => Object.hashAll(scores.values);
}

class VoteResult {
  final Map<int, bool> approvals = {};
  final Map<int, double> rankings = {};
  final Map<int, double> scores = {};

  void addApproval(Candidate candidate) {
    approvals[candidate.id] = true;
  }

  void addRanking(int candidateId, double rank) {
    rankings[candidateId] = rank;
  }

  void addScore(int candidateId, double score) {
    scores[candidateId] = score;
  }
}
