  String toString() => "Candidate($id, $name)";
}

class AssemblyGraph {
  List<Candidate> candidates = [];
  Map<int, Set<int>> connections = {};

  void addCandidate(int id, String name) {
    candidates.add(Candidate(id, name));
    connections[id] = {};
  }

  void connect(int fromId, int toId) {
    if (connections[fromId] != null && connections[toId] != null) {
      connections[fromId]!.add(toId);
      connections[toId]!.add(fromId);
    }
  }

  bool isCyclicUtil(int node, Set<int> visited, Set<int> recStack) {
    if (!visited.contains(node)) {
      visited.add(node);
      recStack.add(node);

      if (connections.containsKey(node)) {
        for (int neighbor in connections[node]!) {
          if (!visited.contains(neighbor)) {
            if (isCyclicUtil(neighbor, visited, recStack)) return true;
          } else if (recStack.contains(neighbor)) {
            return true; // Found a cycle
          }
        }
      }

      recStack.remove(node);
    }
    return false;
  }

  bool hasCycle() {
    Set<int> visited = Set();
    Set<int> recursionStack = Set();

    for (var candidate in candidates) {
      int nodeId = candidate.id;
      if (!visited.contains(nodeId)) {
        if (isCyclicUtil(nodeId, visited, recursionStack)) {
          return true;
        }
      }
    }
    return false;
  }

  void printCandidatesWithConnections() {
    for (var candidate in candidates) {
      var neighbors = connections[candidate.id] ?? [];
      print("Candidate ${candidate.name} (ID: ${candidate.id}) connected to [${neighbors.map((n) => candidates.firstWhere((c) => c.id == n).name).join(', ')}]");
    }
  }
}
