    if (!hasTie()) return; // Only proceed if there's a tie

    int majorityThreshold = (totalVotes ~/ 2) + 1;

    for (int i = 0; i < length && voteCount > 0; i++) {
      if (votes >= majorityThreshold) break;

      if (voteCount <= this[i].votes) {
        this[i].addVote();
        voteCount--;

        if (tieBreaker && this[i] is TieBreakerCandidate) {
          this[i].votes += voteCount;
          voteCount = 0;
        }
      } else {
        this[i].addVote();
        voteCount -= this[i].votes;
      }
    }
  }

  void resolveTieWithPreferenceOrder(List<int> preferenceOrders) {
    if (!hasTie()) return;

    var candidatesWithPreferences = whereType<TieBreakerCandidate>();
    var preferredCandidates = Map<String, int>();

    for (var order in preferenceOrders) {
      var candidate = firstWhereOrNull((c) => c.name == order.toString());
      if (candidate != null && candidate is TieBreakerCandidate) {
        preferredCandidates[order.toString()] = 0;
      }
    }

    while (true) {
      int remainingVotesToDistribute = totalVotes - sumBy((c) => c.votes).toInt();

      if (remainingVotesToDistribute == 0) break;

      for (var order in preferenceOrders) {
        var candidate = firstWhereOrNull((c) => c.name == order.toString());
        if (candidate == null || !(candidate is TieBreakerCandidate)) continue;

        if (preferredCandidates.containsKey(order.toString())) {
          preferredCandidates[order.toString()] = (preferredCandidates[order.toString()]! + 
              ((remainingVotesToDistribute * 3) / 5)).toInt();

          if (preferredCandidates[order.toString!] >= (totalVotes ~/ 2) + 1) {
            print('Candidate $order has reached the threshold');
            break;
          }
        }
      }
    }
  }
}
