class Candidate {
  final List<int> _positions;
  late int _current;

  Candidate(this._positions) : _current = -1;

  bool next() {
    if (_current >= _positions.length - 1) return false;

    ++_current;
    while (_current < _positions.length && _positions[_current] == _positions[_current + 1]) {
      ++_current;
    }
    return true;
  }

  void reset() => _current = -1;
}

void main() {
  var candidate = Candidate([3, 2, 2, 5]);

  for (var i in [0, 4]) {
    print('Position $i is ${candidate.next()}');
  }
}
