import 'dart:io';
import 'dart:convert';

void main() {
  final input = stdin.readLinesSync();

  final List<String> lines = [];
  for (final line in input) {
    if (line.trim().isNotEmpty && !lines.contains(line)) {
      lines.add(line);
    }
  }

  const int maxDepth = 10;
  final Map<int, Set<String>> depthMap = {};
  final Map<String, String> nodeToParent = {};
  final Map<String, bool> isLeaf = {};

  void buildTree(String node, int depth) {
    if (depth > maxDepth) return;

    var children = getChildren(node);

    if (children.isNotEmpty) {
      for (String child in children) {
        nodeToParent[child] = node;
        buildTree(child, depth + 1);
      }
    } else {
      isLeaf[node] = true;
    }
  }

  void processLine(String line) {
    final parts = line.split(' ');

    if (parts[0].startsWith('-')) {
      // Remove the '-' and split into parent-child pairs
      final nodes = parts.sublist(1).map((p) => p.split(':').first).toList();

      if (nodes.length >= 2) {
        final parent = nodes.first;
        final child = nodes.skip(1).first; 

        if (!nodeToParent.containsKey(parent)) {
          nodeToParent[parent] = '';
        }

        if (!depthMap.containsKey(parent)) {
          depthMap[parent] = {parent};
        } else {
          depthMap[parent]!.add(parent); 
        }

        if (child != null && !nodeToParent.containsKey(child)) {
          nodeToParent[child] = parent;
        }

        if (nodeToParent.containsKey(child) && !depthMap.containsKey(child)) {
          depthMap[child] = {child};
        } else if (nodeToParent.containsKey(child)) {
          depthMap[child]!.addAll(depthMap[parent]!);
        }
      }
    } else {
      // Add to root level
      if (!depthMap.containsKey(parts[0])) {
        depthMap[parts[0]] = {parts[0]};
      }
    }
  }

  for (var line in lines) {
    processLine(line);
  }

  print('Processing complete.');
}

List<String> getChildren(String node) {
  final Set<String> children = [];

  for (final key in nodeToParent.keys) {
    if (nodeToParent[key] == node) {
      children.add(key);
    }
  }

  return children.toList(); 
}
