  T convert<T>() {
    final result = T.fromMap(json.decode(this));
    return result;
  }
}

T fromMap<T extends Object>(dynamic map) {
  if (map == null) return null;
  if (map is T) return map;
  if (map is Map<String, dynamic>) {
    late T instance;
    for (var key in map.keys.cast<String>()) {
      var value = map[key];
      if (value != null && key.endsWith('?')) continue; // skip nullable fields
      if (key == '_type') continue; // skip type information
      final field = T.getField(key); 
      if (field != null) {
        instance = field.apply(instance ?? T(), value);
      }
    }
    return instance;
  }
  return T.fromString(map.toString());
}

