List<Candidate> findTopCandidates(List<String> names, List<int> scores) {
  if (names.length != scores.length || names.isEmpty || scores.isEmpty) {
    throw ArgumentError('Names and scores lists must have the same length.');
  }

  // Combine the names with their corresponding scores into a list of Candidates.
  var candidates = List.generate(names.length, (index) => Candidate(names[index], scores[index]));

  // Sort the candidates by score in descending order to get top performers.
  candidates.sort((a, b) => b.score.compareTo(a.score));

  return candidates;
}
