class ElectionResult {
  final List<Candidate> candidates;
  final Map<int, double> votes; // candidateId -> totalVotes

  ElectionResult({
    required this.candidates,
    required this.votes,
  });

  static void computeElectionResults(
      List<List<String>> ballots, List<Candidate> candidates) {
    final voteCounts = <int, int>{};

    for (final ballot in ballots) {
      if (ballot.isEmpty) continue;

      var currentCandidateId = -1;
      var currentVoteCount = 0;

      for (var i = 0; i < ballot.length; i++) {
        final candidateName = ballot[i];
        final candidateIndex = candidates.indexWhere((c) => c.name == candidateName);
        if (candidateIndex >= 0 && candidateIndex < candidates.length) {
          final candidateId = candidates[candidateIndex].id;

          if (i == 0) {
            currentCandidateId = candidateId;
            currentVoteCount += 1;
          } else if (i > 0) {
            // In a real system, you'd handle ranking here, but we're simulating simple voting.
            // For simplicity, assume each position on the list counts as one vote to that candidate.
            currentVoteCount++;
          }
        }
      }

      if (currentCandidateId != -1) {
        voteCounts[currentCandidateId] =
            (voteCounts[currentCandidateId] ?? 0) + currentVoteCount;
      }
    }

    // Convert map of vote counts to map with double values
    final result = voteCounts.entries.fold<Map<int, double>>(
        {}, (prev, entry) => {entry.key: entry.value.toDouble()});

    // Sort candidates by vote count descending and then by ID ascending
    final sortedCandidates = [...candidates]
        .sorted(((a, b) {
      final aVoteCount = result[a.id] ?? 0.0;
      final bVoteCount = result[b.id] ?? 0.0;
      return aVoteCount.compareTo(bVoteCount) != 0 ? aVoteCount.compareTo(bVoteCount).reversed : a.id.compareTo(b.id);
    }));

    print('Election Results:');
    for (final candidate in sortedCandidates) {
      final voteCount = result[candidate.id] ?? 0.0;
      print('${candidate.name}: $voteCount');
    }
  }
}
