abstract class Interviewer<T extends Candidate> {
  void conductInterview(T candidate);
}

class TechnicalInterviewer implements Interviewer<Candidate> {
  @override
  void conductInterview(Candidate candidate) {
    print('Conducting technical interview with $candidate');
  }
}

class BehavioralInterviewer implements Interviewer<Candidate> {
  @override
  void conductInterview(Candidate candidate) {
    print('Conducting behavioral interview with $candidate');
  }
}

void main() {
  // Example usage:
  var candidates = [
    Candidate(name: 'Alice', age: 25, skills: ['Java', 'Python']),
    Candidate(name: 'Bob', age: 30, skills: ['JavaScript', 'Dart']),
  ];

  for (var candidate in candidates) {
    var interviewer = Interviewer<Candidate>.fromCandidate(candidate);
    interviewer.conductInterview(candidate);
  }

  // Custom logic to find the best candidate based on specific criteria
  var bestCandidate = candidates.reduceOrNull(
    (currentBest, candidate) {
      if (currentBest == null) return candidate;
      return currentBest.compareTo(candidate) > 0 ? candidate : currentBest;
    },
  );

  if (bestCandidate != null) {
    print('The best candidate is ${bestCandidate.name}');
  } else {
    print('No candidates found.');
  }
}
