class Interviewer<CandidateType extends Candidate> {
  static Interviewer<CandidateType>? fromCandidate(CandidateType? candidate) {
    if (candidate == null) return null;

    switch (candidate.skills.firstWhere(
        (skill) => skill.startsWith('Tech'), orElse: () => '')) {
      case 'Java':
        return TechnicalInterviewer();
      default:
        return BehavioralInterviewer();
    }
  }
}
