class Candidate {
  final String name;
  final int votes;

  const Candidate({required this.name, required this.votes});

  static List<Candidate> parseCandidates(String input) {
    if (input.trim().isEmpty) return [];

    // Split the input into lines and process each line as a candidate entry
    final candidates = <Candidate>[];
    for (final line in input.split('\n')) {
      final trimmedLine = line.trim();
      if (trimmedLine.isNotEmpty && !trimmedLine.startsWith('#')) {
        final parts = trimmedLine.split(':');
        if (parts.length == 2) {
          final name = parts[0].trim();
          final voteCountStr = parts[1].trim();

          try {
            final voteCount = int.parse(voteCountStr);
            candidates.add(Candidate(name: name, votes: voteCount));
          } catch (_) {}
        }
      }
    }
    return candidates;
  }

  @override
  String toString() => '$name ($votes)';
}

