import 'dart:io';
import 'dart:convert';

// Define a class to represent the assembly instructions
class AssemblyInstruction {
  final String opCode;
  final List<String> operands;

  AssemblyInstruction(this.opCode, this.operands);

  @override
  String toString() => '$opCode ${operands.join(', ')}';
}

void main() async {
  // Read input from stdin (assembly code)
  stdout.write('Enter assembly code (end with .END):\n');
  var lines = <String>[];
  while (true) {
    final line = await stdin.readLineSync();
    if (line == null || line.trim().toUpperCase() == '.END') break;
    lines.add(line);
  }

  try {
    // Parse each line into an instruction
    for (final line in lines) {
      final parts = line.split(/\s+/).where((p) => p.isNotEmpty).toList();
      if (parts.isEmpty) continue;

      final opCode = parts[0].toUpperCase();

      switch (opCode) {
        case 'ADD':
          if (parts.length != 3) throw FormatException('Invalid ADD instruction format');
          final operand1 = parts[1];
          final operand2 = parts[2];
          print(AssemblyInstruction('ADD', [operand1, operand2]));
          break;

        case 'SUB':
          if (parts.length != 3) throw FormatException('Invalid SUB instruction format');
          final operand1 = parts[1];
          final operand2 = parts[2];
          print(AssemblyInstruction('SUB', [operand1, operand2]));
          break;

        case 'MOV':
          if (parts.length != 3) throw FormatException('Invalid MOV instruction format');
          final src = parts[1];
          final dest = parts[2];
          print(AssemblyInstruction('MOV', [src, dest]));
          break;

        default:
          print('Unknown opcode: $opCode');
      }
    }
  } catch (e) {
    print('Error parsing assembly code: $e');
  }
}
