  final List<Vector2> points;

  Candidate(this.points);

  Vector3 computeResultantForce() {
    double totalMagnitude = 0.0;
    double xSum = 0.0, ySum = 0.0, zSum = 0.0;

    for (int i = 0; i < points.length; i++) {
      Vector2 point = points[i];
      // Calculate vector from center to current point
      double dx = point.x - 0.5 * windowWidth;
      double dy = point.y - 0.5 * windowHeight;

      // Normalize and scale the force magnitude based on distance
      double distance = sqrt(dx*dx + dy*dy);
      if (distance == 0) continue; // Avoid division by zero
      double forceMagnitude = pow(distance, -2); 
      double forceX = (dx / distance) * forceMagnitude;
      double forceY = (dy / distance) * forceMagnitude;

      // Accumulate forces along all three axes with damping
      xSum += forceX;
      ySum += forceY;
      zSum += 0; // Assuming no vertical component initially

      totalMagnitude += forceMagnitude;
    }

    return new Vector3(xSum, ySum, zSum).normalize();
  }

  void applyForcesToPoints(double strengthFactor) {
    for (int i = 0; i < points.length; i++) {
      Vector2 point = points[i];
      double dx = point.x - 0.5 * windowWidth;
      double dy = point.y - 0.5 * windowHeight;

      // Calculate force vector based on position
      double distance = sqrt(dx*dx + dy*dy);
      if (distance == 0) continue;
      double forceMagnitude = pow(0.675/distance, 2) * strengthFactor;
      double forceX = (dx / distance) * forceMagnitude;
      double forceY = (dy / distance) * forceMagnitude;

      // Apply force using a simple Euler integration method
      point.x -= forceX;
      point.y -= forceY;

      // Add some noise to avoid getting stuck in local minima
      point.x += sin(i.toDouble()) * 0.01;
      point.y += cos(i.toDouble()) * 0.01;
    }
  }
