import 'package:collection/collection.dart';

class Candidate {
  final String name;
  final int age;

  const Candidate(this.name, this.age);

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is Candidate &&
          runtimeType == other.runtimeType &&
          name == other.name &&
          age == other.age;

  @override
  int get hashCode => Object.hash(name, age);
}

extension Candidates on List<Candidate> {
  // Sort candidates by name and then by age.
  List<Candidate> sortByNameAndAge() {
    return sorted((a, b) => a.name.compareTo(b.name) != 0 ? a.name.compareTo(b.name) : a.age.compareTo(b.age));
  }

  // Group candidates into groups of size N. If the total number isn't divisible by N,
  // the last group will have fewer elements.
  List<List<Candidate>> groupBySize(int size) {
    if (size < 1) throw ArgumentError('Group size must be at least 1');

    var result = [];
    for (var i = 0; i < length; i += size) {
      result.add(sublist(i, i + size).take(size).toList());
    }
    return result;
  }

  // Find all candidates with names that start with the given prefix.
  List<Candidate> filterNamesWithPrefix(String prefix) {
    return where((candidate) => candidate.name.startsWith(prefix)).toList();
  }

  // Check if there are any duplicates in the list based on [==] operator.
  bool hasDuplicates() {
    Set<Candidate> seen = {};
    for (final c in this) {
      if (seen.contains(c)) return true;
      seen.add(c);
    }
    return false;
  }

  // Compute the average age among all candidates.
  double computeAverageAge() {
    if (isEmpty) return 0.0;
    num sum = 0.0;
    for (final c in this) {
      sum += c.age.toDouble();
    }
    return sum / length;
  }

  // Filter out duplicate entries keeping only the first occurrence.
  List<Candidate> removeDuplicates() {
    Map<String, Candidate> map = {};
    for (final c in this) {
      if (!map.containsKey(c.name)) {
        map[c.name] = c;
      }
    }
    return map.values.toList();
  }
}
