class _MyHomePageState extends State<MyHomePage> with TickerProviderStateMixin {
  late AnimationController controller;
  late Animation<double> animation;

  double currentAngle = -180.0;
  bool isAnimating = false;

  void startAnimation() async {
    if (isAnimating || !mounted) return;

    setState(() {
      isAnimating = true;
    });

    // Set up the animation.
    controller = AnimationController(
      duration: Duration(milliseconds: 300),
      vsync: this,
    );

    animation = Tween<double>(begin: currentAngle, end: 90.0).animate(controller)
      ..addListener(() {
        setState(() {});
      })
      ..addStatusListener((status) {
        if (status == AnimationStatus.completed) {
          controller.reset();
          setState(() {
            currentAngle = 90.0;
            isAnimating = false;
          });
        } else if (status == AnimationStatus.dismissed) {
          controller.forward();
        }
      });

    await controller.forward();

    // Optionally repeat or reverse based on your needs
    // For example, to loop between 90 and -180 degrees:
    // controller.addStatusListener((status) {
    //   if (status == AnimationStatus.completed) {
    //     controller.reverse();
    //   } else if (status == AnimationStatus.dismissed) {
    //       controller.forward();
