final String assembly = '''
    add r0, r1, r2
    sub r3, r4, r5
    mul r6, r7, r8
    div r9, r10, r11
    and r12, r13, r14
    or  r15, r16, r17
    xor r18, r19, r20
    not r21, r22
    mov r23, r24
    ldr r25, [r26]
    str r27, [r28]
''';

void candidate() {
  final List<String> instructions = assembly.split('\n');

  for (var instruction in instructions) {
    if (instruction.trim().isEmpty) continue;

    final parts = instruction.trim().split(' ');
    var op = parts[0];
    var regA = parts[1];
    var regB = parts.length > 2 ? parts[2] : '';

    switch(op.toLowerCase()) {
      case 'add':
        print("Adding $regA + $regB");
        break;
      case 'sub':
        print("Subtracting $regB from $regA");
        break;
      case 'mul':
        print("Multiplying $regA * $regB");
        break;
      case 'div':
        print("Dividing $regA by $regB");
        break;
      case 'and':
        print("AND operation between $regA and $regB");
        break;
      case 'or':
        print("OR operation between $regA and $regB");
        break;
      case 'xor':
        print("XOR operation between $regA and $regB");
        break;
      case 'not':
        print("NOT operation on $regA");
        break;
      case 'mov':
        print("Moving value of $regB to $regA");
        break;
      case 'ldr':
        print("Loading value at address stored in $regA into $regB");
        break;
      case 'str':
        print("Storing value in $regA into memory location pointed by $regB");
        break;
      default:
        print("Unknown instruction: $op");
    }
  }
}
