class NativeFunction<T extends Function> {
  late T? _function;

  NativeFunction(FunctionPointer fp) : super() {
    if (fp == null) throw ArgumentError.notNull("ptr");

    try {
      _function = T.fromAddress(fp.address as IntPtr).call;
    } on FormatException catch (_) {
      print("Could not cast function pointer to type $T.");
    }
  }

  dynamic call([dynamic args]) {
    return _function!(args);
