class Candidate {
  final int id;
  final String name;

  const Candidate({required this.id, required this.name});

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is Candidate &&
          runtimeType == other.runtimeType &&
          id == other.id &&
          name == other.name;

  @override
  int get hashCode => id.hashCode ^ name.hashCode;

  static List<Candidate> fromJson(List<dynamic> jsonList) {
    return jsonList.map((json) => Candidate(
        id: json['id'] as int,
        name: json['name'] as String)).toList();
  }
}

void main() {
  // Example usage:
  var candidates = [
    {'id': 1, 'name': 'Alice'},
    {'id': 2, 'name': 'Bob'}
  ];

  var candidateList = Candidate.fromJson(candidates);

  print(candidateList[0].name); // Output: Alice
}
