import 'dart:math';

class Candidate {
  final List<int> _values;

  Candidate(this._values);

  int get length => _values.length;

  void add(int value) {
    if (value < 0 || value > 100) throw ArgumentError("Value must be between 0 and 100");
    _values.add(value);
  }

  double computeAverage() {
    if (_values.isEmpty) return 0.0;

    int sum = 0;
    for (int value in _values) {
      sum += value;
    }
    return sum / length.toDouble();
  }

  bool isAllValuesEqualTo(int target) {
    if (_values.isEmpty) return false;

    int firstValue = _values[0];
    if (firstValue != target) return false;

    for (int i = 1; i < _values.length; i++) {
      if (_values[i] != firstValue) return false;
    }
    return true;
  }

  int findMaximum() {
    if (_values.isEmpty) throw Exception("List is empty");

    int maxVal = _values[0];
    for (int val in _values) {
      if (val > maxVal) {
        maxVal = val;
      }
    }
    return maxVal;
  }

  int findMinimum() {
    if (_values.isEmpty) throw Exception("List is empty");

    int minVal = _values[0];
    for (int val in _values) {
      if (val < minVal) {
        minVal = val;
      }
    }
    return minVal;
  }

  String describeData() {
    if (_values.isEmpty) return "No data available";

    int count = _values.length;
    double average = computeAverage();
    int maximum = findMaximum();
    int minimum = findMinimum();
    bool allSame = isAllValuesEqualTo(_values[0]);

    return "Data has $count entries, average of $average, with a range from $minimum to $maximum. All values are the same? $allSame.";
  }
}
