class Triangle {
  final Point2D _a;
  final Point2D _b;
  final Point2D _c;

  Triangle(Point2D a, Point2D b, Point2D c)
      : _a = a,
        _b = b,
        _c = c;

  double get area => calculateArea();

  double calculateArea() {
    var abx = (_b.x - _a.x).toDouble(); 
    var aby = (_b.y - _a.y).toDouble();

    var acx = (_c.x - _a.x).toDouble();
    var acy = (_c.y - _a.y).toDouble();

    var crossProduct = (abx * acy) - (aby * acx); 

    return abs((crossProduct)/2.0);
  }

  void render(Canvas canvas) {
    Paint trianglePaint = Paint()
      ..color = Colors.black.withOpacity(1.0)
      ..style = PaintingStyle.fill;

    Path trianglePath = Path();
    trianglePath.moveTo(_a.x.toDouble(), _a.y.toDouble());
    trianglePath.lineTo(_b.x.toDouble(), _b.y.toDouble());
    trianglePath.lineTo(_c.x.toDouble(), _c.y.toDouble());
    trianglePath.close();

    canvas.drawPath(trianglePath, trianglePaint);
  }
}

