class Graph<T> {
  Map<T, List<Edge<T>>> _adjacencyList = {};
  Set<T> _nodes = {};

  void addNode(T node) {
    if (!_nodes.contains(node)) {
      _nodes.add(node);
      _adjacencyList[node] = [];
    }
  }

  void addEdge(T source, T destination, {double? weight}) {
    if (_nodes.contains(source) && _nodes.contains(destination)) {
      _adjacencyList[source]!.add(Edge<T>(source, destination, weight));
      _adjacencyList[destination]!.add(Edge<T>(destination, source, weight)); 
    }
  }

  DijkstraResult<T> dijkstra(T start, T end) {
    final distances = <T, double>{};
    final previousNodes = <T, T>{};

    final priorityQueue = PriorityQueue<MapEntry<T, double>>((a, b) => a.value.compareTo(b.value));

    for (final node in _nodes) {
      distances[node] = double.infinity;
      priorityQueue.add(MapEntry(node, double.infinity));
    }

    distances[start] = 0.0;

    while (!priorityQueue.isEmpty) {
      final current = priorityQueue.removeFirst();
      if (current.key == end) break;

      if (distances[current.key]! < current.value) continue;

      for (final edge in _adjacencyList[current.key]!) {
        final newDistance = distances[current.key!] + edge.weight!;

        if (newDistance < distances[edge.destination]) {
          distances[edge.destination] = newDistance;
          previousNodes[edge.destination] = current.key;
          priorityQueue.add(MapEntry(edge.destination, newDistance));
        }
      }
    }

    return buildDijkstraResult(start, end, distances, previousNodes);
  }

  DijkstraResult<T> buildDijkstraResult(
    T start,
    T end,
    Map<T, double> distances,
    Map<T, T> previousNodes,
  ) {
    final result = DijkstraResult<T>();

    if (!distances.containsKey(end)) {
      throw Exception('No path found between $start and $end.');
    } else if (distances[end] == double.infinity) {
      throw Exception('No path found between $start and $end.');
    }

    result.distance = distances[end];

    final path = <T>[];
    T currentNode = end;
    while (currentNode != null) {
      path.add(currentNode);
      currentNode = previousNodes[currentNode];
    }

    result.path = path.reversed.toList();

    return result;
  }
}

class Edge<T> {
  final T source;
  final T destination;
  final double? weight;

  Edge(this.source, this.destination, this.weight);
} 

