String candidate(String input) {
  int sum = 0;
  bool flag = true;

  for (int i = 0; i < input.length; i++) {
    if (input[i] == '(') {
      sum--;
    } else if (input[i] == ')') {
      sum++;
    } else if (input[i] == '[') {
      sum -= 2;
    } else if (input[i] == ']') {
      sum += 2;
    } else if (input[i].isDigit()) {
      sum += int.parse(input[i]);
    }

    if (sum < 0) {
      flag = false;
      break;
    }
  }

  return flag ? 'Valid' : 'Invalid';
