abstract class ElectionResult {
  List<Candidate> get candidates;
  int get winnerId; // ID of the winning candidate
  double get voteCount; // Total votes cast in the election
  double get voterTurnoutPercentage; // Percentage of voters who participated
}

class SimpleElection implements ElectionResult {
  final Map<int, List<int>> _votesByCandidate;
  final Set<int> _voters;

  SimpleElection({
    required Map<int, List<int>> votesByCandidate,
    required Set<int> voters,
  }) : 
    _votesByCandidate = votesByCandidate,
    _voters = voters;

  @override
  List<Candidate> get candidates {
    return _votesByCandidate.entries.map((entry) => Candidate(id: entry.key, name: 'Candidate ${entry.key}')).toList();
  }

  @override
  int get winnerId {
    if (_votesByCandidate.isEmpty) throw Exception('No candidates');

    var maxVotes = -1;
    var winnerId = -1;

    for (var entry in _votesByCandidate.entries) {
      var totalVotesForCandidate = entry.value.length.toDouble();

      if (totalVotesForCandidate > maxVotes) {
        maxVotes = totalVotesForCandidate;
        winnerId = entry.key;
      }
    }

    return winnerId;
  }

  @override
  double get voteCount {
    return _voters.length.toDouble(); // Assuming each voter casts one vote
  }

  @override
  double get voterTurnoutPercentage {
    if (_voters.isEmpty) return 0.0;

    return (_voteCount / 10000.0).toDouble() * 100; // Assume 10,000 registered voters as a fixed base
  }
}
