void candidate() {
  final List<int> numbers = [3, 1, 4, 2];

  for (int i = 0; i < numbers.length - 1; i++) {
    bool swapped = false;

    // Traverse the array from 0 to n-i-1
    for (int j = 0; j < numbers.length - i - 1; j++) {
      if (numbers[j] > numbers[j + 1]) {
        // Swap elements if they are in wrong order
        int temp = numbers[j];
        numbers[j] = numbers[j + 1];
        numbers[j + 1] = temp;
        swapped = true;
      }
    }

    // If no swaps were made, the list is sorted and we can break early
    if (!swapped) break;
  }

  print('Sorted list:');
  for (var num in numbers) {
    stdout.write('$num ');
  }
}
