import 'package:vector_math/vector_math.dart';

class Candidate {
  final List<Vector3> _vertices;

  Candidate(this._vertices);

  double computeArea() {
    if (_vertices.length < 3) return 0.0;

    // Calculate the area using the shoelace formula for polygons.
    int n = _vertices.length;
    double area = 0.0;

    for (int i = 0; i < n; i++) {
      Vector3 current = _vertices[i];
      Vector3 next = _vertices[(i + 1) % n];

      area += current.x * next.y - next.x * current.y;
    }

    return area.abs() / 2.0;
  }
}
