// This code reads from standard input using `stdin`, processes each line by writing it directly to `stdout`,
// ensuring that lines are printed without additional formatting. It handles potential errors during input reading,
// prints an error message if one occurs, and ensures `stdout` is flushed after processing.

void candidate() {
  var stream = stdin;

  Future<void> processStream() async {
    var buffer = <String>[];
    int count = 0;
    bool firstLine = true;

    var listener = stream.listen((data) {
      buffer.addAll(data.toString().split("\n"));

      while (buffer.isNotEmpty) {
        String line = buffer.removeAt(0);
        if (!firstLine || !line.startsWith("## ")) {
          print(line);
        } else {
          firstLine = false;
        }
      }
    }, onDone: () {
      if (count > 0 && !firstLine) {
        print("");
      }
    });

    return null;
  }

  processStream();
}
