class Candidate {
  final String name;
  final int score;

  const Candidate({required this.name, required this.score});

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is Candidate &&
          runtimeType == other.runtimeType &&
          name == other.name &&
          score == other.score;

  @override
  int get hashCode => Object.hash(name, score);
}

List<Candidate> filterCandidates(List<Candidate> candidates, {int? minScore}) {
  if (minScore == null || minScore < 0) return [...candidates];

  List<Candidate> filtered = [];
  for (var candidate in candidates) {
    if (candidate.score >= minScore) {
      filtered.add(candidate);
    }
  }
  return filtered;
}
