import 'package:vector_math/vector_math.dart';

class Vector3D {
  final double x;
  final double y;
  final double z;

  const Vector3D({required this.x, required this.y, required this.z});

  factory Vector3D.fromList(List<double> list) {
    return Vector3D(x: list[0], y: list[1], z: list[2]);
  }

  static List<Vector3D> fromPoints(Iterable<Point> points) {
    final result = <Vector3D>[];
    for (final point in points) {
      result.add(Vector3D(
        x: point.x,
        y: point.y,
        z: point.z,
      ));
    }
    return result;
  }

  static void copyFromTo(Vector3D source, Vector3D target) {
    target.x = source.x;
    target.y = source.y;
    target.z = source.z;
  }

  static void addVectors(Vector3D v1, Vector3D v2, Vector3D out) {
    out.x = v1.x + v2.x;
    out.y = v1.y + v2.y;
    out.z = v1.z + v2.z;
  }

  static void subtractVectors(Vector3D v1, Vector3D v2, Vector3D out) {
    out.x = v1.x - v2.x;
    out.y = v1.y - v2.y;
    out.z = v1.z - v2.z;
  }

  static void multiplyByScalar(Vector3D vector, double scalar, Vector3D out) {
    out.x = vector.x * scalar;
    out.y = vector.y * scalar;
    out.z = vector.z * scalar;
  }

  static void normalize(Vector3D vector, Vector3D out) {
    final length = sqrt(vector.x * vector.x + vector.y * vector.y + vector.z * vector.z);
    if (length == 0.0) {
      // Avoid division by zero.
      out.x = 0.0;
      out.y = 0.0;
      out.z = 0.0;
    } else {
      out.x = vector.x / length;
      out.y = vector.y / length;
      out.z = vector.z / length;
    }
  }

  static double dotProduct(Vector3D a, Vector3D b) {
    return a.x * b.x + a.y * b.y + a.z * b.z;
  }

  static double crossProductLength(Vector3D a, Vector3D b) {
    final lenX = a.y * b.z - a.z * b.y;
    final lenY = a.z * b.x - a.x * b.z;
    final lenZ = a.x * b.y - a.y * b.x;
    return sqrt(lenX * lenX + lenY * lenY + lenZ * lenZ);
  }

  static void crossProduct(Vector3D a, Vector3D b, Vector3D out) {
    out.x = a.y * b.z - a.z * b.y;
    out.y = a.z * b.x - a.x * b.z;
    out.z = a.x * b.y - a.y * b.x;
  }

  @override
  String toString() => '($x, $y, $z)';
}

abstract class Point {
  double get x;
  double get y;
  double get z;
}
