class Candidate {
  final String name;

  const Candidate({required this.name});

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is Candidate &&
          runtimeType == other.runtimeType &&
          name == other.name;

  @override
  int get hashCode => name.hashCode;

  static Map<String, Candidate> fromMap(Map<String, dynamic>? map) {
    if (map == null || map.isEmpty) return {};
    var candidates = <String, Candidate>{};
    for (var entry in map.entries) {
      if (!entry.value.containsKey('name')) continue;
      var candidateName = entry.value['name'] as String?;
      if (candidateName != null && !candidates.containsKey(candidateName)) {
        candidates[candidateName] = Candidate(name: candidateName);
      }
    }
    return candidates;
  }

  static List<Candidate> sortCandidatesByVoteCount(
      Map<String, dynamic>? votes) {
    if (votes == null || votes.isEmpty) return [];

    // Convert the vote counts to a list of maps with names and vote counts
    List<Map<String, dynamic>> sortedVotes = votes.entries.map((e) {
      return {'name': e.key, 'count': e.value};
    }).toList();

    // Sort by vote count descending
    sortedVotes.sort((a, b) => b['count'].compareTo(a['count']));

    // Extract only the names of the candidates in order of their votes
    List<String> orderedNames = sortedVotes.map((vote) => vote['name']).toList();
    return orderedNames.map(Candidate.fromName).toList();
  }

  static Candidate? findCandidateByName(String name,
      [Map<String, Candidate>? candidates]) {
    if (candidates == null) candidates = fromMap({});
    return candidates[name];
  }

  factory Candidate.fromName(String name) {
    return Candidate(name: name);
  }
}
