class Candidate {
  static int calculateSum(List<int> numbers) {
    if (numbers == null || numbers.isEmpty) return 0;

    int sum = 0;
    for (int num in numbers) {
      sum += num;
    }
    return sum;
  }

  static List<int> filterEvenNumbers(List<int> numbers) {
    if (numbers == null || numbers.isEmpty) return [];

    List<int> evenNumbers = [];
    for (int num in numbers) {
      if (num % 2 == 0) {
        evenNumbers.add(num);
      }
    }
    return evenNumbers;
  }

  static int findMaxValue(List<int> numbers) {
    if (numbers == null || numbers.isEmpty) return -1;

    int maxVal = numbers[0];
    for (int i = 1; i < numbers.length; i++) {
      if (numbers[i] > maxVal) {
        maxVal = numbers[i];
      }
    }
    return maxVal;
  }

  static bool containsNumber(List<int> numbers, int target) {
    if (numbers == null || numbers.isEmpty) return false;

    for (int num in numbers) {
      if (num == target) {
        return true;
      }
    }
    return false;
  }
}
