import 'package:collection/collection.dart';
import 'dart:convert';

class Candidate {
  final int id;
  final String name;

  const Candidate({required this.id, required this.name});

  factory Candidate.fromJson(Map<String, dynamic> json) {
    return Candidate(
      id: json['id'] as int,
      name: json['name'] as String,
    );
  }
}

List<Candidate> parseCandidates(String input) {
  List<Map<String, dynamic>> candidatesData = [];

  for (int i = 0; i < input.length; i++) {
    if (input[i] == '{') {
      var start = i + 1;
      var end = input.indexOf('}', i);

      while (end != -1 && end > i) {
        // Extract the JSON string and decode it
        String jsonString = input.substring(start, end);
        Map<String, dynamic> candidateJson = jsonDecode(jsonString);

        // Add to list of parsed data
        candidatesData.add(candidateJson);

        // Move past the current JSON object
        i = end;
        start = i + 1;
        end = input.indexOf('}', i);
      } 
    }
  }

  return candidatesData.map((data) => Candidate.fromJson(data)).toList();
}
