      identical(this, other) ||
      other is Candidate &&
          runtimeType == other.runtimeType &&
          name == other.name &&
          score == other.score;

  @override
  int get hashCode => Object.hash(name, score);
}

List<Candidate> findTopCandidates(List<Candidate> candidates, int topN) {
  if (candidates.isEmpty || topN <= 0) return [];

  // Sort by score descending and then by name ascending for tie-breaker
  List<Candidate> sorted = [...candidates]
    ..sort((a, b) {
      if (a.score != b.score) {
        return b.score.compareTo(a.score); // Descending order of scores
      } else {
        return a.name.compareTo(b.name); // Ascending alphabetical order for names
      }
    });

  return sorted.take(topN).toList();
}
