// This is a helper function that processes each line of input and parses it into a matrix.
String parseMatrix(String inputLine, int n) {
  var tokens = inputLine.split(' ').where((token) => token.isNotEmpty).toList();

  if (tokens.length != (n * n)) {
    throw FormatException(
      "Invalid number of elements. Expected ${n*n}, got ${tokens.length}");
  }

  List<List<int>> matrix = List.generate(n, (_) => List<int>.filled(n, 0));
  int index = 0;

  for (var i = 0; i < n; i++) {
    for (var j = 0; j < n; j++) {
      matrix[i][j] = int.tryParse(tokens[index]) ?? 0;
      index++;
    }
  }

  return matrix.toString(); 
}

