class Result {
  final List<Candidate> candidates;
  final Map<int, int> totalVotes;
  final Map<String, int> candidateCounts;

  const Result({
    required this.candidates,
    required this.totalVotes,
    required this.candidateCounts,
  });

  @override
  String toString() {
    return 'Result{candidates: $candidates, '
        'totalVotes: $totalVotes, '
        'candidateCounts: $candidateCounts}';
  }

  static Result fromJson(Map<String, dynamic> json) {
    var candidates = <Candidate>[];
    if (json.containsKey('candidates')) {
      for (var c in json['candidates']) {
        candidates.add(Candidate.fromJson(c));
      }
    } else {
      // Handle case where 'candidates' key is not present or empty
      candidates = [];
    }

    var totalVotesMap = <int, int>{};
    if (json.containsKey('total_votes') && json['total_votes'] != null) {
      for (final entry in json['total_votes'].entries) {
        totalVotesMap[entry.key] = entry.value.toInt();
      }
    } else {
      totalVotesMap = {};
    }

    var candidateCountMap = <String, int>{};
    if (json.containsKey('candidate_counts') && json['candidate_counts'] != null) {
      for (final entry in json['candidate_counts'].entries) {
        candidateCountMap[entry.key] = entry.value.toInt();
      }
    } else {
      candidateCountMap = {};
    }

    return Result(
      candidates: candidates,
      totalVotes: totalVotesMap,
      candidateCounts: candidateCountMap,
    );
  }
}
