import 'package:vector_math/vector_math.dart' as vec;

class Candidate {
  final int id;
  late String name;
  double score = -1.0;

  // Initialize a candidate with an ID and a name.
  Candidate(this.id, this.name);

  void calculateScore(List<double> weights) {
    if (weights.length != 3) throw ArgumentError('Weights must have exactly three elements.');

    // Calculate the weighted sum of scores based on given weights.
    var total = 0.0;
    for (var i = 0; i < 3; i++) {
      total += weights[i] * getSkill(i);
    }

    score = total / weights.reduce((a, b) => a + b); // Normalize by sum of weights
  }

  double getSkill(int index) {
    switch(index) {
      case 0:
        return _getSkillLevel(45.0, 25.0, 98.0); // Mathematics
      case 1:
        return _getSkillLevel(65.0, 35.0, 70.0); // Programming
      case 2:
        return _getSkillLevel(50.0, 20.0, 80.0); // Communication
      default:
        throw Exception("Invalid skill index");
    }
  }

  static double _getSkillLevel(double avg, double stdDev, double max) {
    // Simulate skill level using normal distribution parameters.
    var randomValue = Vector2.random(vec.RandomSource.secure(), 0.0, 1.0).x * max;
    return ((randomValue - avg) / stdDev) * max; // Linear transformation to scale between 0-1
  }

  @override
  String toString() {
    return '$name (ID $id): Score $score';
  }
}
