import 'dart:io';

// Function to convert a string representation of an assembly instruction into its corresponding Dart function.
String assemble(String input) {
  final lines = input.split('\n');
  final outputLines = <String>[];

  for (final line in lines) {
    if (line.trim().isEmpty) continue;

    // Split the line into parts, assuming whitespace as separator
    final parts = line.split(' ');
    final opCode = parts[0].trim();

    switch (opCode.toLowerCase()) {
      case 'mov':
        if (parts.length == 3 && parts[1] != '') {
          final registerDest = parts[1];
          final valueOrRegisterSource = parts[2];

          String sourceValue = '';
          if (valueOrRegisterSource.startsWith('%')) {
            sourceValue = '$valueOrRegisterSource';
          } else if (int.tryParse(valueOrRegisterSource) != null) {
            sourceValue = '"$valueOrRegisterSource"';
          }

          outputLines.add(
              "register\$registerDest = \$sourceValue;");
        }
        break;

      case 'add':
        if (parts.length >= 4 && parts[1] != '' && parts[2] != '' && parts[3] != '') {
          final registerDest = parts[1];
          final registerSrc1 = parts[2];
          final registerSrc2 = parts[3];

          outputLines.add("register\$registerDest = register\$registerSrc1 + register\$registerSrc2;");
        }
        break;

      case 'sub':
        if (parts.length >= 4 && parts[1] != '' && parts[2] != '' && parts[3] != '') {
          final registerDest = parts[1];
          final registerSrc1 = parts[2];
          final registerSrc2 = parts[3];

          outputLines.add("register\$registerDest = register\$registerSrc1 - register\$registerSrc2;");
        }
        break;

      case 'mul':
        if (parts.length >= 4 && parts[1] != '' && parts[2] != '' && parts[3] != '') {
          final registerDest = parts[1];
          final registerSrc1 = parts[2];
          final registerSrc2 = parts[3];

          outputLines.add("register\$registerDest = register\$registerSrc1 * register\$registerSrc2;");
        }
        break;

      case 'div':
        if (parts.length >= 4 && parts[1] != '' && parts[2] != '' && parts[3] != '') {
          final registerDest = parts[1];
          final registerSrc1 = parts[2];
          final registerSrc2 = parts[3];

          outputLines.add("register\$registerDest = register\$registerSrc1 ~/ register\$registerSrc2;");
        }
        break;

      case 'cmp':
        if (parts.length >= 4 && parts[1] != '' && parts[2] != '' && parts[3] != '') {
          final registerSrc1 = parts[1];
          final registerSrc2 = parts[2];

          outputLines.add("if (register\$registerSrc1 > register\$registerSrc2) { flag = 1; } else { flag = 0; }");
        }
        break;

      default:
        // For other instructions or invalid ones, we just pass through as comments
        outputLines.add("// Unknown or unimplemented instruction: $line");
    }
  }

  return outputLines.join('\n');
}
