import 'dart:math';

int candidate(int n) {
  if (n == 0 || n == 1) return 1;

  int result = 0;
  for (var i = 2; i <= sqrt(n); i++) {
    var count = 0;
    while (n % i == 0) {
      n ~/= i;
      count++;
    }
    if (count > 0) {
      result += count;
    }
  }
  if (n > 1) {
    result += 1;
  }
  return result;
}
