int calculatePrimeFactorCount(int number) {
  if (number < 2) return 0;

  int totalFactors = 0;
  int divisor = 2;

  // Check even numbers first
  while (number % divisor == 0) {
    totalFactors++;
    number ~/= divisor;
  }

  // Check odd divisors from 3 upwards
  for (divisor = 3; divisor * divisor <= number; divisor += 2) {
    while (number % divisor == 0) {
      totalFactors++;
      number ~/= divisor;
    }
  }

  // If remaining number is greater than 1, it's a prime factor
  if (number > 1) {
    totalFactors++;
  }

  return totalFactors;
}

// Example usage:
void main() {
  print(calculatePrimeFactorCount(6)); // Output: 2 (factors are 2 and 3)
  print(calculatePrimeFactorCount(12)); // Output: 3 (factors are 2^2*3)
  print(calculatePrimeFactorCount(7)); // Output: 1 (prime number)
}
