  for (int i = 1; i < lines.length; i++) {
    if (lines[i].trim().isEmpty) continue;
    var parts = lines[i].split(': ');
    if (parts.length != 2) continue;
    String name = parts[0];
    int score = int.parse(parts[1]);
    candidates.add(Candidate(name, score));
  }

  return candidates;
}

