  // Read input from stdin
  String? input = await stdin.readLinesSync();

  // Parse the input into a list of Candidate objects
  List<Candidate> candidates = parseCandidates(input!);

  // Sort the candidates by their scores in descending order
  candidates.sort((a, b) => b.score.compareTo(a.score));

  // Print the sorted results
  print("Sorted Candidates by Score:");
  for (Candidate candidate in candidates) {
    print("${candidate.name}: ${candidate.score}");
  }
