  int get hashCode => Object.hash(name, score);
}

extension Candidates on List<Candidate> {
  List<String> toNames() => map((c) => c.name).toList();
  int maxScore() => fold(0, (max, candidate) => max > candidate.score ? max : candidate.score);
  Map<int, List<String>> groupByScore() {
    if (isEmpty) return {};

    final scores = setOf(score);
    final grouped = <int, List<String>>{};

    for (final s in scores) {
      grouped[s] = where((c) => c.score == s).toNames();
    }

    return grouped;
  }

  double averageScore() => length != 0 ? reduce((a, b) => a + b.score) / length : 0.0;

  // Helper method to find candidates with the highest score(s)
  List<String> topCandidates(int count) {
    final sorted = sortedBy((a, b) => b.score.compareTo(a.score));
    final maxScore = sorted.first?.score ?? 0;
    final maxScores = groupByScore()[maxScore];
    return maxScores!.take(count).toList(); 
  }  

  // Sort by score descending and then alphabetically ascending
  List<Candidate> sortedByScoreThenName() => sorted(
        (a, b) => b.score.compareTo(a.score) != 0
            ? b.score.compareTo(a.score)
            : a.name.compareTo(b.name),
      );
}
