import 'dart:io';
import 'package:image/image.dart' as image;

void main() {
  final input = stdin.readLinesSync();

  for (final line in input) {
    if (line.isEmpty) continue;

    // Parse the assembly code into instructions
    final tokens = line.split(' ');
    final opCode = tokens[0];
    final operands = List<int>.from(tokens.skip(1).map(int.parse));

    switch (opCode) {
      case 'MOV':
        _executeMov(operands);
        break;
      case 'ADD':
        _executeAdd(operands);
        break;
      case 'SUB':
        _executeSub(operands);
        break;
      case 'MUL':
        _executeMul(operands);
        break;
      case 'DIV':
        _executeDiv(operands);
        break;
      case 'JMP':
        _executeJump(operands);
        break;
      case 'CMP':
        _executeCompare(operands);
        break;
      case 'PUSH':
        _executePush(operands);
        break;
      case 'POP':
        _executePop(operands);
        break;
      default:
        print("Unknown instruction");
    }
  }
}

void _executeMov(List<int> operands) {
  int sourceRegister = operands[0];
  int destinationRegister = operands[1];
  registers[destinationRegister] = registers[sourceRegister];
}

void _executeAdd(List<int> operands) {
  int registerA = operands[0];
  int registerB = operands[1];
  int result = registers[registerA] + registers[registerB];
  registers[registerA] = result;
}

void _executeSub(List<int> operands) {
  int registerA = operands[0];
  int registerB = operands[1];
  int result = registers[registerA] - registers[registerB];
  registers[registerA] = result;
}

void _executeMul(List<int> operands) {
  int registerA = operands[0];
  int registerB = operands[1];
  int result = registers[registerA] * registers[registerB];
  registers[registerA] = result;
}

void _executeDiv(List<int> operands) {
  int registerA = operands[0];
  int registerB = operands[1];
  int result = registers[registerA] ~/ registers[registerB];
  registers[registerA] = result;
}

void _executeJump(List<int> operands) {
  int address = operands[0];
  pc = address;
}

void _executeCompare(List<int> operands) {
  int registerA = operands[0];
  int registerB = operands[1];
  if (registers[registerA] > registers[registerB]) {
    flags['gt'] = true;
  } else {
    flags['gt'] = false;
  }
}

void _executePush(List<int> operands) {
  int value = operands[0];
  stack.add(value);
}

void _executePop(List<int> operands) {
  if (stack.isNotEmpty) {
    int value = stack.removeLast();
    registers[operands[0]] = value;
  }
}
