import 'dart:io';
import 'dart:convert';

void main() {
  // Read the input from stdin as a single string, trimming whitespace and splitting by newlines.
  final input = stdin.readLinesSync().join('\n').trim();

  if (input.isEmpty) {
    print('No input provided.');
    return;
  }

  try {
    // Parse the input into JSON format using jsonDecode.
    var data = jsonDecode(input);

    // Check if the parsed data is a map with a key "instructions".
    if (!data.containsKey("instructions")) {
      throw FormatException("Missing required field 'instructions'");
    }

    String instructions = data["instructions"];
    List<String> steps = instructions.split("; ").map((step) => step.trim()).toList();

    int totalSteps = steps.length;

    bool completed = false;
    for (int i = 0; i < totalSteps && !completed; i++) {
      String currentStep = steps[i];

      // Determine if the current instruction starts with an action or a command.
      if (currentStep.startsWith("do ")) {
        // Extract the action part of the instruction.
        String action = currentStep.substring(3).trim();

        // Execute the corresponding function based on the action.
        switch (action.toLowerCase()) {
          case "print":
            print(currentStep);
            break;
          case "wait":
            sleep(Duration(seconds: int.tryParse(currentStep.replaceAll("wait ", "")) ?? 1));
            break;
          default:
            print("Unknown action: $action");
        }
      } else if (currentStep.startsWith("if ")) {
        // Handle conditional statements starting with "if ".
        String condition = currentStep.substring(3).trim();

        // Split the condition into parts to check the comparison operator and values.
        List<String> conditionParts = condition.split(" ");
        if (conditionParts.length != 3) {
          print("Invalid condition syntax. Expected format: value [operator] value.");
          continue;
        }

        dynamic leftValue;
        String op = conditionParts[1].toLowerCase();
        dynamic rightValue;

        // Try parsing the left and right values as integers or strings.
        try {
          leftValue = int.parse(conditionParts[0]);
          rightValue = int.parse(conditionParts[2]);
        } catch (_) {
          try {
            leftValue = conditionParts[0];
            rightValue = conditionParts[2];
          } catch (_) {
            print("Invalid operands in condition.");
            continue;
          }
        }

        // Evaluate the condition based on the operator.
        bool result = false;
        switch (op) {
          case "==":
            result = leftValue == rightValue;
            break;
          case ">":
            result = leftValue > rightValue;
            break;
          case "<":
            result = leftValue < rightValue;
            break;
          case ">=":
            result = leftValue >= rightValue;
            break;
          case "<=":
            result = leftValue <= rightValue;
            break;
          case "!=":
            result = leftValue != rightValue;
            break;
          default:
            print("Unsupported comparison operator: $op");
            continue;
        }

        // If the condition evaluates to true, execute the next step.
        if (result) {
          completed = true;
          i += 1;
        }
      } else {
        // Default case - treat it as a regular line to be printed.
        print(currentStep);
      }
    }

    print("\nCompleted ${totalSteps} steps successfully!");
  } catch (e) {
    print("Error processing input:\n$e");
  }
}
