import 'package:vector_math/vector_math.dart';

class Candidate {
  static void main() {
    final List<Vector3> points = [
      Vector3(0.0, 0.0, 1.0),
      Vector3(2.0, 0.0, 0.5),
      Vector3(0.0, 1.0, 0.5)
    ];

    // Compute the area of a triangle using Heron's formula
    double area = computeTriangleArea(points);

    print('Area of triangle: $area');
  }

  static double computeTriangleArea(List<Vector3> points) {
    if (points.length != 3) throw ArgumentError("Exactly three points required");

    final p1 = points[0];
    final p2 = points[1];
    final p3 = points[2];

    final ab = p2 - p1;
    final ac = p3 - p1;

    return ab.cross(ac).length / 2;
  }
}
