/// A simple implementation of a linked list with basic operations.
class LinkedList<T> {
  Node? _head;
  int _size = 0;

  // Define the node class inside the linked list class.
  class Node {
    T data;
    Node? next;

    Node(this.data, [this.next]);

    @override
    String toString() => "Node(data: $data)";
  }

  // Add an element to the beginning of the list.
  void addFirst(T value) {
    final newNode = Node(value);
    if (_head == null) {
      _head = newNode;
    } else {
      newNode.next = _head;
      _head = newNode;
    }
    _size++;
  }

  // Add an element at a specific index.
  void addAt(int index, T value) {
    if (index < 0 || index > size) throw ArgumentError('Index out of bounds');
    if (index == 0) {
      addFirst(value);
      return;
    }
    var current = _head;
    for (var i = 1; i < index; i++) {
      if (current?.next != null) {
        current = current!.next;
      } else {
        break;
      }
    }
    if (current != null) {
      final newNode = Node(value, current.next);
      current.next = newNode;
      _size++;
    }
  }

  // Remove an element from a specific index.
  T removeAt(int index) {
    if (index < 0 || index >= size) throw ArgumentError('Index out of bounds');
    if (index == 0) {
      final removedValue = _head!.data;
      _head = _head?.next;
      _size--;
      return removedValue;
    }
    var current = _head;
    for (var i = 1; i < index; i++) {
      if (current?.next != null) {
        current = current!.next;
      } else {
        break;
      }
    }
    if (current != null && current.next != null) {
      final removedValue = current.next!.data;
      current.next = current.next?.next;
      _size--;
      return removedValue;
    } else {
      throw StateError("Cannot remove at this position");
    }
  }

  // Get the element at a specific index.
  T getAt(int index) {
    if (index < 0 || index >= size) throw IndexError();
    var current = _head;
    for (var i = 0; i < index; i++) {
      if (current != null) {
        current = current.next;
      } else {
        break;
      }
    }
    if (current != null) {
      return current.data;
    } else {
      throw StateError("Invalid index");
    }
  }

  // Check if the list contains a certain value.
  bool hasElement(T value) {
    var current = _head;
    while (current != null) {
      if (current.data == value) {
        return true;
      }
      current = current.next;
    }
