      for (var candidate in candidates) {
        votes[candidate.name] = 0;
      }
    });
  }

  void toggleVote(String candidateName) {
    if (!isVotingOpen || votes.containsKey(candidateName)) return;

    setState(() {
      votes[candidateName] = (votes[candidateName] ?? 0) + 1;
    });
  }

  void endVoting() {
    setState(() {
      isVotingOpen = false;
    });
