// Helper function to calculate distance between two points
double calculateDistance(Candidate a, Candidate b) {
  return (a.x - b.x).abs();
}

// Function to find closest neighbor using vector math
Candidate findClosestNeighbor(List<Candidate> candidates, Candidate current) {
  if (candidates.isEmpty) throw Exception('No candidates provided');

  Candidate? closest = candidates[0];
  double minDist = calculateDistance(current, closest);

  for (int i = 1; i < candidates.length; i++) {
    final dist = calculateDistance(current, candidates[i]);
    if (dist < minDist) {
      minDist = dist;
      closest = candidates[i];
    }
  }

  return closest!;
}
