// Main logic to process all candidates and find optimal paths
List<List<Candidate>> solveTSP(List<Candidate> candidates) {
  List<List<Candidate>> routes = [];

  for (var start in candidates) {
    List<Candidate> route = [start];

    // Find next best node from current one
    Candidate curr = start;

    while (route.length < candidates.length) {
      // Find the next nearest unvisited node
      Candidate next = findClosestNeighbor(candidates.where((c) => !route.contains(c)).toList(), curr);

      // Add it to our path
      route.add(next);
      curr = next;
    }

    routes.add(route);
  }

  return routes;
}
