class Candidate {
  final String name;
  final int score;

  const Candidate({required this.name, required this.score});

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
          other is Candidate &&
              runtimeType == other.runtimeType &&
              name == other.name &&
              score == other.score;

  @override
  int get hashCode => Object.hash(name, score);
}

List<Candidate> selectTopN(List<Candidate> candidates, int n) {
  if (n <= 0 || candidates.isEmpty) return [];

  // Sort candidates by score descending and then by name ascending.
  List<Candidate> sorted = [...candidates]
    ..sort((a, b) {
      if (a.score != b.score) return b.score.compareTo(a.score);
      return a.name.compareTo(b.name);
    });

  // Select top N candidates. If there are less than N, just take all.
  return sorted.take(n).toList();
}
```

This code defines a `Candidate` class to represent each candidate with their name and score, and provides a function `selectTopN()` that selects the top N candidates based on their scores. Candidates with equal scores are ordered alphabetically by name.

