import 'package:collection/collection.dart';

void main() {
  var input = """
    #include <stdio.h>

    int main(int argc, char *argv[]) {
      printf("Hello World\n");
      return 0;
    }
  """;

  String output = convertCtoDart(input);
  print(output);
}

String convertCtoDart(String cCode) {
  final lines = cCode.split('\n');
  List<String> dartLines = [];
  bool inFunction = false;

  for (var line in lines) {
    if (!line.startsWith('#')) {
      // Skip any other comments or non-code lines
      continue;
    }

    if (line.contains('main') && !inFunction) {
      inFunction = true;
      dartLines.add('void main() {');
    } else if (line.contains(';')) {
      // Handle function body with semicolons
      if (line.endsWith(';')) {
        dartLines.add(line.replaceFirst(RegExp(r'(\w+)\s*$', '$1;'));
      } else {
        dartLines.add(line);
      }
    } else {
      // Regular code line
      dartLines.add(line);
    }
  }

  if (inFunction) {
    dartLines.add('}');
  }

  return dartLines.join('\n');
}
