List<Candidate> calculateScores(
    List<Map<String, dynamic>> data,
    Map<String, Function(Map<String, dynamic>, num)> evaluatorMap) {
  return data.map((item) {
    var result = item['result'];
    var evaluationFunction = evaluatorMap[item['type']];
    if (evaluationFunction != null && result != null) {
      try {
        var computedScore = evaluationFunction(item, result);
        return Candidate(name: item['name'], score: computedScore.toInt());
      } catch (_) {}
    }
    throw Exception('Evaluation function not found for type ${item['type']}');
  }).whereType<Candidate>().toList();
}
