import 'dart:math' show Random;

// This code implements a basic graph data structure with adjacency list representation.
class Graph {
  final Map<String, List<String>> _adjacencyList = {};

  // Adds a node to the graph
  void addNode(String node) {
    if (!_adjacencyList.containsKey(node)) {
      _adjacencyList[node] = [];
    }
  }

  // Removes a node from the graph (and its edges)
  void removeNode(String node) {
    if (_adjacencyList.containsKey(node)) {
      for (var neighbor in _adjacencyList[node]!) {
        _adjacencyList[neighbor]!.remove(node);
      }
      _adjacencyList.removeWhere((key, value) => key == node);
    }
  }

  // Adds an edge between two nodes (bidirectional)
  void connectNodes(String node1, String node2) {
    addNode(node1); 
    addNode(node2);
    _adjacencyList[node1]!.add(node2);
    _adjacencyList[node2]!.add(node1);
  }

  // Gets all adjacent nodes of a given node
  List<String>? getAdjacentNodes(String node) {
    return _adjacencyList[node];
  }

  // Checks if there's an edge between two nodes
  bool hasEdgeBetween(String node1, String node2) {
    return getAdjacentNodes(node1)?.contains(node2) ?? false;
  }

  // Returns the number of nodes in the graph
  int getNodeCount() => _adjacencyList.length;

  // Returns the number of edges in the graph
  int getEdgeCount() {
    int count = 0;
    for (var neighbors in _adjacencyList.values) {
      count += neighbors.length ~/ 2; // Each edge is counted twice
    }
    return count;
  }

  // Generates random graph data based on parameters:
  // - totalNodes: Number of nodes to create
  // - maxEdgesPerNode: Maximum number of connections per node
  static Graph generateRandomGraph(int totalNodes, int maxEdgesPerNode) {
    final graph = Graph();

    final rand = Random();

    for (int i = 0; i < totalNodes; i++) {
      var nodeName = "N$i";
      graph.addNode(nodeName);

      for (int j = 0; j < min(maxEdgesPerNode, totalNodes - 1 - i); j++) {
        var otherNodeIndex = rand.nextInt(totalNodes - 1 - i) + i + 1;
        var otherNodeName = "N$otherNodeIndex";

        if (!graph.hasEdgeBetween(nodeName, otherNodeName)) {
          graph.connectNodes(nodeName, otherNodeName);
        }
      }
    }

    return graph;
  }

  @override
  String toString() {
    return '{\n${_adjacencyList.entries.map((e) => '${e.key}: [${e.value.join(', ')}]').join('\n')}\n}';
  }
}
