  void initState() {
    super.initState();
    qrReaderController = QrReaderController(
      androidCameraResolution: Size(640, 480),
      // Android specific options...
    );
    if (widget.initialScanResult != null) {
      setState(() {
        scanResultText = widget.initialScanResult;
      });
    }
  }

  Future<void> startScan(BuildContext context) async {
    try {
      await qrReaderController.initialize(); // Ensure camera access permissions are handled here
      setState(() {
        isScanning = true;
      });

      var result = await qrReaderController.getBarcodeResult();

      if (!mounted) return;

      setState(() {
        isScanning = false;
        scanResultText = result.code!;
      });

      Navigator.of(context).pop(result.code!);
    } catch (e) {
      print('Error scanning QR code: $e');
      setState(() {
        isScanning = false;
      });
    }
  }

