abstract class CandidateRepository<T extends Candidate> {
  Future<List<T>> fetchCandidates();
  void saveCandidate(T candidate);
  void updateCandidateScore(T candidate);
  void deleteCandidate(String id);
  T? findById(String id);
}

class InMemoryCandidateRepository implements CandidateRepository<Candidate> {
  final Map<String, Candidate> _candidates = {};

  @override
  Future<List<Candidate>> fetchCandidates() async {
    return List.of(_candidates.values.toList());
  }

  @override
  void saveCandidate(Candidate candidate) {
    _candidates[candidate.name] = candidate;
  }

  @override
  void updateCandidateScore(Candidate candidate) {
    if (_candidates.containsKey(candidate.name)) {
      _candidates[candidate.name] = candidate;
    }
  }

  @override
  void deleteCandidate(String id) {
    _candidates.remove(id);
  }

  @override
  Candidate? findById(String id) {
    return _candidates[id];
  }
