Void Function(Pointer<Void>) getAsmCode(String asm) {
  final ptr = calloc<Uint8>(asm.length + 1);
  final bytes = ptr.address;
  final code = Pointer.fromFunction<void>(bytes.cast<NativeFunction<void>>());
  return () => code.call();
}

