void main(List<String> args) async {
  if (args.isEmpty || args.length < 2) {
    print('Usage: dart run your_script_name.dart [file_path] [query]');
    exit(1);
  }

  final filePath = args[0];
  final query = args[1];

  try {
    // Read the file content
    final fileContent = await File(filePath).readAsString();

    // Parse JSON
    var data = jsonDecode(fileContent);

    List<Candidate> candidates = [];
    for (var item in data) {
      if (item is Map<String, dynamic>) {
        candidates.add(Candidate.fromJson(item));
      } else {
        throw Exception("Invalid data format");
      }
    }

    // Filter by query
    List<Candidate>? filteredCandidates = candidates.where((candidate) {
      return candidate.name.toLowerCase().contains(query.toLowerCase());
    }).toList();

    if (filteredCandidates.isNotEmpty) {
      print("Filtered Candidates:");
      for (var c in filteredCandidates) {
        print(c.toString());
      }
    } else {
      print("No matching candidates found.");
    }
  } catch (e) {
    print("Error processing file: $e");
  }
}
