import 'package:collection/collection.dart';

void main() {
  final input = [
    ['a', 'b'],
    ['b', 'c'],
    ['d', 'e'],
    ['e', 'f'],
    ['a', 'd']
  ];

  // Build adjacency list and in-degree count for topological sort
  Map<String, List<String>> graph = {};
  Map<String, int> inDegree = {};

  void addEdge(String from, String to) {
    if (!graph.containsKey(from)) {
      graph[from] = [];
    }
    graph[from]!.add(to);

    if (!inDegree.containsKey(to)) {
      inDegree[to] = 0;
    }
    inDegree[to] = (inDegree[to] ?? 0) + 1;
  }

  for (var edge in input) {
    addEdge(edge[0], edge[1]);
  }

  // Initialize queue with nodes of zero in-degree
  Queue<String> queue = Queue();
  Set<String> visited = Set();

  for (final key in inDegree.keys) {
    if (inDegree[key] == 0) {
      queue.add(key);
    }
  }

  while (queue.isNotEmpty) {
    var current = queue.removeFirst();
    visited.add(current);

    print('Visited node: $current');

    if (graph[current] != null) {
      for (var neighbor in graph[current]!) {
        inDegree[neighbor] = (inDegree[neighbor] ?? 0) - 1;

        if (inDegree[neighbor] == 0) {
          queue.add(neighbor);
        }
      }
    }
  }

  // Check for cycles
  if (visited.length < inDegree.length) {
    throw Exception("Cycle detected");
  }
}
