import 'package:vector_math/vector_math.dart';

class Candidate {
  final List<double> _points;

  Candidate(this._points);

  double calculateDistanceToLine() {
    // Calculate the distance from each point to a line defined by two points.
    // For this example, we'll use the first three points as the base for the line.
    if (_points.length < 3) throw Exception('Not enough points');

    final p0 = Vector2(_points[0], _points[1]);
    final p1 = Vector2(_points[2], _points[3]);

    double minDistance = double.infinity;
    int closestIndex = -1;

    for (int i = 4; i < _points.length; i += 2) {
      final pi = Vector2(_points[i], _points[i + 1]);
      final d = Point.distance(pi, Line(p0, p1));
      if (d < minDistance) {
        minDistance = d;
        closestIndex = i ~/ 2;
      }
    }

    return minDistance;
  }

  static List<double> getPointsFromAssembly(String assemblyString) {
    // Extract numerical values from the assembly string and parse them into doubles.
    final numbers = [];
    var currentNumber = '';
    bool isNegative = false;

    void processChar(char) {
      if (char == '-' && !currentNumber.isEmpty) {
        isNegative = true;
      } else if (char.isDigit()) {
        currentNumber += char;
      } else {
        if (currentNumber.isNotEmpty) {
          numbers.add(double.parse(currentNumber));
          currentNumber = '';
        }
      }
    }

    for (final c in assemblyString.split('')) {
      processChar(c);
    }

    // Handle any remaining number after loop ends
    if (currentNumber.isNotEmpty) {
      numbers.add(double.parse(currentNumber));
    }

    return numbers;
  }
}
