abstract class VoteStrategy {
  List<Candidate> computeVotes(List<Candidate> candidates);
}

class SimpleVoteStrategy implements VoteStrategy {
  @override
  List<Candidate> computeVotes(List<Candidate> candidates) {
    // Return the same list of candidates as votes
    return [...candidates];
  }
}

class WeightedVoteStrategy implements VoteStrategy {
  final Map<int, double> weights;

  const WeightedVoteStrategy({
    required this.weights,
  });

  @override
  List<Candidate> computeVotes(List<Candidate> candidates) {
    if (weights.length != candidates.length) {
      throw StateError('Weights and candidates must have the same length.');
    }

    List<double> totalWeight = List.filled(candidates.length, 0.0);

    for (int i = 0; i < candidates.length; i++) {
      totalWeight[i] = weights[candidates[i].id]!;
    }

    double sum = totalWeight.reduce((a, b) => a + b);

    if (sum <= 0) {
      throw StateError('Total weight must be positive.');
    }

    List<double> normalizedWeights =
        totalWeight.map((w) => w / sum).toList();

    List<double> cumulativeProbabilities = [];
    double probability = 0.0;

    for (final weight in normalizedWeights) {
      probability += weight;
      cumulativeProbabilities.add(probability);
    }

    List<Candidate> votes = [];

    for (int _ in candidates) {
      double randomValue = math.Random().nextDouble();
      int index = -1;

      for (int i = 0; i < cumulativeProbabilities.length; i++) {
        if (randomValue < cumulativeProbabilities[i]) {
          index = i;
          break;
        }
      }

      if (index == -1) {
        index = cumulativeProbabilities.length - 1;
      }

      votes.add(candidates[index]);
    }

    return votes;
  }
}
