class Election {
  List<Candidate> candidates = [];
  Map<int, int> votesPerCandidate = {};

  void addCandidate(Candidate candidate) {
    if (!candidates.contains(candidate)) {
      candidates.add(candidate);
      votesPerCandidate[candidate.id] = 0;
    }
  }

  void castVote(int candidateId) {
    if (votesPerCandidate.containsKey(candidateId)) {
      votesPerCandidate[candidateId]++;
    } else {
      // Handle invalid vote or error case
    }
  }

  void tallyVotes() {
    for (var candidate in candidates) {
      print('Candidate ID: ${candidate.id}, Name: ${candidate.name}, Votes: ${votesPerCandidate[candidate.id]}');
    }
  }
}
