List<Candidate> parseCandidates(String input) {
  if (input.trim().isEmpty) return [];

  List<Map<String, dynamic>> candidatesJson = [];
  try {
    // Split the input into lines and process each line as a JSON object
    for (String line in input.split('\n')) {
      if (line.trim() == '') continue; // Skip empty lines
      Map<String, dynamic>? parsedLine = jsonDecode(line);
      if (parsedLine != null && parsedLine.containsKey('name') && parsedLine.containsKey('votes')) {
        candidatesJson.add(parsedLine);
      } else {
        throw FormatException("Invalid format at line '$line'");
      }
    }
  } catch (e) {
    rethrow;
  }

  return candidatesJson.map((json) => Candidate.fromJson(json)).toList();
}
