// Helper function to generate a random number between min and max (inclusive)
int getRandomNumber(int min, int max) {
  return Random().nextInt(max - min + 1) + min;
}

// Main function to calculate the candidate's score based on their performance in different areas
double calculateCandidateScore() {
  // Define weights for each area
  final double englishWeight = 0.25; 
  final double mathWeight = 0.30;
  final double scienceWeight = 0.20;
  final double codingWeight = 0.25;

  // Generate scores for each subject/area using helper function
  final int englishScore = getRandomNumber(60, 95);
  final int mathScore = getRandomNumber(70, 98);
  final int scienceScore = getRandomNumber(65, 92);
  final int codingScore = getRandomNumber(75, 100);

  // Calculate weighted average score
  final double totalScore = (englishScore * englishWeight +
      mathScore * mathWeight +
      scienceScore * scienceWeight +
      codingScore * codingWeight);

  return totalScore;
}
