import 'package:collection/collection.dart';

class Candidate {
  final String name;
  final int score;

  const Candidate({required this.name, required this.score});

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is Candidate &&
          runtimeType == other.runtimeType &&
          name == other.name &&
          score == other.score;

  @override
  int get hashCode => Object.hash(name, score);

  static List<Candidate> parseCandidates(String input) {
    if (input.isEmpty || !input.contains('[')) return [];

    // Remove the surrounding brackets and split by commas
    final candidatesStr = input.replaceAll(RegExp(r'[\$$\[\]]'), '');
    final candidateList = candidatesStr.split(',').map((e) {
      final parts = e.trim().split(':');
      if (parts.length != 2) throw FormatException("Invalid candidate format");
      final name = parts[0].trim();
      final score = int.tryParse(parts[1].trim()) ?? 0;
      if (name.isEmpty || score < 0) throw FormatException("Invalid candidate data");
      return Candidate(name: name, score: score);
    }).toList();

    return candidateList;
  }

  @override
  String toString() => 'Candidate{name: $name, score: $score}';
}

void main() {
  try {
    final candidatesString = "[Alice:85, Bob:92, Charlie:78]";
    final parsedCandidates = Candidate.parseCandidates(candidatesString);
    for (var c in parsedCandidates) print(c);
  } catch (e) {
    print("Error parsing candidates: $e");
  }
}
