import 'package:vector_math/vector_math.dart';

class Candidate {
  final int id;
  late String name;

  // Initial parameters for the candidate's performance and attributes.
  double _basePerformance = 0.5; 
  double _efficiencyFactor = 1.0; 

  List<double> _attributes = [0.8, 0.7, 0.6]; // Attributes like communication, problem-solving, etc.

  // Initialize with ID and name.
  Candidate(this.id, this.name) {}

  // Get base performance value.
  double get basePerformance => _basePerformance;

  // Adjust efficiency factor based on team dynamics (e.g., collaboration).
  void adjustEfficiency(double adjustmentRate) {
    _efficiencyFactor *= (1 + adjustmentRate);
  }

  // Update performance considering current state of project phases.
  void updatePerformance(String phase) {
    if (phase == "design") {
      _basePerformance += 0.1 * (_attributes[0] - _attributes[2]);
    } else if (phase == "implementation") {
      _basePerformance -= 0.1 * (_attributes[2] - _attributes[1]);
    }
  }

  // Calculate overall contribution using weighted attributes.
  double calculateContribution() {
    return _basePerformance * _efficiencyFactor * (
        _attributes.reduce((a, b) => a > b ? a : b)
    );
  }

  // Method to assess how well the candidate fits into the team context.
  double fitInTeam(List<Candidate> teammates) {
    double compatibilityScore = 0.0;
    double totalAttributes = 0.0;

    for (final teammate in teammates) {
      // Compare each attribute with the average of teammates' attributes.
      for (int i=0; i < _attributes.length; i++) {
        double avgAttribute = teammates.map((t) => t._attributes[i]).average();
        compatibilityScore += (this._attributes[i] - avgAttribute).abs(); // Absolute difference as similarity measure
        totalAttributes += avgAttribute;
      }
    }

    // Normalize by summing all teammate averages across all attributes.
    if (totalAttributes != 0) {
      compatibilityScore /= totalAttributes;
    }

    return compatibilityScore;
  }
}
