import 'package:collection/collection.dart';

class Candidate {
  final String name;
  final int votes;

  const Candidate({required this.name, required this.votes});

  factory Candidate.fromJson(Map<String, dynamic> json) {
    return Candidate(
      name: json['name'] as String,
      votes: json['votes'] as int,
    );
  }
}

List<Candidate> parseCandidates(String input) {
  List<Map<String, dynamic>> parsed = [];

  // Split the input into lines and process each line
  for (var line in input.split('\n')) {
    if (line.trim().isEmpty || line.startsWith('#')) continue; // Skip empty or comment lines

    var parts = line.split(':');

    if (parts.length == 2) {
      try {
        var name = parts[0].trim();
        var votes = int.parse(parts[1].trim());

        parsed.add({'name': name, 'votes': votes});
      } catch (e) {
        print('Error parsing line: $line');
        print(e);
      }
    } else {
      print('Invalid format for line: $line');
    }
  }

  // Sort candidates by votes descending
  parsed.sort((a, b) => b['votes'].compareTo(a['votes']));

  return parsed.map(Candidate.fromJson).toList();
}
