  @override
  _CandidateState createState() => _CandidateState();
}

class _CandidateState extends State<Candidate> with TickerProviderStateMixin {
  late final AnimationController _controller = AnimationController(
    duration: const Duration(milliseconds: 1000),
    vsync: this,
  )..repeat(reverse: true);
  late final Animation<double> _animation = CurvedAnimation(
    parent: _controller,
    curve: Interval(0.2, 0.8, curve: Curves.easeOutQuad),
  );

  void initState() {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      Future.delayed(const Duration(seconds: 3), () {
        if (_controller.isAnimating) return;
        _controller.forward();
      });
    });
    super.initState();
  }

  @override
  Widget build(BuildContext context) {
    double width = MediaQuery.of(context).size.width / 4;

    return Container(
      padding: EdgeInsets.symmetric(horizontal: width * 0.5),
      child: Row(
        mainAxisAlignment: MainAxisAlignment.spaceBetween,
        children: [
          SizedBox.fromSize(
            size: Size(width, width + (width * _animation.value - width)),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.center,
              mainAxisSize: MainAxisSize.min,
              children: [
                Text('I', style: TextStyle(fontSize: 60, fontWeight: FontWeight.bold)),
                Transform.translate(
                  offset: Offset(-_animation.value * 70, -(_animation.value * 30)),
                  child: Text('I',
                      style:
                          TextStyle(fontSize: 120, color: Colors.blue.shade900.withOpacity(.6))),
                ),
              ],
            ),
          ),
          SizedBox.fromSize(
            size: Size(width, width + (width * _animation.value - width)),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.center,
