import 'package:collection/collection.dart';

final _primeCache = <int>[2, 3];

void main() {
  final primes = generatePrimes(10_000);

  print('First 100 prime numbers:');
  for (var i = 0; i < 100 && i < primes.length; ++i) {
    print('${primes[i]}');
  }
}

List<int> generatePrimes(int limit) {
  if (limit <= _primeCache.last) return List.from(_primeCache);

  var primes = List.of(_primeCache);
  var nextCandidate = _primeCache.last + 1;

  while (nextCandidate <= limit) {
    bool isPrime = true;

    // Check divisibility by known primes up to sqrt(nextCandidate)
    for (var p in primes) {
      if (p * p > nextCandidate) break;

      if (nextCandidate % p == 0) {
        isPrime = false;
        break;
      }
    }

    if (isPrime) {
      primes.add(nextCandidate);
    }

    nextCandidate += 2;
  }

  _primeCache.clear();
  _primeCache.addAll(primes);
  return primes;
}
