extension MapExtensions on Map<String, dynamic> {
  bool isMapEmpty() => isEmpty;

  T? getOrNull<T>(String key) {
    if (containsKey(key)) return this[key] as T?;
    return null;
  }

  void mergeWith(Map<String, dynamic>? other) {
    if (other != null) {
      for (var entry in other.entries) {
        putIfAbsent(entry.key, () => entry.value);
      }
    }
  }
}

