import 'dart:io';

void main() {
  // Read input from stdin and parse the assembly code.
  final lines = stdin.readLinesSync();

  if (lines.isEmpty) return;

  var currentLine = '';
  List<String> instructions = [];

  for (var line in lines) {
    if (line.trim().isEmpty) continue;

    currentLine += line + '\n';
  }

  // Split the assembled code into individual instructions by splitting on newlines.
  instructions = currentLine.split('\n');

  // Process each instruction to generate Dart source code.
  List<String> dartCodeParts = [];

  for (final instr in instructions) {
    String trimmedInstr = instr.trim();

    // Check if it's a comment or empty line, skip processing
    if (trimmedInstr.startsWith('//') || trimmedInstr.isEmpty) {
      continue;
    }

    // Parse the instruction type and operands
    int splitIndex = trimmedInstr.indexOf(' ');
    String opCode = trimmedInst.substring(0, splitIndex).trim();
    String operand = trimmedInstr.substring(splitIndex + 1).trim();

    // Handle different opcodes accordingly
    switch (opCode.toLowerCase()) {
      case 'add':
        dartCodeParts.add('_add($operand);');
        break;
      case 'sub':
        dartCodeParts.add('_subtract($operand);');
        break;
      case 'mov':
        dartCodeParts.add('_move($operand);');
        break;
      case 'cmp':
        dartCodeParts.add('_compare($operand);');
        break;
      case 'jmp':
        dartCodeParts.add('_jumpToLabel($operand);');
        break;
      case 'jz':
        dartCodeParts.add('_jumpIfZero($operand);');
        break;
      default:
        print("Unknown opcode: $opCode");
    }
  }

  // Combine all parts of generated Dart code and output them
  String generatedCode = '// Generated Dart Source Code\n'
      'void _add(String value) {\n'
      '  // Implementation of ADD operation goes here.\n'
      '}\n'
      'void _subtract(String value) {\n'
      '  // Implementation of SUBTRACT operation goes here.\n'
      '}\n'
      'void _move(String targetRegister, String value) {\n'
      '  // Implementation of MOVE operation goes here.\n'
      '}\n'
      'void _compare(String registerA, String registerB) {\n'
      '  // Implementation of CMP operation goes here.\n'
      '}\n'
      'void _jumpToLabel(String labelName) {\n'
      '  // Implementation of JMP operation goes here.\n'
      '}\n'
      'void _jumpIfZero(String labelName) {\n'
      '  // Implementation of JZ operation goes here.\n'
      '}\n';

  for (String part in dartCodeParts) {
    generatedCode += part + '\n';
  }

  stdout.write(generatedCode);
}
