  var yamlContent = await File('data.yaml').readAsString();

  // Parse the YAML into a Map (assuming it's structured correctly).
  var parsedYAML = loadYAML(yamlContent);

  if (!parsedYAML.containsKey("nodes")) {
    print("Error: The YAML does not contain 'nodes' key.");
    return;
  }

  var nodesMap = parsedYAML["nodes"] as Map<String, dynamic>;

  // Create a list of Node objects from the map entries.
  List<Node> nodesList = [];
  for (var entry in nodesMap.entries) {
    var nodeId = entry.key;
    var dependencies = entry.value as List<dynamic>;

    // Convert dependency names to strings and filter out any that are not valid identifiers.
    List<String> filteredDependencies = dependencies.cast<String>().where((dep) => dep.isNotEmpty).toList();

    nodesList.add(Node(id: nodeId, dependencies: filteredDependencies));
  }

  // Now you can work with the nodesList however needed.

  // Example usage:
  for (var node in nodesList) {
    print(node.toString());
  }
}
