// Helper function to demonstrate graph traversal
List<int> traverseGraph(List<List<int>> adjacencyList, int startNode, bool isUndirected = true) {
  List<int> visited = [];
  if (isUndirected) {
    _dfsTraversal(adjacencyList, startNode, visited, Set<int>());
  } else {
    _dfsTraversalDirected(adjacencyList, startNode, visited, Set<int>());
  }
  return visited;
}

void _dfsTraversal(List<List<int>> adj, int node, List<int> visited, Set<int> seen) {
  if (!seen.contains(node)) {
    seen.add(node);
    visited.add(node);
    for (int neighbor in adj[node]) {
      _dfsTraversal(adj, neighbor, visited, seen);
    }
  }
}

void _dfsTraversalDirected(List<List<int>> adj, int node, List<int> visited, Set<int> seen) {
  if (!seen.contains(node)) {
    seen.add(node);
    visited.add(node);
    for (int neighbor in adj[node]) {
      _dfsTraversalDirected(adj, neighbor, visited, seen);
    }
  }
}
