import 'package:graph/graph.dart';

class Candidate {
  final String name;
  final int votes;

  const Candidate({required this.name, required this.votes});

  factory Candidate.fromJson(Map<String, dynamic> json) {
    return Candidate(
      name: json['name'] as String,
      votes: json['votes'] as int,
    );
  }
}

Future<void> main() async {
  try {
    // Load graph from JSON file
    var graph = await Graph.fromFile('candidates.json');

    // Get the candidate with the highest number of votes
    var maxVotes = -1;
    var winner = '';
    for (var node in graph.nodes.values) {
      if (node.data is Candidate) {
        var candidate = node.data as Candidate;
        if (candidate.votes > maxVotes) {
          maxVotes = candidate.votes;
          winner = candidate.name;
        } else if (candidate.votes == maxVotes && candidate.name.compareTo(winner) < 0) {
          winner = candidate.name;
        }
      }
    }

    print('Winner is $winner with $maxVotes votes.');
  } catch (e) {
    print('Error: $e');
  }
}
