import 'package:vector_math/vector_math.dart';

class Candidate {
  final int id;
  final String name;

  Candidate({required this.id, required this.name});

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is Candidate &&
          runtimeType == other.runtimeType &&
          id == other.id &&
          name == other.name;

  @override
  int get hashCode => id.hashCode ^ name.hashCode;

  static List<Candidate> candidates = [
    Candidate(id: 1, name: "Alice"),
    Candidate(id: 2, name: "Bob"),
    Candidate(id: 3, name: "Charlie"),
    Candidate(id: 4, name: "David"),
    Candidate(id: 5, name: "Eve"),
    Candidate(id: 6, name: "Frank"),
    Candidate(id: 7, name: "Grace"),
    Candidate(id: 8, name: "Hannah"),
    Candidate(id: 9, name: "Ian"),
    Candidate(id: 10, name: "Jack")
  ];

  static void printCandidates() {
    for (Candidate candidate in candidates) {
      print("ID: ${candidate.id}, Name: ${candidate.name}");
    }
  }

  static void addNewCandidate(Candidate newCandidate) {
    if (!candidates.contains(newCandidate)) {
      candidates.add(newCandidate);
    } else {
      print("Candidate with ID ${newCandidate.id} already exists.");
    }
  }

  static void removeCandidate(int idToRemove) {
    final index = candidates.indexWhere((c) => c.id == idToRemove);
    if (index != -1) {
      candidates.removeAt(index);
    } else {
      print("Candidate with ID $idToRemove not found.");
    }
  }

  static void updateCandidateName(int idToUpdate, String newName) {
    final index = candidates.indexWhere((c) => c.id == idToUpdate);
    if (index != -1) {
      candidates[index] = Candidate(id: idToUpdate, name: newName);
    } else {
      print("Candidate with ID $idToUpdate not found.");
    }
  }

  // Helper function to find a candidate by ID
  static Candidate? findById(int id) {
    return candidates.firstWhereOrNull((c) => c.id == id);
  }

  static void displayAllCandidates() {
    print("Current Candidates:");
    for (final candidate in candidates) {
      print("${candidate.id}: ${candidate.name}");
    }
  }
}
