import 'package:ffi/ffi.dart';
import 'package:win32/win32.dart';

class CpuInfo {
  static final _kernel32 = DynamicLibrary.process();
  static late final GetLogicalProcessorInformationEx = _kernel32.lookupFunction(
    Pointer<NativeFunction<Void Function(Pointer, Int32, IntPtr)>>.fromAddress(0x1405a6c70),
    "GetLogicalProcessorInformationEx"
  );

  static List<Map<String, dynamic>> getLogicalProcessorInformation() {
    int bufferSize;
    var bufferPtr = calloc<Int32>(1);
    if (GetLogicalProcessorInformationEx(
        ProcessorRelationshipType.ProcessorGroup,
        pointerTo(bufferPtr),
        bufferPtr.cast<Int32>().addressOf.bufferSize) != true) {
      free(bufferPtr);
      return [];
    }

    final result = <Map<String, dynamic>>[];
    for (int i = 0; i < bufferPtr.value; i++) {
      var info = calloc<Int32>(1);
      var size = calloc<Int32>(1);
      size.value = 0;

      if (_kernel32.call(
          Pointer.fromFunction<void Function(Int32, Int32, Pointer<Int32>)>(
              (IntPtr, IntPtr, Pointer<Int32> _) => null), 
          info.addressOf(), 
          size.addressOf(),
          0)) {
        // ... processing ...
      }
      free(info);
      free(size);
    }
    free(bufferPtr);

    return result;
  }
}
