import 'package:assembly/assembly.dart';

class Candidate {
  final String name;
  final int votes;

  Candidate({required this.name, required this.votes});
}

List<Candidate> calculateElectionResults(Map<String, List<String>> electionData) {
  Map<String, int> voteCounts = {};

  // Initialize vote counts for each candidate
  for (var entry in electionData.entries) {
    var candidateName = entry.key;
    var votesForCandidate = entry.value.length; // Assuming each entry is a list of voter names

    if (!voteCounts.containsKey(candidateName)) {
      voteCounts[candidateName] = votesForCandidate;
    }
  }

  List<Candidate> candidates = [];
  for (var entry in voteCounts.entries) {
    candidates.add(Candidate(name: entry.key, votes: entry.value));
  }

  return candidates;
}
