import 'dart:math';

class Candidate {
  final int id;
  final String name;

  const Candidate({required this.id, required this.name});

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
          other is Candidate &&
              runtimeType == other.runtimeType &&
              id == other.id &&
              name == other.name;

  @override
  int get hashCode => id.hashCode ^ name.hashCode;
}

List<Candidate> generateCandidates(int count) {
  List<Candidate> candidates = [];
  for (int i = 0; i < count; i++) {
    candidates.add(Candidate(id: i + 1, name: "Candidate ${i + 1}"));
  }
  return candidates;
}

void main() {
  // Generate a list of candidate objects.
  List<Candidate> candidates = generateCandidates(10);

  // Print the generated candidates to verify they are created correctly.
  print("Generated Candidates:");
  for (var candidate in candidates) {
    print("${candidate.id}: ${candidate.name}");
  }

  // Demonstrate that equality checks work as expected.
  Candidate c1 = Candidate(id: 5, name: "Candidate 5");
  Candidate c2 = Candidate(id: 5, name: "Candidate 5");

  if (c1 == c2) {
    print("Equality check passed.");
  } else {
    print("Equality check failed.");
  }

  // Check for hash code consistency across equal instances.
  print("Hash codes match? ${c1.hashCode == c2.hashCode}");

  // Try comparing with an unequal instance.
  Candidate c3 = Candidate(id: 6, name: "Candidate 6");
  if (c1 != c3) {
    print("Inequality check passed.");
  } else {
    print("Inequality check failed.");
  }
}
