abstract class Repository<T> {
  Future<List<T>> fetch();
  Future<void> save(T item);
  Future<void> delete(String id);
}

class InMemoryRepository<T extends Object> implements Repository<T> {
  List<T> _items = [];
  late final Map<String, T> _itemMap;

  InMemoryRepository() : super(), _itemMap = {};

  @override
  Future<void> save(T item) async {
    if (_itemMap.containsKey(item.runtimeType.toString())) {
      await delete(item.hashCode.toString());
    }

    _itemMap[item.hashCode.toString()] = item;
    _items.add(item);

    // To ensure the list is updated with new items
    await Future.delayed(Duration(milliseconds: 10));
  }

  @override
  Future<void> delete(String id) async {
    int index = -1;
    for (int i = 0; i < _items.length; i++) {
      if (_items[i].hashCode.toString() == id) {
        index = i;
        break;
      }
    }

    if (index != -1) {
      _items.removeAt(index);
      _itemMap.remove(id);
    }
  }

  @override
  Future<List<T>> fetch() async {
    await Future.delayed(Duration(milliseconds: 50)); 
    return _items.toList(); 
  }
}
