import 'dart:io';

class Candidate {
  final String name;
  final int score;

  const Candidate({required this.name, required this.score});

  @override
  String toString() => '$name ($score)';
}

Future<void> main() async {
  // Read the assembly input (simulated for this example)
  final List<String> lines = File('input.asm').readAsLinesSync();

  // Parse and execute the assembly code
  final List<Candidate> candidates = parseAssembly(lines);

  // Sort by score descending, then by name ascending
  candidates.sort((a, b) {
    if (a.score != b.score) return b.score - a.score; // sort by higher scores first
    return a.name.compareTo(b.name); // alphabetical order for ties
  });

  print("Sorted Candidates:");
  for (final candidate in candidates) {
    print(candidate);
  }
}

List<Candidate> parseAssembly(List<String> lines) {
  final List<Candidate> result = [];

  for (var line in lines) {
    // Remove comments and trim whitespace
    var trimmedLine = line.trim();

    if (trimmedLine.startsWith(';')) continue; // Skip comments

    // Split into parts based on spaces
    final parts = trimmedLine.split_whitespace();

    if (parts.isEmpty) continue;

    // First part is the command
    final command = parts[0];

    switch (command.toLowerCase()) {
      case 'candidate':
        // Format: candidate <name> <score>
        if (parts.length >= 3 && int.tryParse(parts[1]) == null) {
          final name = parts[1];
          final score = int.parse(parts[2]);
          result.add(Candidate(name: name, score: score));
        }
        break;

      default:
        // Unknown command - ignore or handle as needed
        break;
    }
  }

  return result;
}
