import 'dart:math';

class Candidate {
  final String name;
  int points;

  Candidate(this.name, this.points);

  void addPoints(int amount) {
    points += amount;
  }

  @override
  String toString() => '$name ($points)';
}

void main() {
  var candidates = [
    Candidate('Alice', 0),
    Candidate('Bob', 0),
    Candidate('Charlie', 0)
  ];

  print("Initial Candidates:\n${candidates.map((c) => c.toString()).join('\n')}\n");

  for (int i = 1; i <= 5; i++) {
    print("\nRound $i:");
    List<Candidate> selectedCandidates = [];
    Random random = Random();

    // Select 2 candidates to receive points
    while (selectedCandidates.length < 2 && candidates.isNotEmpty) {
      int index = random.nextInt(candidates.length);
      if (!selectedCandidates.contains(candidates[index])) {
        selectedCandidates.add(candidates[index]);
      }
    }

    // Assign points based on the number of other selected candidates and their initial positions
    for (var candidate in selectedCandidates) {
      int numSelected = selectedCandidates.where((c) => c != candidate).length + 1;
      int pointValue = (numSelected * 4).toInt(); // Example calculation with some randomness
      candidate.addPoints(pointValue);
    }

    print('Selected Candidates:');
    for (var cand in selectedCandidates) {
      print('${cand.name} received ${pointValue}');
    }

    // Update the list of candidates excluding those who have already been selected
    candidates.removeWhere((candidate) => selectedCandidates.any((sCand) => sCand == candidate));
    print('');
  }

  print("\nFinal Results:\n${candidates.map((c) => c.toString()).join('\n')}");
}
```

This code simulates a simple selection process where each round selects two candidates at random from the current pool. The points awarded are calculated using a formula that considers how many candidates were selected (including themselves), resulting in more points for being chosen earlier or when fewer others are picked.

The simulation runs for five rounds, but it can be adjusted by changing the loop's upper limit. Each time a candidate is selected, they're removed from the available list so they can't be re-selected in subsequent rounds.

