import 'package:vector_math/vector_math.dart';

class Triangle {
  final List<Vector3> points;
  late double area;

  Triangle(List<Vector3> pts) : points = pts {
    // Calculate the area of the triangle using Heron's formula
    var a = _distance(points[0], points[1]);
    var b = _distance(points[1], points[2]);
    var c = _distance(points[2], points[0]);

    var s = (a + b + c) / 2.0;
    this.area = sqrt(s * (s - a) * (s - b) * (s - c));
  }

  static double _distance(Vector3 p1, Vector3 p2) {
    return pow(p1.distanceToSquared(p2), 0.5);
  }
}
