class ElectionViewModel with ChangeNotifier {
  List<Candidate> _candidates = [];
  late SharedPreferences prefs;

  ElectionViewModel() async {
    prefs = await SharedPreferences.getInstance();
    loadCandidates();
  }

  Future<void> loadCandidates() async {
    final candidatesJson = prefs.getString('candidates');
    if (candidatesJson != null) {
      _candidates = (json.decode(candidatesJson) as List)
          .map((item) => Candidate.fromJson(item))
          .toList();
    }
  }

  void addCandidate(String name) {
    setState(() {
      _candidates.add(Candidate(name: name, votes: 0));
    });
    saveCandidates();
  }

  void castVote(int index) {
    if (_candidates.isNotEmpty && index >= 0 && index < _candidates.length) {
      setState(() {
        _candidates[index].votes++;
      });
      saveCandidates();
    }
  }

  void removeCandidate(int index) {
    if (_candidates.isNotEmpty && index >= 0 && index < _candidates.length) {
      setState(() {
        _candidates.removeAt(index);
      });
      saveCandidates();
    }
  }

  void clearAllVotes() {
    setState(() {
      _candidates.forEach((candidate) { candidate.votes = 0; });
    });
    saveCandidates();
  }

  void sortCandidates(Function comparator) {
    setState(() {
      _candidates.sort(comparator);
    });
    saveCandidates();
  }

  void setCandidateName(int index, String newName) {
    if (_candidates.isNotEmpty && index >= 0 && index < _candidates.length) {
      setState(() {
        _candidates[index] = Candidate(
            name: newName,
            votes: _candidates[index].votes);
      });
      saveCandidates();
    }
  }

  void resetElection() {
    setState(() {
      _candidates.clear();
    });
    saveCandidates();
  }

  void saveCandidates() {
    final candidatesJson = json.encode(_candidates.map((c) => c.toJson()).toList());
    prefs.setString('candidates', candidatesJson);
  }

  Map<String, Object?> toJson() {
    return {'candidates': _candidates};
  }

  List<Candidate> get candidates => [..._candidates];
  bool get hasCandidates => _candidates.isNotEmpty;
}

