import 'package:vector_math/vector_math.dart';

class Candidate {
  // Vector representing the position of the candidate in a 2D space.
  final Vector2 _position;

  // Constructor to initialize the candidate's position.
  const Candidate({required this._position});

  // Method to calculate distance between two candidates.
  double getDistanceTo(Candidate other) {
    return _position.distance(other._position);
  }

  // Method to move the candidate towards another candidate by a certain step size.
  void moveTo(Candidate target, double stepSize) {
    if (target.getDistanceTo(this) > stepSize) {
      _position += (_position - target._position).normalized() * stepSize;
    }
  }

  // Method to check for collision with another candidate.
  bool isCollidingWith(Candidate other) {
    return getDistanceTo(other) < 0.5; // Assuming each candidate has a radius of 0.5 units.
  }

  // Factory method to create an array of candidates at random positions within a given area.
  static List<Candidate> generateCandidates(int count, double width, double height) {
    var candidates = [];
    for (var i = 0; i < count; i++) {
      var x = dart.Random().nextDouble() * width;
      var y = dart.Random().nextDouble() * height;
      candidates.add(Candidate(position: Vector2(x, y)));
    }
    return candidates;
  }

  @override
  String toString() => "Candidate(${_position.x}, ${_position.y})";
}
