import 'package:vector_math/vector_math.dart';

class Candidate {
  final int id;
  final String name;

  const Candidate({required this.id, required this.name});

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is Candidate &&
          runtimeType == other.runtimeType &&
          id == other.id &&
          name == other.name;

  @override
  int get hashCode => id.hashCode ^ name.hashCode;
}

abstract class VoteStrategy<T> {
  List<T> calculateWinners(List<Candidate> candidates);
}

class MajorityVote implements VoteStrategy<Candidate> {
  @override
  List<Candidate> calculateWinners(List<Candidate> candidates) {
    if (candidates.isEmpty) return [];

    // Count votes for each candidate using a map
    Map<int, int> voteCount = {};
    for (Candidate c in candidates) {
      voteCount[c.id] = (voteCount[c.id] ?? 0) + 1; 
    }

    // Find the maximum number of votes received by any candidate
    int maxVotes = voteCount.values.reduce(max); 

    // Filter out all candidates with that many votes to get the winners
    List<Candidate> winners = candidates.where((c) => voteCount[c.id] == maxVotes).toList();

    return winners;
  }

  static int max(int a, int b) => a > b ? a : b;
}
```

The code defines two classes:

1. `Candidate` - represents a candidate in an election, with an ID and a name.
2. `MajorityVote` - implements the majority voting strategy where we count how many votes each candidate gets, find the highest number of votes, then select all candidates who got that number of votes as the winners.

This implementation uses a simple counting approach and assumes there's at least one valid candidate when calculating the winner.

