import 'package:graph/graph.dart';

void main() {
  // Create a graph with some nodes and edges
  final graph = Graph<String>();

  const nodeA = 'A';
  const nodeB = 'B';
  const nodeC = 'C';
  const nodeD = 'D';
  const nodeE = 'E';
  const nodeF = 'F';

  graph.addNodes([nodeA, nodeB, nodeC, nodeD, nodeE, nodeF]);

  graph.addEdge(nodeA, nodeB);
  graph.addEdge(nodeA, nodeC);
  graph.addEdge(nodeB, nodeD);
  graph.addEdge(nodeC, nodeD);
  graph.addEdge(nodeD, nodeE);
  graph.addEdge(nodeE, nodeF);

  // Find the shortest path from A to F using BFS
  final path = findShortestPath(graph, nodeA, nodeF);

  print('The shortest path is $path');
}

List<String> findShortestPath(Graph<String> graph, String startNode, String endNode) {
  if (startNode == endNode) return [startNode];

  final visited = Set<String>();
  final queue = Queue<Map<String, List<String>>>(); 
  queue.add({'current': startNode, 'path': [startNode]});

  while (!queue.isEmpty) {
    final current = queue.removeFirst();

    for (final neighbor in graph.getNeighbors(current['current'])) {
      if (neighbor == endNode) {
        return [...current['path'], neighbor];
      }

      if (!visited.contains(neighbor)) {
        visited.add(neighbor);
        queue.add({
          'current': neighbor,
          'path': [...current['path'], neighbor]
        });
      }
    }
  }

  throw Exception("No path found");
}
