List<Candidate> parseCandidates(String input) {
  List<String> lines = input.split('\n');
  List<Candidate> candidates = [];

  for (int i = 0; i < lines.length; i++) {
    if (lines[i].trim().isNotEmpty && !candidates.contains(lines[i])) {
      String[] parts = lines[i].split(':');
      String name = parts[0].trim();
      int score = int.parse(parts[1].trim());
      candidates.add(Candidate(name, score));
    }
  }

  return candidates;
}

void main() {
  // Read from stdin
  String input = stdin.readSync().toString();

  List<Candidate> candidateList = parseCandidates(input);

  // Sort the list in descending order of scores
  candidateList.sort((a, b) => b.score.compareTo(a.score));

  // Print out the sorted list
  print('Sorted Candidates by Score:');
  for (Candidate c in candidateList) {
    print('${c.name}: ${c.score}');
  }
}
