import 'dart:io';
import 'dart:convert';

void main() async {
  final String input = await File('input.txt').readAsString();

  // Parse the assembly code
  List<String> lines = input.split('\n');

  // Initialize registers and memory
  Map<String, int> registers = {'a': 0, 'b': 0, 'c': 0, 'd': 0};
  List<int> mem = List.filled(65537, 0);

  void runOp(String op) {
    if (op.startsWith('add')) {
      var args = op.split(' ').skip(1).map(int.parse).toList();
      registers[args[0]] += args[1];
    } else if (op.startsWith('mul')) {
      var args = op.split(' ').skip(1).map(int.parse).toList();
      registers[args[0]] *= args[1];
    } else if (op.startsWith('mod')) {
      var args = op.split(' ').skip(1).map(int.parse).toList();
      registers[args[0]] %= args[1];
    } else if (op.startsWith('jnz')) {
      var args = op.split(' ').skip(1).map(int.parse).toList();
      if (registers[args[0]] != 0) {
        int i = args[1] + 2;
        while (i >= 0 && i < lines.length) {
          runOp(lines[i]);
          i++;
        }
      }
    } else if (op.startsWith('cpy')) {
      var args = op.split(' ').skip(1).map(int.parse).toList();
      registers[args[1]] = registers[args[0]];
    } else if (op.startsWith('inc')) {
      var args = op.split(' ').skip(1).map(int.parse).toList();
      registers[args[0]] += 1;
    } else if (op.startsWith('dec')) {
      var args = op.split(' ').skip(1).map(int.parse).toList();
      registers[args[0]] -= 1;
    } else if (op.startsWith('seti')) {
      var args = op.split(' ').skip(1).map(int.parse).toList();
      registers[args[1]] = args[0];
    } else if (op.startsWith('tgl')) {
      var args = op.split(' ').skip(1).map(int.parse).toList();
      int addr = args[0];
      if (addr + 3 < 65536) {
        int opCode = regToOp(mem[addr+3]);
        switch(opCode) {
          case 0:
            mem[addr+3] = 2; // add -> mul
            break;
          case 1:
            mem[addr+3] = 4; // mul -> mod
            break;
          default:
            break;
        }
      }
    } else if (op.startsWith('setr')) {
      var args = op.split(' ').skip(1).map(int.parse).toList();
      registers[args[1]] = registers[args[0]];
    } else if (op.startsWith('out')) {
      var args = op.split(' '.trim()).skip(1).map(int.parse).toList();
      print(registers[args[0]]);
    }
  }

  for (int i = 0; i < lines.length; ++i) {
    runOp(lines[i]);
  }
}
