import 'package:collection/collection.dart';

void main() {
  final input = List<int>.from(stdin.readLinesSync().map(int.parse));

  // Convert to a list of integers for easier manipulation
  var nums = input;

  int n = nums.length;
  if (n == 0) return;

  // Sort the array
  nums.sort();

  void swap(List<int> arr, int i, int j) {
    final temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
  }

  void heapify(List<int> arr, int n, int i) {
    int largest = i; 
    final left = 2 * i + 1;
    final right = 2 * i + 2;

    if (left < n && arr[left] > arr[largest]) {
      largest = left;
    }

    if (right < n && arr[right] > arr[largest]) {
      largest = right;
    }

    if (largest != i) {
      swap(arr, i, largest);
      heapify(arr, n, largest);
    }
  }

  // Build max-heap
  for (int i = n ~/ 2 - 1; i >= 0; i--) {
    heapify(nums, n, i);
  }

  // Extract elements from heap one by one
  for (int i = n - 1; i > 0; i--) {
    swap(nums, 0, i); 
    heapify(nums, i, 0);
  }

  print('Sorted Array:');
  for (var num in nums) {
    stdout.write('$num ');
  }
}
