// Helper function to get user input via stdin
List<String> readInput(String prompt) {
  print(prompt);
  final lines = stdin
    .readLinesSync()
    .where((line) => line.trim().isNotEmpty)
    .toList();
  return lines;
}

void main() async {
  try {
    final numbers = await readInput("Enter comma-separated numbers:");

    final parsedNumbers = numbers.map(double.tryParse).whereType<double>().toList();

    if (parsedNumbers.isEmpty) {
      throw Exception("No valid numbers provided.");
    }

    final result = parseAndProcess(parsedNumbers);

    print("\nResult:");
    print(result);
  } catch (e, stackTrace) {
    print(e.toString());
    print(stackTrace);
  }
}

dynamic parseAndProcess(List<double> data) {
  if (data.isNotEmpty) {
    final sum = data.reduce((a, b) => a + b);
    final average = sum / data.length;
    final min = data.reduce(min);
    final max = data.reduce(max);

    return {'sum': sum, 'average': average, 'min': min, 'max': max};
  } else {
    return "Empty dataset";
  }
}
