import 'package:vector_math/vector_math.dart';

class Candidate {
  final List<Face> faces;
  final int totalFaces;

  const Candidate({required this.faces, required this.totalFaces});

  double get score => _calculateScore();

  double _calculateScore() {
    var faceCount = 0.0;
    for (var i in faces) {
      if (!i.isClosed || !i.isValid) continue;
      faceCount += i.vertices.length.toDouble();
    }

    return ((faceCount / totalFaces) * 100).toDouble();
  }
}

abstract class Face {
  bool get isClosed;
  bool get isValid;
  int get verticesLength;
}

class TriangularFace implements Face {
  final List<Vector3> points;

  TriangularFace(this.points);

  @override
  bool get isClosed =>
      points[0] == points.last && points.length >= 3;

  @override
  bool get isValid => points.length == 3;

  @override
  int get verticesLength => points.length;
}
