import 'package:vector_math/vector_math.dart';

class Candidate {
  final double x;
  final double y;

  const Candidate({required this.x, required this.y});

  factory Candidate.fromPoint(Vector2 point) => Candidate(x: point.x, y: point.y);

  Vector2 toVector() => Vector2(x, y);
}

extension Points on List<Candidate> {
  // Returns the convex hull of a set of points in O(n log n) time.
  List<Vector2> convexHull() {
    if (length <= 3) return map((c) => c.toVector()).toList();

    final sorted = sort((a, b) => a.compareTo(b));

    var upper = <Candidate>[];
    for (var p in sorted) {
      while (upper.length >= 2 && cross(upper[1].toVector(), upper.last.toVector()) <= 0) {
        upper.removeLast();
      }
      upper.add(p);
    }

    var lower = <Candidate>[];
    for (var i = sorted.length - 1; i >= 0; i--) {
      while (lower.length >= 2 && cross(lower[1].toVector(), lower.last.toVector()) <= 0) {
        lower.removeLast();
      }
      lower.add(sorted[i]);
    }

    return [...upper..removeLast(), ...lower..removeLast()];
  }

  static int compareTo(Candidate a, Candidate b) =>
      a.x != b.x ? a.x.compareTo(b.x) : a.y.compareTo(b.y);

  static bool isCollinear(A,B,C) => cross(A.toVector(), B.toVector()) == cross(B.toVector(), C.toVector());

  static num cross(A,B) => A.x * B.y - A.y * B.x;
}
