String processAssemblyToDart(String assembly) {
  // Split the assembly into lines
  final lines = assembly.split('\n');

  // Initialize a list to hold the Dart code lines
  List<String> dartCodeLines = [];

  for (final line in lines) {
    if (line.trim().isEmpty) continue;

    // Split the line into parts based on spaces
    final parts = line.split(' ');

    // Extract the instruction type and operands
    String instructionType = parts[0].trim();
    List<String> operands = parts.sublist(1).map((part) => part.trim()).toList();

    // Handle different instructions
    switch (instructionType.toLowerCase()) {
      case '.data':
        handleDataDirective(dartCodeLines, operands);
        break;
      case '.text':
        handleTextDirective(dartCodeLines, operands);
        break;
      case 'mov':
        handleMovInstruction(dartCodeLines, operands);
        break;
      default:
        throw Exception("Unsupported instruction: $instructionType");
    }
  }

  return dartCodeLines.join('\n');
}

void handleDataDirective(List<String> dartCodeLines, List<String> operands) {
  // For .data directive, we can ignore it as it's not directly applicable in Dart
