  dartCodeLines.add('// Start of text section');
}

void handleMovInstruction(List<String> dartCodeLines, List<String> operands) {
  // Assuming syntax like "MOV destination, value"
  if (operands.length != 2) {
    throw Exception("Invalid MOV instruction format");
  }

  final dest = operands[0];
  final value = operands[1];

  // Convert hex values to integers if necessary
  int? intValue;
