List<String> tokenize(String line) {
  final List<String> tokens = [];
  var buffer = '';

  for (var i = 0; i < line.length; i++) {
    if (line[i] == ' ') {
      // Handle space as separator, but skip leading and trailing spaces
      if (buffer.isNotEmpty) {
        tokens.add(buffer);
        buffer = '';
      }
    } else if (line[i] == '\t') {
      // Skip tabs
    } else if (line[i] == ',') {
      // Comma is used as delimiter in the code, so split on commas as well
      if (buffer.isNotEmpty) {
        tokens.add(buffer);
        buffer = '';
      }
    } else if (line[i] == ';') {
      break;
    } else if (line[i].trim().isNotEmpty && !line[i].trim().contains('[')) {
      buffer += line[i];
    } 
  }

  return tokens;
}

