import 'package:collection/collection.dart';

extension OnList<T> on List<T> {
  void removeDuplicatesWithKey(Function(T) keyFunction, {bool isStable = true}) {
    if (this.isEmpty || this.length == 1) return;

    final Set<dynamic> seenKeys = {};
    final List<T> result = [];
    for (int i = 0; i < length; ++i) {
      final T item = this[i];
      final dynamic key = keyFunction(item);

      if (!seenKeys.contains(key)) {
        seenKeys.add(key);
        result.add(item);
      } else if (isStable && !result.any((e) => e.hashCode == item.hashCode)) {
        result.add(item); // Add duplicate with the same key but different object
      }
    }

    replaceAll(result);
  }
}
```

The `removeDuplicatesWithKey` extension method removes duplicates from a list based on a custom key function. It maintains stable order by preserving original elements when multiple items have the same key and are not identical objects.

