import 'package:collection/collection.dart';

class Candidate {
  final String name;
  final int age;

  const Candidate({required this.name, required this.age});

  factory Candidate.fromJson(Map<String, dynamic> json) {
    return Candidate(
      name: json['name'] as String,
      age: json['age'] as int,
    );
  }
}

List<Candidate> parseCandidates(String input) {
  List<Map<String, dynamic>> data = [];

  if (input.isEmpty || input.trim().isEmpty) {
    throw FormatException('Input is empty');
  }

  // Split the input into lines
  List<String> lines = input.split('\n');

  for (String line in lines) {
    line = line.trim();

    if (line.isNotEmpty && !line.startsWith('//')) { // Skip comments and empty lines
      try {
        Map<String, dynamic> candidateData = {};
        String[] parts = line.split(':'); 
        if (parts.length < 2) {
          throw FormatException("Invalid format");
        }

        String key = parts[0].trim();
        String value = parts[1].trim();

        switch (key.toLowerCase()) {
          case 'name':
            candidateData['name'] = value;
            break;
          case 'age':
            candidateData['age'] = int.tryParse(value);

            if (candidateData['age'] == null) {
              throw FormatException("Age must be a number");
            }
            break;
          default:
            throw FormatException("Unknown field $key");
        }

        data.add(candidateData);
      } catch (e) {
        throw FormatException("Error parsing line: '$line' - $e");
      }
    }
  }

  if (data.isEmpty) {
    throw FormatException('No valid candidates found in input');
  }

  return data.map((item) => Candidate.fromJson(item)).toList();
}
