import 'package:graph/graph.dart';

class Candidate {
  final String name;
  int votes;

  Candidate({required this.name, required this.votes});
}

List<Candidate> calculateWinners(List<String> candidates) {
  List<Candidate> result = [];

  // Initialize each candidate with zero votes
  for (String candidate in candidates) {
    result.add(Candidate(name: candidate, votes: 0));
  }

  // Read input from stdin and count votes
  final inputLines = stdin.readLinesSync();
  for (final line in inputLines) {
    if (line.trim().isEmpty) continue; // Skip empty lines

    final voteLine = line.split(' ').firstWhere((word) => word.isNotEmpty);

    final candidateName = voteLine;
    final voterCount = int.tryParse(voteLine.substring(1)) ?? 0;

    if (voterCount > 0) {
      final index = result.indexWhere((candidate) => candidate.name == candidateName);

      if (index != -1) {
        result[index].votes += voterCount;
      }
    }
  }

  return result;
}
