// Helper function to generate a random number within a given range
int getRandomNumber(int min, int max) {
  return Random().nextInt(max - min + 1) + min;
}

void main() {
  // Initialize the game state
  List<String> board = [' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' '];
  bool gameOver = false;

  void printBoard() {
    print(' ${board[0]} | ${board[1]} | ${board[2]} ');
    print('-----------');
    print(' ${board[3]} | ${board[4]} | ${board[5]} ');
    print('-----------');
    print(' ${board[6]} | ${board[7]} | ${board[8]} ');
  }

  void checkWin(String player) {
    final winPatterns = [
      [0, 1, 2], [3, 4, 5], [6, 7, 8],
      [0, 3, 6], [1, 4, 7], [2, 5, 8],
      [0, 4, 8], [2, 4, 6]
    ];

    for (var pattern in winPatterns) {
      if (board[pattern[0]] == player &&
          board[pattern[1]] == player &&
          board[pattern[2]] == player) {
        print("Player $player wins!");
        gameOver = true;
        break;
      }
    }
  }

  void playGame() {
    String currentPlayer = 'X';
    while (!gameOver) {
      printBoard();
      print("Player $currentPlayer's turn.");
      int position;

      do {
        print("Enter your move (1-9):");
        position = int.parse(stdin.readLineSync());
      } while (position < 1 || position > 9 || board[position - 1] != ' ');

      board[position - 1] = currentPlayer;

      checkWin(currentPlayer);
      if (gameOver) break;

      if (board.every((cell) => cell != ' ')) {
        print("It's a draw!");
        gameOver = true;
      } else {
        currentPlayer = currentPlayer == 'X' ? 'O' : 'X';
      }
    }

    print("\nFinal Board:");
    printBoard();
  }

  // Start the game
  playGame();
}
