Future<void> main() async {
  try {
    // Read the JSON data from stdin (simulating an API response)
    final jsonString = await stdin.readLines().join('\n');

    if (jsonString.trim().isEmpty) {
      print('No input received.');
      return;
    }

    final jsonData = jsonDecode(jsonString);

    if (!jsonData is List || jsonData.isEmpty) {
      print('Invalid or empty list of candidates.');
      return;
    }

    final candidates = <Candidate>[];
    for (final item in jsonData) {
      if (item is Map<String, dynamic>) {
        final candidate = Candidate.fromJson(item);
        candidates.add(candidate);
      } else {
        print('Skipping invalid entry: ${item.runtimeType}');
      }
    }

    if (candidates.isEmpty) {
      print("No valid candidates found.");
      return;
    }

    // Sort candidates by highest score and then alphabetically by name
    candidates.sort((a, b) {
      final scoreComparison = b.score.compareTo(a.score);
      if (scoreComparison != 0) return scoreComparison;
      return a.name.compareTo(b.name);
    });

    // Output the sorted result
    print('Candidates ranked by score:');
    for (var i = 0; i < candidates.length; i++) {
      print('${i + 1}. ${candidates[i].name} - Score: ${candidates[i].score}');
    }
  } catch (e) {
    print('Error processing input: $e');
  }
}
