extension ListX on List {
  int lastIndexOf<T>(T element) {
    for (int i = length - 1; i >= 0; --i) {
      if (element == this[i]) return i;
    }
    return -1;
  }

  void removeLastOccurrenceOf<T>(T value, {bool equals = false}) {
    final index = lastIndexOf(value);
    if (index != -1) removeAt(index);
  }
}

