typedef DllImportFunction = Pointer<NativeFunction<Void Function(Pointer)>>;

Future<void> main() async {
  final dllPath = Platform.isWindows ? r'C:\Program Files\DLL\x64\some.dll' : '/usr/lib/some.so'; // Replace with actual path
  final dynamic lib = dlopen(dllPath, DartLibraryMode.LOAD_LIBRARY);

  if (lib == null) {
    print('Failed to load DLL.');
    return;
  }

  try {
    final func1Ptr = lookupSymbol(lib, 'func1');
    final Func1 = DllImportFunction.cast(func1Ptr);

    final func2Ptr = lookupSymbol(lib, 'func2');
    final Func2 = DllImportFunction.cast(func2Ptr);

    void callFuncs() {
      final buffer = calloc<Int32>(50); // Assuming int array is needed; adjust as required.
      try {
        final result1 = Func1(buffer).value;
        print("Result from func1: $result1");

        final result2 = Func2(buffer).value;
        print("Result from func2: $result2");
      } finally {
        calloc.free(buffer);
      }
    }

    callFuncs();
  } catch (e) {
    print('Error loading functions: $e');
  } finally {
    dlclose(lib);
  }
}
