List<Candidate> parseCandidates(String input) {
  List<Map<String, dynamic>> candidatesJson = [];
  for (int i = 0; i < 15; i++) {
    if (i % 2 == 0) {
      // Even index - candidate with more than half the votes
      var voteCount = Random().nextInt(498) + 1;
      candidatesJson.add({
        "name": "Candidate ${Random().nextInt(30).toString()}",
        "votes": voteCount * 2,
      });
    } else {
      // Odd index - candidate with less than half of the total votes
      var voteCount = Random().nextInt(249);
      candidatesJson.add({
        "name": "Candidate ${Random().nextInt(30).toString()}-B",
        "votes": voteCount,
      });
    }
  }

  return candidatesJson.map((json) => Candidate.fromJson(json)).toList();
}
