}

void main(List<String> args) {
  if (args.isEmpty || args.length < 2) {
    print('Usage: dart run main.dart <candidate_id_1> [candidate_id_2 ...]');
    exit(0);
  }

  List<Candidate> candidates = [];
  for (int i = 0; i < args.length; i++) {
    try {
      int candidateId = int.parse(args[i]);
      candidates.add(Candidate(id: candidateId, name: 'Candidate ${candidateId}'));
    } catch (e) {
      print("Invalid candidate ID: '${args[i]}'");
    }
  }

  // Sort the list by ID
  candidates.sort((a, b) => a.id.compareTo(b.id));

  // Print each candidate in order
  for (final candidate in candidates) {
    print(candidate);
  }
}
