class Candidate {
  final String name;
  final int score;

  Candidate(this.name, this.score);

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
          other is Candidate &&
              runtimeType == other.runtimeType &&
              name == other.name &&
              score == other.score;

  @override
  int get hashCode => Object.hash(name, score);
}

extension TopCandidates on List<Candidate> {
  List<Candidate> top(int count) {
    if (count <= 0 || isEmpty) return [];

    // Sort candidates by score descending and then by name ascending
    var sorted = toSorted((a, b) {
      if (a.score != b.score) {
        return b.score.compareTo(a.score); 
      } else {
        return a.name.compareTo(b.name);
      }
    });

    // Take the first [count] elements or less if there are not enough
    return sorted.take(count).toList();
  }
}
