import 'package:collection/collection.dart';

class Candidate {
  final String name;
  final int score;

  const Candidate({required this.name, required this.score});

  factory Candidate.fromJson(Map<String, dynamic> json) {
    return Candidate(
      name: json['name'] as String,
      score: json['score'] as int,
    );
  }
}

List<Candidate> parseCandidates(String input) {
  List<Map<String, dynamic>> data = [];
  if (input.isEmpty) return [];

  try {
    // Split the input into lines and process each line
    for (final line in input.split('\n')) {
      if (line.trim().isEmpty) continue; // Skip empty lines
      final parts = line.split(':');
      if (parts.length < 2) continue; // Skip invalid lines
      final name = parts[0].trim();
      final scoreStr = parts[1].trim();

      if (!int.tryParse(scoreStr).isPresent) continue; // Skip invalid scores

      final score = int.parse(scoreStr);
      data.add({
        'name': name,
        'score': score,
      });
    }

    // Sort candidates by score descending, then by name ascending
    data.sort((a, b) {
      final scoreA = a['score'];
      final scoreB = b['score'];

      if (scoreA != scoreB) {
        return scoreB.compareTo(scoreA); // Descending order of score
      } else {
        return a['name'].compareTo(b['name']); // Ascending order of name
      }
    });

    return data.map((e) => Candidate.fromJson(e)).toList();
  } catch (e) {
    print('Error parsing candidate list: $e');
    return [];
  }
}
