class CandidateListScreen extends StatefulWidget {
  @override
  _CandidateListScreenState createState() => _CandidateListScreenState();
}

class _CandidateListScreenState extends State<CandidateListScreen> {
  List<Candidate> candidates = [];

  Future<void> loadCandidates() async {
    SharedPreferences prefs = await SharedPreferences.getInstance();
    var candidateJsonList = prefs.getString('candidates');

    if (candidateJsonList != null) {
      List<dynamic> parsedData = json.decode(candidateJsonList);
      List<Candidate> loadedCandidates = parsedData.map((json) => Candidate.fromJson(json)).toList();
      setState(() {
        candidates = loadedCandidates;
      });
    }
  }

  void addCandidate(String name, int age) {
    setState(() {
      candidates.add(Candidate(name: name, age: age));
    });
    saveCandidates(candidates);
  }

  void deleteCandidate(int index) {
    setState(() {
      candidates.removeAt(index);
    });
    saveCandidates(candidates);
  }

  void saveCandidates(List<Candidate> candidatesToSave) {
    SharedPreferences prefs = SharedPreferences.getInstance().then((prefs) {
      String encodedCandidates = json.encode(candidatesToSave.map((c) => c.toJson()).toList());
      prefs.setString('candidates', encodedCandidates);
    }).catchError((error) {
      print("Failed to save candidates: $error");
    });
  }

  @override
  void initState() {
    super.initState();
    loadCandidates();
  }

  @override
