class Candidate {
  final List<int> _graph;

  Candidate(this._graph);

  int get size => _graph.length ~/ 2;

  bool isPossible(int a, int b) {
    if (a >= size || b >= size || a < 0 || b < 0) return false;

    // Check for adjacency using bitwise operations
    return (_graph[a] & (1 << b)) != 0;
  }
}

void main() {
  const graph = [
    1 << 1 | 1 << 3,
    1 << 0 | 1 << 2,
    1 << 1 | 1 << 4,
    1 << 0 | 1 << 5,
    1 << 3 | 1 << 4,
    1 << 2 | 1 << 5,
  ];

  final candidate = Candidate(graph);

  print(candidate.isPossible(0, 1)); // true
  print(candidate.isPossible(0, 2)); // false
  print(candidate.isPossible(2, 4)); // true
}
