extension SortByRank on Iterable<Candidate> {
  List<Candidate> sortCandidates() {
    var sorted = toList();
    // Use a stable sort with the rank and then name for tie-breaking
    sorted.sort((a, b) {
      final diff = a.rank - b.rank;
      if (diff != 0) return diff;
      return a.name.compareTo(b.name);
    });
    return sorted;
  }

  List<Candidate> sortByName() {
    var sorted = toList();
    sorted.sort((a, b) => a.name.compareTo(b.name));
    return sorted;
  }
}

