List<Candidate>? parseCandidates(String input) {
  if (input.isEmpty || !input.contains('candidate')) return null;

  final lines = input.split('\n');
  List<Candidate> candidates = [];

  for (var line in lines) {
    if (!line.startsWith('candidate') && !line.startsWith('Candidate')) continue;

    var parts = line.trim().split(': ');
    if (parts.length < 2) continue;

    try {
      var name = parts[1].trim();
      var ageStr = parts[0].replaceAll('candidate', '').trim();

      // Extract the number from the age string using regex
      final match = RegExp(r'(\d+)').firstMatch(ageStr);
      if (match != null) {
        int age = int.parse(match.group(1)!);

        candidates.add(Candidate(name: name, age: age));
      }
    } catch (e) {
      print("Error parsing candidate data: $e");
    }
  }

  return candidates.isNotEmpty ? candidates : null;
}
