Future<void> main() async {
  final String? input = stdin.readLineSync();

  if (input == null) return;

  final List<String> parts = input.split(' ');
  final int n = int.parse(parts[0]);
  final int m = int.parse(parts[1]);

  // Check for valid inputs
  if (n <= 0 || m < 0 || m > n) {
    print("Invalid input");
    return;
  }

  final Set<int> selected = {};
  bool isPossible = false;

  void backtrack(int start, int count) {
    if (count == m) {
      isPossible = true;
      return;
    }

    for (int i = start; i <= n && !isPossible; i++) {
      selected.add(i);
      backtrack(i + 1, count + 1);
      if (!isPossible) selected.remove(i);
    }
  }

  backtrack(1, 0);

  if (isPossible) {
    print("${selected.toList()} are the $m numbers to choose from $n.");
  } else {
    print("No such combination exists.");
  }
