  int _counter = 0;
  late Timer? timer;

  void startTimer() {
    if (timer != null) {
      timer!.cancel();
      timer = null;
    }

    timer = Timer.periodic(const Duration(seconds: 1), (_) {
      setState(() {
        _counter++;
      });
    });
  }

  void stopTimer() {
    if (timer != null) {
      timer!.cancel();
      timer = null;
    }
  }

  @override
  void dispose() {
    super.dispose();
    stopTimer(); // Ensure the timer is stopped when widget is disposed.
