  static List<Vector3D> fromMatrix4(Matrix4 matrix) {
    return [
      Vector3D(matrix.getColumn(0).toList()[0], matrix.getColumn(1).toList()[0], matrix.getColumn(2).toList()[0]),
      Vector3D(matrix.getColumn(0).toList()[1], matrix.getColumn(1).toList()[1], matrix.getColumn(2).toList()[1]),
      Vector3D(matrix.getColumn(0).toList()[2], matrix.getColumn(1).toList()[2], matrix.getColumn(2).toList()[2])
    ];
  }

  @override
  String toString() =>
      "Vector3D(x=$x, y=$y, z=$z)";
}

class Transformations {
  static Matrix4 translate(Vector3D translation) {
    var m = new Matrix4.identity();
    m.translate(translation.x, translation.y, translation.z);
    return m;
  }

  static Matrix4 rotateX(double angleInRadians) {
    var m = new Matrix4.identity();
    m.rotateX(angleInRadians);
    return m;
  }
