import 'package:collection/collection.dart';

class Candidate {
  final List<int> data;
  final int windowSize;

  Candidate(this.data, this.windowSize);

  double calculateMean() {
    if (data.isEmpty || windowSize <= 0) return 0.0;
    var sum = 0.0;
    for (var i = 0; i < windowSize && i < data.length; i++) {
      sum += data[i];
    }
    return sum / windowSize;
  }

  List<double> slidingWindowAverages() {
    if (data.isEmpty || windowSize <= 0) return [];

    final result = <double>[];
    final n = data.length;
    final avg = calculateMean();

    // First pass - compute initial average
    var currentSum = 0.0;
    for (int i = 0; i < windowSize && i < n; i++) {
      currentSum += data[i];
    }
    result.add(currentSum / windowSize);

    // Subsequent passes with O(1) updates
    for (int i = windowSize; i < n; i++) {
      currentSum -= data[i - windowSize];
      currentSum += data[i];
      result.add(currentSum / windowSize);
    }

    return result;
  }
}
