import 'package:collection/collection.dart';

extension ArrayExt on List {
  void swap(int i, int j) {
    final temp = this[i];
    this[i] = this[j];
    this[j] = temp;
  }
}

class Solution {
  static List<int> quickSelect(List<int> nums, int k) {
    if (nums.isEmpty || k < 0 || k >= nums.length) return [];

    var left = [];
    var mid = [];
    var right = [];

    // Partition the array using a pivot element
    for (int num in nums) {
      if (num == nums[0]) {
        mid.add(num);
      } else if (num > nums[0]) {
        right.add(num);
      } else {
        left.add(num);
      }
    }

    if (left.length >= k) {
      return quickSelect(left, k); 
    } else if (mid.length + left.length >= k) {
      return [nums[0]];
    } else {
      return quickSelect(right, k - left.length - mid.length);
    }
  }
}
