class Candidate {
  void solve() async {
    final input = await File('input.txt').readAsString();
    final lines = input.split('\n');

    int totalValidPasswords = 0;
    for (var line in lines) {
      if (line.trim().isEmpty) continue;

      var parts = line.split(': ');
      var policyAndChar = parts[0].split(' ');
      var char = policyAndChar.last;
      var counts = policyAndChar.first.split('-');
      var minCount = int.parse(counts[0]);
      var maxCount = int.parse(counts[1]);

      var password = parts[1];
      var count = password.where((c) => c == char).length;

      if (count >= minCount && count <= maxCount) {
        totalValidPasswords++;
      }
    }

    print(totalValidPasswords);
  }
}
