  void startCounter() {
    timer = Timer.periodic(Duration(seconds: 1), (Timer t) {
      setState(() {
        _counter++;
      });
    });
  }

  void stopCounter() {
    if (timer.isActive) {
      timer.cancel();
    }
  }

  @override
  void initState() {
    super.initState();
    // Start the counter when widget is initialized
    startCounter();
  }

  @override
