extension Candidates on List<Candidate> {
  bool get isConvex =>
      convexHull(this).length == length ? true : false;

  Vector3 convexHullPoint(int index) {
    if (index >= length || index < 0) {
      return null;
    }
    int n = length;
    var i = index - 1 + n % n; // previous point
    var j = (index + 1) % n;   // next point

    var vectorI = Point2D(i);
    var vectorJ = Point2D(j);

    var crossProduct = (vectorJ.x - vectorI.x)*(this[j].y - this[i].y)
                      - (vectorJ.y - vectorI.y)*(this[j].x - this[i].x);

    return crossProduct > 0.0 ? Vector3(1, 0, 0) :
        crossProduct < 0.0 ? Vector3(-1, 0, 0) : Vector3(0, 0, 1); 
  } 

  static List<Point2D> convexHull(List<Candidate> candidates) {
    if (candidates.isEmpty) return [];

    var hull = <Point2D>[];
    for (var candidate in candidates) {
      hull.add(Point2D(candidate));
    }

    for (int i=0; i < hull.length; ++i){
      while(hull.length >= 3 && !isCounterClockwise(
          hull[hull.length-2],
          hull.last,
          hull[(i+1)%hull.length])){
        hull.removeLast();
      }
    }

    return hull;
  }

  static bool isCounterClockwise(Point2D a, Point2D b, Point2D c) {
    return (b.x - a.x)*(c.y - a.y) - (b.y -a.y)*(c.x - a.x) > 0;
  }
}
