import 'package:vector_math/vector_math.dart';

class Candidate {
  final int id;
  late double x, y;

  Candidate(this.id) : this.x = -1.0, this.y = -1.0;

  void reset() => (x, y) = (-1.0, -1.0);

  bool isAssigned(int targetId) =>
      (id == targetId) || (id != -1 && x > -1e-6 && y > -1e-6);
}

class Agent {
  static const double stepSize = 1.0 / 32.0; // Adjust as needed for speed and accuracy

  List<Candidate> candidates;
  int currentTargetId = -1;
  Vector2 position = Vector2.zero();
  double energyLevel = 1.0;

  Agent(List<Candidate> candidatesList) : candidates = candidatesList;

  void update(double dt) {
    if (currentTargetId < 0) return;

    var candidate = findCandidate(currentTargetId);
    if (!candidate.isAssigned(currentTargetId)) {
      moveToward(candidate.position, dt * stepSize);
    } else {
      currentTargetId = -1;
    }
  }

  void moveToward(Vector2 destination, double deltaMove) {
    final direction = destination - position;
    final distanceToGo = direction.length;
    if (distanceToGo <= deltaMove) {
      position += direction.normalize() * deltaMove;
      if (distanceToGo < 1e-5) {
        position = destination;
      }
    } else {
      position += direction.normalize() * deltaMove;
    }
  }

  Candidate? findCandidate(int targetId) {
    for (var c in candidates) {
      if (c.id == targetId) return c;
    }
    return null;
  }

  void assignTarget(int newTargetId) {
    currentTargetId = newTargetId;
  }

  void consumeEnergy(double amount) {
    energyLevel -= amount;
    if (energyLevel < 0) energyLevel = 0;
  }
}
