  final List<double> weights =
      skillWeights.values.map((v) => v).toList();
  final List<double> presence = [];
  for (final s in weights.asMap().keys.toList()) {
    presence.add(skillWeights[s]! / weights.firstWhere(
        (w) => w == skillWeights[s],
        orElse: () => 1.0)); // Normalize by max weight
  }

  return Vector3(presence[0], presence[1], presence[2]);
}

void main() {
  // Create sample candidates with varying skill sets
  final candidates = Candidate.generateSampleCandidates(10);

  print('Generated Candidates:');
  for (final c in candidates) {
    print(c.toString());
  }

  // Calculate and display skill similarities
  for (int i = 0; i < candidates.length - 1; i++) {
    for (int j = i + 1; j < candidates.length; j++) {
      final vecI = _getSkillVector(candidates[i].skills);
      final vecJ = _getSkillVector(candidates[j].skills);

      // Compute cosine similarity
      final dotProduct = vecI.dot(vecJ);
      final magnitudeI = vecI.magnitude;
      final magnitudeJ = vecJ.magnitude;

      final sim = dotProduct / (magnitudeI * magnitudeJ);

      print('\nSimilarity between Candidate ${candidates[i].id} '
          'and Candidate ${candidates[j].id}: $sim');
    }
  }
}
