  ['Alice', 'Bob', 'Charlie', 'David'].forEach((name) {
    graph.addNode(name);
  });

  // Define edges based on the assembly instructions
  graph.addEdge('Alice', 'Bob');
  graph.addEdge('Bob', 'Charlie');
  graph.addEdge('Charlie', 'David');

  // Calculate in-degrees to determine who has the most support
  Map<String, int> inDegrees = {};
  graph.nodes.forEach((node) {
    inDegrees[node] = graph.getInDegree(node);
  });

  // Find the candidate with the highest in-degree
  String winner = inDegrees.entries.reduce(
      (String maxCandidate, entry) =>
          inDegrees[maxCandidate]! > inDegrees[entry.key] ? maxCandidate : entry.key,
  );

  print('Winner is $winner with ${inDegrees[winner]} votes.');
}
