import 'dart:math';

class Candidate {
  final int id;
  final String name;

  Candidate(this.id, this.name);

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is Candidate &&
          runtimeType == other.runtimeType &&
          id == other.id &&
          name == other.name;

  @override
  int get hashCode => id.hashCode ^ name.hashCode;
}

class Election {
  List<Candidate> candidates = [];

  void addCandidate(Candidate candidate) {
    candidates.add(candidate);
  }

  List<int> countVotes(List<String> votes) {
    Map<int, int> voteCount = {};

    for (var vote in votes) {
      if (!vote.isEmpty && !vote.contains('[')) { // Ignore empty or invalid votes
        var parsedVote = parseVote(vote);
        if (parsedVote != null) {
          voteCount[parsedVote] ??= 0;
          voteCount[parsedVote]++;
        }
      }
    }

    return voteCount.entries.map((e) => e.value).toList(); // Return counts as list of integers
  }

  int? parseVote(String voteStr) {
    try {
      // Extract the part inside [ ] and remove spaces
      var match = RegExp(r'\[(\d+)\]').firstMatch(voteStr)?.group(1);
      if (match != null) {
        var index = int.tryParse(match)! - 1; // Convert to zero-based index
        if (index >= 0 && index < candidates.length) {
          return index;
        }
      }
    } catch (_) {}
    return null;
  }

  static const List<String> validVotePatterns = [
    r'^$$$\d+$$$', 
    r'$$\d+\s*$$', 
    r'$$\d+$',
    r'$$(?:$&|$&)$$'
  ];

  bool isValidVote(String voteStr) {
    for (final pattern in validVotePatterns) {
      if (RegExp(pattern).hasMatch(voteStr)) {
        return true;
      }
    }
    return false;
  }
}
