import 'package:vector_math/vector_math.dart' show Vector2, Matrix3;

class Triangle {
  final List<Vector2> _points = [];
  late int _index;

  Triangle(this._index) {}

  void addPoint(Vector2 point) {
    _points.add(point);
  }

  Vector2 get Point0 => _points[0];
  Vector2 get Point1 => _points[1];
  Vector2 get Point2 => _points[2];

  double area() {
    return (Point1.x - Point0.x)*(Point2.y - Point0.y) - (Point2.x - Point0.x)*(Point1.y - Point0.y).abs();
  }
}

class Tiling {
  final List<Triangle> triangles = [];

  static bool isClockwise(Triangle triangle) {
    // Calculate the cross product of vectors AB and AC to determine winding order.
    var ab = triangle.Point1 - triangle.Point0;
    var ac = triangle.Point2 - triangle.Point0;
    return ab.cross(ac) < 0.0; 
  }

  static void triangulate(List<Vector2> polygonPoints, Tiling tiling) {
    if (polygonPoints.length >= 3) {
      for (int i=0; i < polygonPoints.length-2; ++i) {
        // Form a triangle between three consecutive points in the list
        var p0 = polygonPoints[i];
        var p1 = polygonPoints[(i+1)%polygonPoints.length];
        var p2 = polygonPoints[(i+2)%polygonPoints.length];

        // Create new triangle with these points
        var triangle = Triangle(tiling.triangles.length); // Assign index as per current count

        triangle.addPoint(p0);
        triangle.addPoint(p1);
        triangle.addPoint(p2);

        tiling.triangles.add(triangle);
      }      
    }
  }

  void buildTrianglesFromPolygon(List<Vector2> polygonPoints) {
    triangulate(polygonPoints, this);

    // Sort triangles by their indices in clockwise orientation
    triangles.sort((a,b) => a.index.compareTo(b.index));
  }
}
