import 'dart:math';

int candidate(int n) {
  if (n <= 1) return 0;
  int count = 0;

  for (int i = 2; i <= sqrt(n); i++) {
    while (n % i == 0) {
      count++;
      n ~/= i;
    }
  }

  if (n > 1) count++;

  return count;
}
