// Helper function to calculate the convex hull of a set of points in 3D space.
List<v.Vector3> computeConvexHull(List<v.Vector3> points) {
  if (points.length <= 4) return points; // Degenerate case, no need for hull.

  var sortedPoints = [...points];
  sortedPoints.sort((a, b) => a.x.compareTo(b.x));

  // Find point with minimum z-coordinate.
  int minZIndex = 0;
  for (int i = 1; i < sortedPoints.length; ++i) {
    if (sortedPoints[i].z < sortedPoints[minZIndex].z) {
      minZIndex = i;
    }
  }

  var startPoint = sortedPoints.removeAt(minZIndex);
  var otherPoints = [startPoint];

  for (var p in sortedPoints) {
    otherPoints.add(p);
  }

  List<int> indices = [];
  double area = 0.0;

  for (int i = 0; i < otherPoints.length - 1; ++i) {
    Vector3 a = otherPoints[0];
    Vector3 b = otherPoints[i + 1];
    Vector3 c = otherPoints[(i + 2) % otherPoints.length];

    var triangleArea = Triangle(a, b, c).area();
    area += triangleArea * 2.0; // Multiply by 2 since we're calculating volume?

    // Calculate cross product to find normal vector
    var ab = b - a;
    var ac = c - a;
    var normal = ab.cross(ac);

    // Check which side of the plane this point is on.
    bool inside = false;
    for (int j = 0; j < otherPoints.length && !inside; ++j) {
      var testP = otherPoints[j];
      if (testP != a && testP != b && testP != c) {
        var cp = (b - a).cross(testP - a);
        var dotProduct = cp.dot(normal);
        if (dotProduct > 0) {
          inside = true;
        } else {
          break;
        }
      }
    }

    if (!inside) {
      indices.add(i + 1); // Indexes are adjusted based on original list
    }
  }

  return indices.map((idx) => otherPoints[idx]).toList();
}
