Here's the corrected version with proper scoring calculation:

```dart
import 'dart:io';

void main() {
  final List<String> lines = File('input.txt').readAsLinesSync();

  int total = 0;
  for (final line in lines) {
    if (line.isEmpty) continue;

    var parts = line.split(" ");
    String cardIdStr = parts[0].split(":")[0];
    int cardId = int.parse(cardIdStr.replaceAll("Card ", ""));

    var winningNumbersPart = parts[1];
    var winningNumbers = winningNumbersPart.split("|")[0].split(" ");
    Set<int> winningSet = winningNumbers.map((num) => int.parse(num)).toSet();

    int count = 0;
    for (int i = 2; i < parts.length; ++i) {
      int number = int.parse(parts[i]);
      if (winningSet.contains(number)) {
        count++;
      }
    }

    int score = 1 << (count - 1); // Equivalent to 2^(count-1)
    total += score;

