          if (parts.length != 2) throw FormatException('Invalid line format');

          final name = parts[0];
          final scoreStr = parts[1];

          try {
            final score = int.parse(scoreStr);
            return Candidate(name: name, score: score);
          } catch (e) {
            throw FormatException('Invalid score value $scoreStr for candidate $name');
          }
        })
        .toList();

    return {'file': f, 'candidates': candidates};
