import 'package:collection/collection.dart';

// Helper function to find the minimum number of operations to reach target from start using BFS
int minOperationsBfs(int start, int end) {
  if (start == end) return 0;

  // Queue for BFS traversal
  final queue = <List<int>>[];
  // Set to keep track of visited numbers
  final visited = <int>{};
  queue.add([start]);
  visited.add(start);

  while (queue.isNotEmpty) {
    final currentPath = queue.removeAt(0); // Dequeuing
    final lastNumber = currentPath.last;

    // Generate next possible moves by adding or subtracting a digit from lastNumber
    final digits = List.generate(lastNumber.toString().length, (index) => index).map((i) => lastNumber ~/ (10 * i) % 10).toList();

    for (final digit in digits) {
      var nextNumbers = [lastNumber + digit, lastNumber - digit];

      for (var nextNum in nextNumbers) {
        if (nextNum >= 0 && !visited.contains(nextNum)) {
          final newPath = [...currentPath, nextNum];

          if (nextNum == end) {
            return newPath.length; // Return path length as count of steps taken
          }

          queue.add(newPath);
          visited.add(nextNum);
        }
      }
    }
  }

  return -1; // If no path found
}

void main() {
  print(minOperationsBfs(52634987654, 1)); // Example call with large inputs
