List<Candidate> parseCandidates(String input) {
  List<Map<String, dynamic>> data = [];

  // Split the input by lines and process each line
  for (String line in input.split('\n')) {
    if (line.trim().isEmpty) continue; // Skip empty lines

    Map<String, dynamic> candidateData = {};

    // Split the line into key-value pairs
    for (String part in line.split('|')) {
      if (part.isEmpty) continue;

      // Split each pair by the first '=' to separate key and value
      var keyValue = part.split('=', maxSplit: 1);
      if (keyValue.length < 2) continue; // Invalid format

      String key = keyValue[0].trim();
      String value = keyValue[1].trim();

      switch (key.toLowerCase()) {
        case 'id':
          candidateData[key] = int.tryParse(value) ?? -1;
          break;
        case 'name':
          candidateData[key] = value;
          break;
        default:
          break;
      }
    }

    if (candidateData.containsKey('id') && candidateData.containsKey('name')) {
      data.add(candidateData);
    }
  }

  return data.map((json) => Candidate.fromJson(json)).toList();
}
