import 'package:vector_math/vector_math.dart' as vector;

class Candidate {
  final double _radius;
  late List<vector.Vector3> _points;

  Candidate(this._radius) : _points = [];

  void addPoint(double x, double y, double z) {
    _points.add(vector.Vector3(x, y, z));
  }

  bool checkPoints() {
    if (_points.length < 4) return false; // Need at least four points to form a plane

    // Compute the convex hull of the points and get its volume (tetrahedron)
    // For simplicity, we'll use a basic method with tetrahedrons formed by each point and three others
    var totalVolume = 0.0;

    for (int i = 0; i < _points.length; i++) {
      for (int j = i + 1; j < _points.length; j++) {
        for (int k = j + 1; k < _points.length; k++) {
          for (int l = k + 1; l < _points.length; l++) {
            var p1 = _points[i];
            var p2 = _points[j];
            var p3 = _points[k];
            var p4 = _points[l];

            var v1 = p2 - p1;
            var v2 = p3 - p1;
            var v3 = p4 - p1;

            var normal = cross(v1, v2);
            var dotProduct = dot(normal, v3);
            var absDot = dotProduct.abs();

            // Volume of tetrahedron is |dot product| / 6
            totalVolume += absDot / 6.0;
          }
        }
      }
    }

    // If any tetrahedron has volume exceeding radius cubed * pi/6, it's inside the sphere
    return totalVolume > (math.pi / 6.0) * pow(_radius, 3);
  }
}
