// Helper function to convert binary data into hex string representation.
String _binaryToHex(String inputBinary) { 
  List<int> bytes = new Uint8List.fromList(inputBinary.codeUnits); 
  StringBuffer sb = new StringBuffer(); 
  for (int i=0; i<bytes.length; i++) { 
    var b = bytes[i]; 
    String twoBytes = ""; 
    for (var j=7; j>=0; j--) { 
      twoBytes += (b >> j & 1 == 1 ? "1" : "0"); 
    }
    sb.write(twoBytes); 
  }
  return sb.toString(); 
} 

