    // Create a list of points for the graph.
    points = [
      Offset(5, height - 30),
      Offset(80, height - 160),
      Offset(140, height - 30),
      Offset(190, height - 170),
      Offset(220, height - 100),
      Offset(270, height - 50),
      Offset(300, height - 100),
      Offset(340, height - 170),
      Offset(390, height - 30),
      Offset(430, height - 160),
      Offset(480, height - 30)
    ];
  }

  Widget build(BuildContext context) {
    var size = MediaQuery.of(context).size;
    var width = size.width;
    var height = size.height;
    initPoints();

    return Scaffold(
      body: GestureDetector(
        onPanUpdate: (details) {
          setState(() {
            if (points.length > 1) {
              // Calculate the vector from previous point to current touch position.
              Vector2 prevPoint = points[points.length - 1];
              Vector2 currVector = details.localPosition - prevPoint;

              // Normalize the direction and calculate new point based on length.
              double magnitude = currVector.magnitude;
              Vector2 normalized = currVector / magnitude;

              // Add this as next point in our path.
              points.add(prevPoint + normalized * magnitude);
            }
          });
        },
        child: CustomPaint(
          painter: GraphPainter(points, angleRad), 
          size: Size(width, height),
        ),
      )
    );
  }
}

class GraphPainter extends CustomPainter {
  final List<Offset> points;
  final double angleRad;

  GraphPainter(this.points, this.angleRad);

  @override
  void paint(Canvas canvas, Size size) {
    Paint linePaint = Paint()
      ..color = Colors.blue
      ..strokeWidth = 2.0
      ..style = PaintingStyle.stroke
      ..isAntiAlias = true;

    Paint fillPaint = Paint()
      ..color = Colors.lightBlue.withOpacity(0.2)
      ..style = PaintingStyle.fill
      ..isAntiAlias = true;

    // Draw filled area under the curve with rotated coordinate system.
    Path path = Path();
    path.moveTo(points[0].dx, points[0].dy);

    for (int i = 1; i < points.length; ++i) {
      path.lineTo(points[i].dx, points[i].dy);
    }

    // Close the shape by connecting back to the first point after rotation adjustment
    path.close(); 

    canvas.save();
    canvas.translate(size.width/2, size.height/2); // Move origin to center

    // Apply rotation around the y-axis using the given angle
    canvas.rotate(angleRad);
    canvas.drawRect(Rect.fromLTWH(-size.width/2, -size.height/2, size.width, size.height), fillPaint);
    canvas.restore();

    // Draw the actual path on top without any rotation transformation
