class AssemblyGraph {
  final List<Candidate> candidates = [];
  late Map<int, List<int>> adjList; // graph representation - adjacency list
  late Set<String> edgesSet;        // set of edge strings to avoid duplicates

  void addCandidate(int id, String name) {
    if (!candidates.any((c) => c.id == id)) {
      candidates.add(Candidate(id: id, name: name));
    }
  }

  void connectCandidates(int fromId, int toId) {
    _ensureBothExist(fromId);
    _ensureBothExist(toId);

    if (fromId != toId) { // self-connections are not allowed
      var key1 = '${fromId}→${toId}';
      var key2 = '${toId}←${fromId}';

      if (!_isEdgeAlreadyPresent(key1) && !_isEdgeAlreadyPresent(key2)) {
        adjList[fromId] ??= [];
        adjList[toId] ??= [];

        adjList[fromId]!.add(toId);
        adjList[toId]!.add(fromId); // undirected graph

        edgesSet.add(key1);
        edgesSet.add(key2);
      }
    }
  }

  bool _isEdgeAlreadyPresent(String edgeKey) =>
      edgesSet.contains(edgeKey);

  void _ensureBothExist(int id) {
    if (!candidates.any((c) => c.id == id)) {
      throw Exception('Candidate with ID $id does not exist');
    }
  }

  Iterable<int> get connectedComponents {
    var visited = <int>{};
    for (var candidate in candidates) {
      if (!visited.contains(candidate.id)) {
        yield _dfs(candidate.id, visited);
      }
    }
  }

  int _dfs(int node, Set<int> visited) {
    visited.add(node);
    int componentSize = 1;

    for (final neighbor in adjList[node]!) {
      if (!visited.contains(neighbor)) {
        componentSize += _dfs(neighbor, visited);
      }
    }
    return componentSize;
  }

  void printAllConnectedComponents() {
    for (final size in connectedComponents) {
      print('Component size: $size');
    }
  }
}
```

This code defines a `Candidate` class and an `AssemblyGraph` class that represents the assembly as a graph. The graph is implemented using an adjacency list (`adjList`) and a set of edge keys to track connections.

The main features:

1. Adds candidates with their IDs and names.
2. Connects pairs of candidates (undirected graph).
3. Prevents duplicate edges between the same pair of nodes.
4. Finds all connected components in the graph through DFS traversal.
5. Prints out the sizes of each connected component.

