import 'package:vector_math/vector_math.dart';

class Candidate {
  final int id;
  final String name;

  const Candidate({required this.id, required this.name});

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
          (other is Candidate &&
              id == other.id &&
              name == other.name);

  @override
  int get hashCode => id.hashCode ^ name.hashCode;
}

abstract class BaseCandidateService {
  List<Candidate> getCandidates();
  void addCandidate(Candidate candidate);
  void updateCandidate(int id, Candidate updatedCandidate);
  void deleteCandidate(int id);
}

class InMemoryCandidateService implements BaseCandidateService {
  final Map<int, Candidate> _candidates = {};

  @override
  List<Candidate> getCandidates() => List.from(_candidates.values.toList());

  @override
  void addCandidate(Candidate candidate) {
    if (_candidates.containsKey(candidate.id)) {
      throw StateError('Candidate with ID ${candidate.id} already exists.');
    }
    _candidates[candidate.id] = candidate;
  }

  @override
  void updateCandidate(int id, Candidate updatedCandidate) {
    if (!_candidates.containsKey(id)) {
      throw StateError('Candidate with ID $id does not exist.');
    }
    _candidates[id] = updatedCandidate;
  }

  @override
  void deleteCandidate(int id) {
    if (!_candidates.containsKey(id)) {
      throw StateError('Candidate with ID $id does not exist.');
    }
    _candidates.remove(id);
  }
}
