void sortAndRankCandidates(List<Candidate> candidates) {
  List<Candidate> sorted = candidates..sort((a, b) => b.score.compareTo(a.score));

  Map<int, List<String>> rankMap = {};
  int currentRank = 1;

  // Assign ranks based on scores with ties
  for (int i = 0; i < sorted.length; i++) {
    if (i > 0 && sorted[i].score != sorted[i - 1].score) {
      currentRank = i + 1;
    }

    if (!rankMap.containsKey(currentRank)) {
      rankMap[currentRank] = [];
    }
    rankMap[currentRank]?.add(sorted[i].name);
  }

  print('\nCandidate Ranks by Score:');
  for (var entry in rankMap.entries) {
    print('$entry.key: ${entry.value.join(', ')}');
  }
}

void filterHighPerformers(List<Candidate> candidates) {
  double threshold = calculatePerformanceThreshold(candidates);

  List<Candidate> highPerformers = candidates.where((c) => c.score >= threshold).toList();

  print("\nHigh Performers ($threshold or higher):");
  for (var performer in highPerformers) {
    print(performer.name);
  }
}

double calculatePerformanceThreshold(List<Candidate> candidates) {
  var sortedScores = candidates.map((c) => c.score).sorted().reversed.toList();
  int topPercentileIndex = (sortedScores.length * 0.25).round(); // Top 25%

  return sortedScores[topPercentileIndex];
}
