// Parses the given graph string into a list of edges.
List<List<String>> parseGraph(List<String> lines) {
  List<List<String>> edges = [];

  for (String line in lines) {
    final parts = line.split(' -> ');
    if (parts.length < 2) continue; // Skip invalid lines

    final sourceNode = parts[0];
    final targetNodes = parts[1].split(',').map((s) => s.trim()).toList();

    for (final dest in targetNodes) {
      edges.add([sourceNode, dest]);
    }
  }
  return edges;
}

// Builds an adjacency map with sets of neighbors.
Map<String, Set<String>> buildAdjacencyList(List<List<String>> edges) {
  final adjMap = <String, Set<String>>{};

  for (var edge in edges) {
    final src = edge[0];
    final dst = edge[1];

    if (!adjMap.containsKey(src)) {
      adjMap[src] = <String>{};
    }
    adjMap[src]!.add(dst);
  }

  return adjMap;
}

