import 'dart:math';

class Candidate {
  final int id;
  final String name;

  Candidate({required this.id, required this.name});

  @override
  String toString() => 'Candidate($id - $name)';
}

// Helper function to generate a random candidate ID.
int _generateRandomId(int min, int max) =>
    Random().nextInt(max - min + 1) + min;

List<Candidate> createCandidates(int count) {
  List<Candidate> candidates = [];

  for (int i = 0; i < count; i++) {
    // Generate unique IDs using the helper function.
    int newId = _generateRandomId(1, 999);

    while (candidates.any((cand) => cand.id == newId)) {
      newId = _generateRandomId(1, 999); // Retry if duplicate found.
    }

    candidates.add(Candidate(id: newId, name: 'Candidate ${newId}'));
  }

  return candidates;
}
```

The `createCandidates` function generates [count] unique Candidate objects with randomized IDs between 1 and 999. Each candidate has an ID and a corresponding name in the format "Candidate X", where X is their randomly generated ID.

