  }

  // Shuffle the list of candidates using Fisher-Yates algorithm
  void shuffle(List<Candidate> list) {
    Random random = Random();
    for (int i = list.length - 1; i > 0; i--) {
      int j = random.nextInt(i + 1);
      var temp = list[i];
      list[i] = list[j];
      list[j] = temp;
    }
  }

  // Shuffle the list and print the shuffled result
  shuffle(candidates);
  print("\nShuffled Candidates:\n");
  for (var candidate in candidates) {
    print("${candidate.id}. ${candidate.name}");
  }
}
