import 'dart:io';
import 'dart:async';

void main() {
  final String input = stdin.readSync().trim();

  final List<String> lines = input.split('\n');
  final int n = int.parse(lines[0].split(' ')[1]);
  final List<int> xCoordinates = [];
  final List<int> yCoordinates = [];

  for (int i = 1; i <= n; ++i) {
    final String line = lines[i];
    final List<String> parts = line.split(' ');
    xCoordinates.add(int.parse(parts[0]));
    yCoordinates.add(int.parse(parts[1]));
  }

  print(calculateArea(xCoordinates, yCoordinates));
}

int calculateArea(List<int> x, List<int> y) {
  // Implement the shoelace formula to compute area of a polygon.
  int sum1 = 0;
  int sum2 = 0;

  for (int i = 0; i < x.length - 1; ++i) {
    sum1 += x[i] * y[i + 1];
    sum2 += x[i + 1] * y[i];
  }
  sum1 += x.last * y.first;
  sum2 += x.first * y.last;

  return abs(sum1 - sum2);
}
