// Fetch dummy data simulating fetching from an external source.
Future<List<Candidate>> _fetchCandidates() async {
  return [
    Candidate("Alice", 85),
    Candidate("Bob", 92),
    Candidate("Charlie", 76),
    Candidate("David", 90),
    Candidate("Eve", 88),
  ];
}

// Find the candidate with the highest score. If multiple have same max score,
// returns all of them as winners.
Future<String> _findWinner(List<Candidate> candidates) async {
  if (candidates.isEmpty) {
    throw Exception("No candidates found.");
  }

  int maxScore = candidates[0].score;
  String? winnerName;

  for (final candidate in candidates) {
    if (candidate.score > maxScore || (candidate.score == maxScore && winnerName == null)) {
      maxScore = candidate.score;
      winnerName = candidate.name;
    } else if (candidate.score == maxScore) {
      winnerName += ", ${candidate.name}";
    }
  }

  return winnerName!; // Assuming at least one candidate exists due to earlier check.
}
