import 'package:vector_math/vector_math.dart';

class Candidate {
  static double calculateDistance(List<Vector3> points) {
    if (points.length < 2) return 0.0;

    // Calculate the distance between consecutive points using Euclidean distance
    double totalDistance = 0.0;
    for (int i = 1; i < points.length; i++) {
      final Vector3 prevPoint = points[i - 1];
      final Vector3 currentPoint = points[i];
      final double dx = currentPoint.x - prevPoint.x;
      final double dy = currentPoint.y - prevPoint.y;
      final double dz = currentPoint.z - prevPoint.z;
      final double distance = sqrt(dx * dx + dy * dy + dz * dz);
      totalDistance += distance;
    }

    return totalDistance;
  }
}
