  final String name;

  Candidate({required this.id, required this.name});

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
          other is Candidate &&
              runtimeType == other.runtimeType &&
              id == other.id &&
              name == other.name;

  @override
  int get hashCode => id.hashCode ^ name.hashCode;
}

abstract class VoteStrategy {
  List<Candidate> calculateWinner(List<Map<String, dynamic>> votes);
}

class SimpleVoteStrategy implements VoteStrategy {
  @override
  List<Candidate> calculateWinner(List<Map<String, dynamic>> votes) {
    Map<int, int> candidateVotes = {};
    for (var vote in votes) {
      if (!vote.containsKey('candidateId')) continue;
      var cid = vote['candidateId'] as int;
      candidateVotes[cid] = (candidateVotes[cid] ?? 0) + 1;
    }

    // Sort candidates by vote count descending
    var sortedCandidates =
        candidateVotes.entries.toList()..sort((a, b) => b.value.compareTo(a.value));

    return sortedCandidates.map((e) => Candidate(id: e.key, name: 'Candidate ${e.key}')).toList();
  }
}

void main() {
  // Example usage:
  var votes = [
    {'candidateId': 1},
    {'candidateId': 2},
    {'candidateId': 3},
    {'candidateId': 2},
    {'candidateId': 4}
  ];

  var strategy = SimpleVoteStrategy();
  var winners = strategy.calculateWinner(votes);

  print(winners); // Output will be a list of Candidates with their IDs and names.
}
