            controller.forward(from: 0.0); // start from beginning when navigating to a new tab.
          } else{
            controller.reverse(); // reverse animation for same tab selection.
          }
          changePage(index);
        },
      ),
      body: AnimatedBuilder(
        animation: controller,
        builder: (_, __) {
          double percent = controller.value; 

          // Slide in page based on animation value.
          double translateX = -percent * (pages.length-1)*240.0; // assuming each page width is 240px.

          return Transform.translate(
              offset: Offset(translateX, 0),
              child: Stack(children: [Container(), ...pages]));
        },
      ),
    );
  }
