void main() async {
  // Read from stdin if running in a console environment
  final input = Platform.isWindows ? stdin : stdin; 

  try {
    final content = await input.readLines().join('\n');

    List<Map<String, dynamic>> parsedData = [];
    Map<String, dynamic> currentMap = {};

    for (var line in content.split('\n')) {
      if (line.trim().startsWith('}') && currentMap.isNotEmpty) {
        parsedData.add(currentMap);
        currentMap = {};
      } else if (line.trim().isNotEmpty) {
        var parts = line.split('=');
        if (parts.length == 2) {
          var key = parts[0].trim();
          var value = parts[1].trim();

          // Handle nested maps by checking for braces and commas
          bool isNested = false;
          int openBraces = 0;
          int closeBraces = 0;
          int lastCommaIndex = -1;

          for (int i = 0; i < value.length; i++) {
            if (value[i] == '{') openBraces++;
            else if (value[i] == '}') closeBraces++;
            else if (value[i] == ',' && openBraces > 0) lastCommaIndex = i;
          }

          if (openBraces != closeBraces || lastCommaIndex == -1) {
            // Not a nested map or not properly formatted, treat as string
            currentMap[key] = value;
          } else {
            // Extract the nested JSON part
            String? nestedJson;

            for (int i = 0; i <= lastCommaIndex + 1; i++) {
              if (i == 0) continue;

              if (value[i] == '{' && i > 0) {
                nestedJson = value.substring(i);
                break;
              }
            }

            if (nestedJson != null && nestedJson.trim().isNotEmpty) {
              try {
                Map<String, dynamic> nestedMap = jsonDecode(nestedJson);

                if (!currentMap.containsKey(key)) {
                  currentMap[key] = nestedMap;
                } else if (currentMap[key] is Map) {
                  Map<String, dynamic>? existingMap = currentMap[key] as Map?;

                  if (existingMap != null) {
                    // Merge nested maps
                    for (String innerKey in nestedMap.keys) {
                      existingMap[innerKey] = nestedMap[innerKey];
                    }

                    currentMap[key] = existingMap;
                  }
                } else {
                  // Overwrite with new map
                  currentMap[key] = nestedMap;
                }
              } catch (e) {
                print("Error parsing nested JSON: $e");
              }
            }
          }
        }
      }
    }

    if (currentMap.isNotEmpty) {
      parsedData.add(currentMap);
    }

