class Candidate {
  final String name;
  final int score;

  const Candidate({required this.name, required this.score});
}

List<Candidate> findTopCandidates(List<List<int>> votes) {
  if (votes.isEmpty || votes.first.isEmpty) return [];

  final numCandidates = votes[0].length;
  final scores = List.filled(numCandidates, 0);

  for (final vote in votes) {
    for (int i = 0; i < numCandidates; i++) {
      scores[i] += vote[i];
    }
  }

  var topCandidates = Map<int, List<String>>();

  // Count the number of candidates with same max score
  final maxScore = scores.reduce(max);
  final countMax = scores.where((s) => s == maxScore).length;

  // Get all indices that have max score
  final indicesWithMax = scores.indexWhere((s) => s == maxScore)
      .cast<int>()
      .toList(growable: false);  

  while (indicesWithMax.isNotEmpty && countMax > 1) {
    final currentIndices = indicesWithMax.toList();

    // For each index, get their remaining candidate list
    final nextIndices = <int>[];
    for (final idx in currentIndices) {
      final subScores = List.generate(
          numCandidates,
          (i) => i != idx ? scores[i] : -inf
      );

      final nextMax = subScores.reduce(max);
      final nextCount = subScores.where((s) => s == nextMax).length;

      final nextIndicesForThis =
          subScores.indexWhere((s) => s == nextMax).cast<int>().toList(growable: false);

      nextIndices.addAll(nextIndicesForThis.map((index) => index));
    }

    indicesWithMax.clear();
    for (final idx in nextIndices) {
      if (!indicesWithMax.contains(idx)) {
        indicesWithMax.add(idx);
      }
    } 

    countMax = indicesWithMax.length;
  }

  final result = [];
  for (final idx in indicesWithMax) {
    result.add(Candidate(name: "Candidate $idx", score: scores[idx]));
  }

  return result;
}
