  List<Candidate> candidates = [];
  for (int i = 0; i < n; ++i) {
    print("Enter candidate ${i + 1}'s name and score separated by space:");
    var input = await _readLine();
    var parts = input.split(' ');
    if (parts.length != 2 || !isNumeric(parts[1])) continue;
    candidates.add(Candidate(parts[0], int.parse(parts[1])));
  }

  // Sort candidates based on their scores in descending order
  candidates.sort((a, b) => b.score.compareTo(a.score));

  print("\nSorted Candidates:\n");
  for (var c in candidates) {
    print(c);
  }
}

// Helper functions
Future<int> _readInt() async {
  try {
    return int.parse(await stdin.readLineSync());
  } catch (_) {
    print('Invalid input. Please enter a valid integer.');
    return _readInt(); // Retry on error
  }
}

Future<String> _readLine() async {
  String? line = await stdin.readLineSync();
  if (line == null) throw Exception('No input received');
  return line.trim();
}

bool isNumeric(String s) {
  return RegExp(r'^-?\d+$').hasMatch(s); // Checks if string is an integer
