import 'dart:io';

void main() {
  // Read the input from stdin (pipe)
  final List<String> lines = stdin.readLinesSync();

  // Parse the assembly instructions into a list of tokens
  final List<List<String>> instructions = [];
  for (var line in lines) {
    if (line.trim().isNotEmpty) {
      final parts = line.split(' ');
      instructions.add(parts);
    }
  }

  // Initialize registers and memory
  int pc = 0;
  Map<String, int> regs = {'a': 1, 'b': 0};
  List<int> mem = List.filled(8, 0);

  void fetchDecodeExecute() {
    while (pc < instructions.length) {
      final opCode = instructions[pc][0];
      var operand = instructions[pc].length > 1 ? instructions[pc][1] : '';

      switch (opCode.toLowerCase()) {
        case 'inc':
          regs['a']++;
          pc++;
          break;

        case 'dec':
          regs['a']--;
          pc++;
          break;

        case 'jnz':
          if (regs.containsKey(operand)) {
            if (regs[operand] != 0) {
              pc += int.parse(instructions[pc + 1][1]);
            } else {
              pc++;
            }
          } else {
            pc += int.parse(operand);
          }
          break;

        case 'cpy':
          if (regs.containsKey(operand)) {
            mem[int.parse(instructions[pc + 1][1])] = regs[operand]!;
          } else {
            mem[int.parse(operand)] = int.tryParse(instructions[pc + 1][1]) ?? 0;
          }
          pc += 2;
          break;

        case 'incm':
          mem[int.parse(operand)]++;
          pc++;
          break;

        case 'decn':
          mem[int.parse(operand)]--;
          pc++;
          break;

        case 'out':
          stdout.write(regs[operand]! % 2 == 0 ? '0' : '1');
          pc++;
          break;

        default:
          throw Exception("Unknown instruction");
      }
    }
  }

  try {
    fetchDecodeExecute();
  } catch (e) {
    print(e.toString());
  }
}
