          name == other.name);

  @override
  int get hashCode => id.hashCode ^ name.hashCode;

  static List<Candidate> fromList(List<Map<String, dynamic>> data) {
    return data.map((item) => Candidate(item['id'], item['name'])).toList();
  }

  static Map<String, dynamic> toMap(Candidate candidate) {
