  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
          other is Candidate &&
              name == other.name &&
              yearOfBirth == other.yearOfBirth;

  @override
  int get hashCode => Object.hash(name, yearOfBirth);
}

List<Candidate> parseCandidates(String input) {
  if (input.isEmpty) return [];

  List<String> lines = input.split('\n');
  List<Candidate> candidates = [];

  for (String line in lines) {
    if (line.trim().isEmpty) continue;

    // Split the line into parts using tabs or spaces as separators
    var splitLine = line.split(RegExp(r'\s+'));

    if (splitLine.length < 2) continue; // Skip invalid lines

    String? lastName = splitLine[0];
    int? birthYear = int.tryParse(splitLine[1]);

    if (lastName != null && birthYear != null) {
      try {
        candidates.add(Candidate(
            name: lastName,
            yearOfBirth: birthYear));
      } catch (_) {}
    }
  }

  return candidates;
}
