class Candidate {
  static void main() {
    // Define the vertices of a cube with side length 1, centered at origin.
    final List<vector.Vector3> vertices = [
      vector.Vector3(-0.5, -0.5, -0.5),
      vector.Vector3(0.5, -0.5, -0.5),
      vector.Vector3(0.5, 0.5, -0.5),
      vector.Vector3(-0.5, 0.5, -0.5),
      vector.Vector3(-0.5, -0.5, 0.5),
      vector.Vector3(0.5, -0.5, 0.5),
      vector.Vector3(0.5, 0.5, 0.5),
      vector.Vector3(-0.5, 0.5, 0.5),
    ];

    // Compute all edges (line segments between adjacent vertices)
    final List<List<int>> edges = <List<int>>[];

    for (int i = 0; i < vertices.length; i++) {
      if ((i % 4) == 0 || (i % 2) == 0) { // Ensure we don't duplicate edges
        int j;

        switch (i % 8) {
          case 0:
            j = 1;
            break;
          case 1:
            j = 5;
            break;
          case 2:
            j = 6;
            break;
          case 3:
            j = 7;
            break;
          case 4:
            j = 5;
            break;
          case 5:
            j = 1;
            break;
          case 6:
            j = 2;
            break;
          default:
            j = 3;
            break;
        }

        edges.add([i, j]);
      }
    }

    print('Edges count: ${edges.length}');
  }
}
