class Candidate {
  final String name;
  int score;

  const Candidate(this.name, this.score);

  @override
  String toString() => '$name ($score)';
}

List<Candidate> calculateScores(String filePath) {
  List<String> lines = File(filePath).readAsLinesSync();

  if (lines.isEmpty) return [];

  List<Candidate> candidates = [];

  for (int i = 1; i < lines.length; i++) {
    String line = lines[i];
    if (line.trim().isEmpty) continue;

    var parts = line.split(':');
    if (parts.length != 2) continue;

    String name = parts[0].trim();
    int? score = int.tryParse(parts[1].trim());

    if (score != null && score >= 0) {
      candidates.add(Candidate(name, score));
    }
  }

  candidates.sort((a, b) => a.score.compareTo(b.score));
  candidates.reversed.toList();

  return candidates;
}
