int solvePartOne(List<int> data) {
  int countIncreases = 0;
  for (int i = 1; i < data.length; i++) {
    if (data[i] > data[i - 1]) countIncreases++;
  }
  return countIncreases;
}

int solvePartTwo(List<int> data) {
  int windowSum = data[0] + data[1] + data[2];
  int countIncreases = 0;

  for (int i = 3; i < data.length; i++) {
    windowSum += data[i] - data[i - 3];
    if (windowSum > data[i - 1] + data[i - 2] + data[i - 3]) countIncreases++;
  }

  return countIncreases;
}
