Future<void> main() async {
  // Read input from stdin as a stream of lines
  var input = stdin.transform(utf8.decoder).transform(const LineSplitter());

  List<Candidate> candidates = [];

  await for (var line in input) {
    if (line.trim().isEmpty) continue;

    try {
      var parts = line.split(' ');
      var name = parts[0];
      var ageStr = parts[1];

      if (!int.tryParse(ageStr)?.isValid == true) {
        print("Invalid age value. Expected an integer.");
        exit(1);
      }

      candidates.add(Candidate(name: name, age: int.parse(ageStr)));
    } catch (e) {
      print("Error parsing input: $e");
      exit(1);
    }
  }

  candidates.sort((a, b) {
    return a.name.compareTo(b.name);
  });

  for (var candidate in candidates) {
    print(candidate);
  }
}
