Future<String> fetchWebPageContent(String url) async {
  try {
    final response = await http.get(Uri.parse(url));

    if (response.statusCode == 200) {
      return response.body; // Return the content of the page
    } else {
      throw Exception('Failed to load page');
    }
  } catch (e) {
    print("Error fetching web page content: $e");
    rethrow;
  }
}

String extractTextFromHTML(String htmlContent) {
  int startTagIndex = htmlContent.indexOf('<body>');

  if (startTagIndex != -1) {
    int endTagIndex = htmlContent.indexOf('</body>', startTagIndex);

    if (endTagIndex != -1) {
      String bodyContent = htmlContent.substring(startTagIndex + '<body>'.length, endTagIndex);

      // Remove any remaining HTML tags using a simple regex
      String cleanedContent = bodyContent.replaceAll(RegExp(r'<[^>]+>'), '');
      return cleanedContent.trim();
    }
  }

  return htmlContent; // If no <body> tag found, return the original content
}
