  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is Candidate &&
          runtimeType == other.runtimeType &&
          name == other.name &&
          score == other.score;

  @override
  int get hashCode => Object.hash(name, score);
}

List<Candidate> calculateCandidates(List<Map<String, dynamic>> data) {
  List<Candidate> candidates = [];

  for (final item in data) {
    if (!item.containsKey('name') || !item.containsKey('score')) continue;
    final name = item['name'] as String?;
    final score = item['score'] as num?;

    if (name != null && score != null) {
      candidates.add(Candidate(
        name: name,
        score: score.toInt(),
      ));
    }
  }

  return candidates;
}
