  Map<String, double> averageScorePerName() {
    final result = <String, double>{};

    forEach((candidate) {
      final currentAvg = result[candidate.name] ?? 0.0;
      final newAvg =
          (currentAvg * result.length + candidate.score) / (result.length + 1);

      result[candidate.name] = newAvg;
    });

    return result;
  }

  // Returns the list of names with scores greater than or equal to a given value.
  List<String> aboveOrEqual(int threshold) {
    return where((c) => c.score >= threshold).map((e) => e.name).toList();
  }

  // Returns the sum of all scores in the list.
  int totalScoresSum() {
    var sum = 0;
    for (var i = 0; i < length; ++i) {
      sum += this[i].score;
    }
    return sum;
  }
