String candidate(String input) {
  // Parse the assembly-like string into tokens.
  List<String> lines = input.split('\n');

  Map<int, int> registerValues = {};

  for (var line in lines) {
    if (line.startsWith('mov')) {
      var parts = line.split(' ');
      int regIndex = int.parse(parts[1][1]);
      int value = int.parse(parts[3]);
      registerValues[regIndex] = value;
    } else if (line.startsWith('add')) {
      var parts = line.split(' ');
      int reg1 = int.parse(parts[1][1]);
      int reg2 = int.parse(parts[3][1]);

      // Perform addition and store result in first register
      int newValue = registerValues[reg1]! + registerValues[reg2]!;
      registerValues[reg1] = newValue;
    }
  }

  // Output the final values of all registers that were used
  StringBuffer output = StringBuffer();
  output.write("Final register values:\n");

  for (var entry in registerValues.entries) {
    output.write("R${entry.key}: ${entry.value}\n");
  }

  return output.toString();
}
