  void applyFolding() {
    if (length < 2) return;

    for (var k = 0; k < length * 2; k++) {
      var x = k % length;
      var y = (k + 1) % length;

      // Calculate the midpoint of the two points
      var midPoint = (this[x] + this[y]) / 2.0;

      // Find a point that is not adjacent to both
      var z = findNonAdjacent(x, y);

      if (z == null) continue;

      // Create new points along the fold line
      var dir = normalize(midPoint - this[z]);
      var offset = dir * 10.0;

      var pNew1 = midPoint - offset;
      var pNew2 = midPoint + offset;

      // Insert new points into the list
      insertAll(z + 1, [pNew1, pNew2]);

      // Remove original points and replace with new ones
      removeRange(x, y + 1); 
    }
  }

  int? findNonAdjacent(int x, int y) {
    for (var z in indicesWhereNotInSet({x, y})) {
      if (z != x && z != y &&
          !isAdjacentTo(x, z)) {
        return z;
      }
    }
    return null;
  }

  bool isAdjacentTo(int x, int z) {
    return (z == x-1 || z == x+1) ||
           (y == x-1 || y == x+1);
  }

  Iterable<int> indicesWhereNotInSet(Set<int> set) sync* {
    for (var i in indices) {
      if (!set.contains(i)) yield i;
    }
  }
