    graph.addVertex(0, Vector3.zero());
    graph.addVertex(1, Vector3(2.0, 0.0, 0.0));
    graph.addVertex(2, Vector3(4.0, 0.0, 0.0));

    graph.addEdge(0, 1);
    graph.addEdge(1, 2);

    // Traverse the graph using DFS
    print("DFS traversal:");
    dfs(graph, 0, Set<int>());

    // Traverse the graph using BFS
    print("\nBFS traversal:");
    bfs(graph, 0);
  }
}

class Graph {
  List<Vector3> vertices;
  List<List<int>> edges;

  Graph() : 
    vertices = [],
    edges = [];

  addVertex(int id, Vector3 position) {
    vertices.add(position);
    edges.add([]);
  }

  addEdge(int fromId, int toId) {
    edges[fromId].add(toId);
    edges[toId].add(fromId); // Undirected graph
  }
}

void dfs(Graph graph, int startId, Set<int> visited) {
  if (visited.contains(startId)) return;

  visited.add(startId);
  print('Visited vertex ${startId} at position ${graph.vertices[startId]}');

  for (var neighbor in graph.edges[startId]) {
    dfs(graph, neighbor, visited);
  }
}

void bfs(Graph graph, int startId) {
  Queue<int> queue = Queue<int>();
  Set<int> visited = Set<int>();

  queue.add(startId);
  visited.add(startId);

  while (!queue.isEmpty) {
    int current = queue.removeFirst();
    print('Visited vertex $current at position ${graph.vertices[current]}');

    for (int neighbor in graph.edges[current]) {
      if (!visited.contains(neighbor)) {
        visited.add(neighbor);
        queue.add(neighbor);
      }
    }
  }
}
