// Helper function to compute cross product of two vectors
Vector3 cross(Vector3 v1, Vector3 v2) {
  return Vector3(
    v1.y * v2.z - v1.z * v2.y,
    v1.z * v2.x - v1.x * v2.z,
    v1.x * v2.y - v1.y * v2.x,
  );
}

// Helper function to compute the length of a vector
double length(Vector3 v) {
  return sqrt(v.x * v.x + v.y * v.y + v.z * v.z);
}

// Helper function for point subtraction
Point3 operator -(Point3 a, Point3 b) {
  return Point3(a.x - b.x, a.y - b.y, a.z - b.z);
}

// Helper function for scalar multiplication
Vector3 operator *(double s, Vector3 v) {
  return Vector3(s * v.x, s * v.y, s * v.z);
}
