import 'package:vector_math/vector_math.dart';

class Candidate {
  final Vector3 position;
  final double mass;

  Candidate({required this.position, required this.mass});

  // Calculate the gravitational force between two candidates
  static Vector3 calculateGravitationalForce(Candidate a, Candidate b) {
    const G = 6.6743015e-11; // Grav constant (m^3 kg^-1 s^-2)

    var r = b.position - a.position;
    var distanceSquared = r.lengthSquared();
    if (distanceSquared == 0) return Vector3.zero(); // Avoid division by zero

    var distance = math.sqrt(distanceSquared);
    var forceMagnitude = G * a.mass * b.mass / distanceSquared;

    return r.normalize() * forceMagnitude;
  }
}
