        stdout.write("Enter score amount: ");
        var scoreInput = await stdin.readLineSync();
        if (!scoreInput!.isNotEmpty && RegExp(r'^-?\d+\.?\d*$', multiLine: true).hasMatch(scoreInput)) {
          double scoreToAdd = double.tryParse(scoreInput)!;
          if (scoreToAdd.isFinite) {
            candidates[selectedIndex].addScore(scoreToAdd.toInt());
            print("Added $scoreToAdd score to ${candidates[selectedIndex].name}");
          } else {
            print("Invalid score value.");
          }
        } else {
          print("Invalid input. Please enter a numeric value.");
        }
        break;

      case "2":
        print("\nCurrent scores:\n");
        for (var c in candidates) {
          print("${c.name}: ${c.score}");
        }
        break;

      case "3":
        print("Exiting program...");
        return;

      default:
        print("Invalid option. Please choose again.");
    }
  }
}
