class Candidate {
  final String name;
  int rank;

  Candidate(this.name, this.rank);
}

extension Extension on List<Candidate> {
  void sortCandidates() {
    if (this.isEmpty) return;
    var sorted = toSorted((a, b) => a.rank.compareTo(b.rank));
    for (int i = 0; i < length; i++) {
      this[i] = sorted[i];
    }
  }

  void bubbleSort() {
    bool swapped;
    do {
      swapped = false;
      for (var i = 0; i < length - 1; i++) {
        if (rankAt(i) > rankAt(i + 1)) {
          swapAt(i, i + 1);
          swapped = true;
        }
      }
    } while (swapped);
  }

  int? findCandidate(String targetName) {
    for (final candidate in this) {
      if (candidate.name == targetName) {
        return indexWhere((element) => element.name == targetName);
      }
    }
    return null;
  }

  void displayRankings() {
    for (var i = 0; i < length; i++) {
      print('$name at position $i');
    }
  }
}
