// Helper function to calculate the area of a triangle using Heron's formula
double triangleArea(double sideA, double sideB, double sideC) {
  final semiPerimeter = (sideA + sideB + sideC) / 2;
  return sqrt(semiPerimeter * 
             (semiPerimeter - sideA) *
             (semiPerimeter - sideB) *
             (semiPerimeter - sideC));
}

void main() {
  // Define three points for triangle vertices
  final point1 = [0.0, 0.0]; // Vertex A at origin
  final point2 = [4.0, 0.0]; // Vertex B on x-axis
  final point3 = [0.0, 3.0]; // Vertex C on y-axis

  // Calculate lengths of sides using Euclidean distance
  final abLength = sqrt(pow(point2[0] - point1[0], 2) + pow(point2[1] - point1[1], 2));
  final bcLength = sqrt(pow(point3[0] - point2[0], 2) + pow(point3[1] - point2[1], 2));
  final acLength = sqrt(pow(point3[0] - point1[0], 2) + pow(point3[1] - point1[1], 2));

  // Compute area using helper function
  final triangleAreaValue = triangleArea(abLength, bcLength, acLength);

  print('Triangle Area: $triangleAreaValue');
