  // Calculate the average of scores for each candidate.
  Map<String, double> calculateAverageScores() {
    return map((candidate) => (candidate.score ?? 0.0).toDouble()).fold(
          {},
          (acc, currentScore) {
            if (!acc.containsKey(candidate.name)) {
              acc[candidate.name] = currentScore;
            } else {
              acc[candidate.name] = acc[candidate.name]! + currentScore / 2;
            }
            return acc;
          },
        );
      }

  // Sort candidates by their score in descending order.
  void sortCandidatesByScoreDescending() {
    sort((a, b) => b.score!.compareTo(a.score!));
  }
}
