        final parts = instr.split(':', 2);
        final label = parts[0].trim();
        final inst = parts[1].trim();

        print("Label: $label");
        if (!inst.isEmpty) processInstruction(inst, i + 1);
      } else {
        processInstruction(instr, i + 1);
      }
    }
  }
}

void processInstruction(String inst, int address) {
  switch (inst.toLowerCase()) {
    case '.data':
      handleDataSection(address);
      break;
    default:
      parseOpcode(inst, address);
  }
}

void handleDataSection(int address) {
  stdout.write('.data\n');
  stdout.write('  .align 4\n');
  stdout.write('  .long 0\n');
}

void parseOpcode(String opCode, int address) {
  final tokens = opCode.split(' ');
  final opcode = tokens[0];

  switch (opcode) {
    case 'add':
      add(tokens, address);
      break;
    case 'sub':
      sub(tokens, address);
      break;
    case 'and':
      and(tokens, address);
      break;
    case 'or':
      or(tokens, address);
      break;
    case 'xor':
      xor(tokens, address);
      break;
    case 'mov':
      mov(tokens, address);
      break;
    case 'cmp':
      cmp(tokens, address);
      break;
    case 'jmp':
      jmp(tokens, address);
      break;
    case 'jeq':
      jeq(tokens, address);
      break;
    case 'jne':
      jne(tokens, address);
      break;
    case 'call':
      call(tokens, address);
      break;
    case 'ret':
      ret(tokens, address);
      break;
    case 'push':
      push(tokens, address);
      break;
    case 'pop':
      pop(tokens, address);
      break;
    case 'lea':
      lea(tokens, address);
      break;
    case 'brk':
      brk(tokens, address);
      break;
    case 'hlt':
      hlt(tokens, address);
      break;
    case 'sys':
      sys(tokens, address);
      break;
    case 'bge':
      bge(tokens, address);
      break;
    case 'blt':
      blt(tokens, address);
      break;
    case 'beq':
      beq(tokens, address);
      break;
    case 'bne':
      bne(tokens, address);
      break;
    default:
      throw Exception('Unknown operation: ${opCode}');
  }
}

