import 'package:vector_math/vector_math.dart';

class Candidate {
  final int id;
  final String name;
  final String party;
  double _votes;

  Candidate(this.id, this.name, this.party) : _votes = 0.0;

  void receiveVote() {
    _votes += 1.0;
  }

  bool operator ==(Object other) =>
      (other is Candidate && other.id == id);

  @override
  int get hashCode => id.hashCode;

  double get votes => _votes;
}

class Election {
  List<Candidate> candidates = [];

  void addCandidate(Candidate candidate) {
    candidates.add(candidate);
  }

  void countVotes(List<int> selections) {
    if (selections.length != candidates.length || selections.any((s) => s < 0)) return;

    for (int i = 0; i < candidates.length; i++) {
      candidates[i].receiveVote();
    }
  }

  // Returns the index of the winner.
  int determineWinner() {
    var maxVotes = -1;
    var winningIndex = -1;

    for (var i = 0; i < candidates.length; i++) {
      if (candidates[i].votes > maxVotes) {
        maxVotes = candidates[i].votes;
        winningIndex = i;
      }
    }
    return winningIndex;
  }

  // returns a list of candidates with their vote counts and percentages
  List<Map<String, dynamic>> getResults() {
    var results = [];

    for (var c in candidates) {
      var percent = ((c.votes / candidates.fold(0, (a, b) => a + b.votes)) * 100).toStringAsFixed(2);
      results.add({
        "name": c.name,
        "party": c.party,
        "votes": c.votes.toString(),
        "percent": "$percent%"
      });
    }
    return results;
  }
}
