  Candidate({required this.name, required this.age});

  @override
  String toString() => 'Candidate(name: $name, age: $age)';
}

void main() {
  // Sample data
  List<Candidate> candidates = [
    Candidate(name: "Alice", age: 30),
    Candidate(name: "Bob", age: 25),
    Candidate(name: "Charlie", age: 35),
    Candidate(name: "David", age: 40),
  ];

  print("Original list:");
  for (var candidate in candidates) {
    print(candidate);
  }

  // Shuffle the list using Fisher-Yates algorithm
  shuffleCandidates(candidates);

  print("\nShuffled list:");
  for (var candidate in candidates) {
    print(candidate);
  }
}

// Function to perform an in-place shuffle of a list of Candidates
void shuffleCandidates(List<Candidate> list) {
  Random random = Random();
  for (int i = list.length - 1; i > 0; i--) {
    int j = random.nextInt(i + 1); // Generate index between 0 and i inclusive
    // Swap elements at positions i and j
    var temp = list[i];
    list[i] = list[j];
    list[j] = temp;
  }
}
