extension Candidates on List<Candidate> {
  bool containsSameNameAs(Candidate other) {
    for (var candidate in this) {
      if (candidate.name == other.name) {
        return true;
      }
    }
    return false;
  }

  void addAllWithUniqueNames(Iterable<Candidate> others) {
    var seen = Set<String>();
    for (final other in others) {
      if (!seen.contains(other.name)) {
        add(other);
        seen.add(other.name);
      }
    }
  }

  void removeDuplicatesByName() {
    var seen = Set<String>();
    var filtered = <Candidate>[];
    for (var candidate in this) {
      if (!seen.contains(candidate.name)) {
        filtered.add(candidate);
        seen.add(candidate.name);
      }
    }
    clear();
    extend(filtered);
  }

  void sortByNameAndAge() {
    sort((a, b) {
      // First compare names
      final nameComparison = a.name.compareTo(b.name);
      if (nameComparison != 0) {
        return nameComparison;
      }
      // If names are equal, compare ages
      return a.age - b.age;
    });
  }

  void replaceIfOlder(int maxAge) {
    var i = 0;
    while (i < length) {
      if (this[i].age > maxAge) {
        removeAt(i);
      } else {
        ++i;
      }
    }
  }

  List<Candidate> filterByAgeRange(int minAge, int maxAge) {
    var result = <Candidate>[];
    for (var candidate in this) {
      if (candidate.age >= minAge && candidate.age <= maxAge) {
        result.add(candidate);
      }
    }
    return result;
  }

  int countCandidatesOverMinAge(int minAge) {
    int count = 0;
    for (var candidate in this) {
      if (candidate.age > minAge) {
        count++;
      }
    }
    return count;
  }

  double averageAge() {
    if (isEmpty) return 0.0;

    int totalAge = 0;
    for (var candidate in this) {
      totalAge += candidate.age;
    }
    return totalAge / length.toDouble();
  }

  Candidate? findYoungestCandidate() {
    if (isEmpty) return null;

    Candidate youngest = first;
    for (var candidate in skip(1)) {
      if (candidate.age < youngest.age) {
        youngest = candidate;
      }
    }
    return youngest;
  }

  Candidate? findOldestCandidate() {
    if (isEmpty) return null;

    Candidate oldest = first;
    for (var candidate in skip(1)) {
      if (candidate.age > oldest.age) {
        oldest = candidate;
      }
    }
    return oldest;
  }

  void mergeWith(List<Candidate> otherList) {
    var merged = toSet().union(otherList.toSet()).toList(growable: false);
    clear();
    addAll(merged);
  }

  void reverseOrder() {
