List<Candidate> calculateTopCandidates(List<Map<String, dynamic>> data) {
  // Sort the data by score in descending order and then alphabetically.
  List<Candidate> candidates = data.map((item) {
    return Candidate(
      name: item['name'] as String,
      score: (item['score'] as num).toInt(),
    );
  }).toList();

  candidates.sort((a, b) {
    if (a.score != b.score) {
      return b.score - a.score; // Descending order for scores
    } else {
      return a.name.compareTo(b.name); // Alphabetical order for tie-breaker
    }
  });

  // Return only the top candidate with highest score or all tied at top.
  var maxScore = candidates.isNotEmpty ? candidates[0].score : 0;
  List<Candidate> result = [];
  for (var candidate in candidates) {
    if (candidate.score == maxScore && result.isEmpty) {
      result.add(candidate);
    } else if (candidate.score < maxScore) {
      break;
    } else if (candidate.score == maxScore) {
      result.add(candidate);
    }
  }

  return result;
}
