import 'dart:math';

class Candidate {
  final int id;
  final String name;

  Candidate({required this.id, required this.name});

  factory Candidate.fromJson(Map<String, dynamic> json) {
    return Candidate(
      id: json['id'] as int,
      name: json['name'] as String,
    );
  }
}

abstract class ElectionResult {
  List<Candidate> get candidates;
  bool isTie();
  String toString();
}

class SimpleElectionResult implements ElectionResult {
  @override
  List<Candidate> get candidates => _candidates;

  final List<Candidate> _candidates;

  SimpleElectionResult(this._candidates);

  @override
  bool isTie() => false;

  @override
  String toString() {
    if (isTie()) {
      return "It's a tie between ${_candidates.map((c) => c.name).join(', ')}.";
    } else {
      var winner = _candidates.reduce((prev, curr) =>
          prev.votes > curr.votes ? prev : curr);
      return "${winner.name} wins with ${winner.votes} votes.";
    }
  }
}

class TiebreakerElectionResult extends SimpleElectionResult {
  TiebreakerElectionResult(List<Candidate> candidates) : super(candidates);

  @override
  bool isTie() {
    var first = candidates.firstWhere((e) => e.votes == maxVotes());
    for (var candidate in candidates) {
      if (candidate.votes != first.votes) return false;
    }
    return true;
  }

  int maxVotes() {
    return candidates.fold(0, (max, candidate) => max + candidate.votes);
  }
}
