      candidates[k].vote(); 
      candidates[k].vote();
    }

    var winner = candidates.reduce(maxByVote);
    print("Current leader is \$winner.name with \${winner.votes} votes.");
  } 

  print("\nFinal results:");
  for (final candidate in candidates)
    print("${candidate.name}: \t\${candidate.votes}");
}

// custom max by vote comparator
Candidate maxByVote(Candidate a, Candidate b) {
  return a.votes != null && b.votes != null ? a.votes! > b.votes! ? a : b :
         a.votes != null || b.votes != null ? a.votes! ?? b.votes! : a;
