import 'package:collection/collection.dart';

class Candidate {
  final String name;
  final int score;

  const Candidate({required this.name, required this.score});

  factory Candidate.fromJson(Map<String, dynamic> json) {
    return Candidate(
      name: json['name'] as String,
      score: json['score'] as int,
    );
  }
}

List<Candidate> parseCandidates(String input) {
  List<Map<String, dynamic>> candidatesData = [];

  // Split the input into lines and process each line
  for (final line in input.split('\n')) {
    if (line.trim().isNotEmpty && !line.startsWith('#') && 
        !line.contains('Candidate Name') && !line.contains('Score')) {
      try {
        Map<String, dynamic>? candidateMap = {};
        bool parsingName = true;
        String currentKey = '';

        for (final char in line.trim()) {
          if (char == ':') {
            parsingName = false;
            continue;
          } else if (parsingName) {
            currentKey += char;
          } else {
            candidateMap[currentKey] = int.tryParse(char) ?? char; // Handle both numbers and strings
          }
        }

        if (candidateMap != null && candidateMap.containsKey('name') && candidateMap.containsKey('score')) {
          candidatesData.add(candidateMap);
        }
      } catch (_) {}
    }
  }

  return candidatesData.map((data) => Candidate.fromJson(data)).toList();
}
