class Vote {
  final List<int> candidateIds; // list of integers representing the selected candidates in order
  final DateTime timestamp;

  const Vote(this.candidateIds, {required this.timestamp});
}

class VotingSystem {
  final Map<int, Candidate> _candidates = {};
  final List<Vote> _votes = [];

  void addCandidate(Candidate candidate) {
    if (_candidates.containsKey(candidate.id)) {
      throw StateError('A candidate with ID ${candidate.id} already exists.');
    }
    _candidates[candidate.id] = candidate;
  }

  void recordVote(List<int> candidateIds) {
    if (candidateIds.isEmpty || !candidateIds.every((id) => _candidates.containsKey(id))) {
      throw ArgumentError('Invalid candidate IDs provided for voting.');
    }
    _votes.add(Vote(candidateIds, timestamp: DateTime.now()));
  }

  Future<void> tallyVotes() async {
    // This method would typically interact with a database or API to store results.
    // For demonstration purposes, we'll just print them out.

    // Group votes by the number of candidates selected
    var voteCountsBySize = <int, int>{};
    for (var vote in _votes) {
      voteCountsBySize[vote.candidateIds.length] ??= 0;
      voteCountsBySize[vote.candidateIds.length]++;
    }

    // Process each group of votes based on the size
    for (final count in voteCountsBySize.entries) {
      final size = count.key;
      final total = count.value;
      print('Total votes where $size candidates were chosen: $total');
    }

    // If there are multiple rounds needed, handle accordingly
    while (_votes.isNotEmpty && !_votes.first.candidateIds.contains(_votes.last.candidateIds[0])) {
      // Simplified logic - actual implementation may vary
      await Future.delayed(Duration(seconds: 1));
    }
  }

  void displayCandidates() {
    for (var entry in _candidates.entries) {
      print('${entry.key}: ${entry.value.name}');
    }
  }
}
